INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (289, 'create', 'zero-decimal-system', 'The Concept of Zero', 'शून्य', 'The greatest invention ever made — a number for nothing', 'Mathematics & Astronomy', 'c. 5th – 7th c. CE', 'Aryabhata & Brahmagupta; rooted in earlier thought of Bhārat', 'Bhārat', NULL, NULL, 'CircleDot', 'from-[#4338CA] to-[#6366F1]', 'bg-indigo-50 text-indigo-700 border-indigo-200', 'text-indigo-600', 'Zero is the most brilliant and most elegant of all mathematical inventions.', 'The view of mathematicians worldwide', 'Without zero, there is no modern mathematics — and Bhārat gave the world zero. The ancient people of Bhārat developed the concept of shunya, \'emptiness\', as a real number, invented the decimal place-value system, and thereby made arithmetic, science, and computers possible.', '[\"Civilisations before Bhārat had symbols for \'nothing\' — a blank space, a dot — but Bhārat was the first to treat emptiness as a number in its own right, with its own arithmetic. The Sanskrit word shunya (\'void\') became the basis of the zero we use today, travelling to the Arab world as \'sifr\', which became our \'zero\' and \'cipher\'.\", \"The genius of the system is place value: the same digit \'2\' means two, twenty, or two hundred depending on its position. This decimal place-value system, perfected in Bhārat, turned arithmetic into a mechanical, almost effortless skill. a trader of Bhārat in 700 CE could multiply like a computer; a Roman could barely manage the abacus.\", \"The mathematician Brahmagupta (7th century CE) wrote the first rules for zero as a number: zero plus a number is that number, zero minus a number is its negative. Aryabhata (5th century) used the place-value system in his astronomy. Today, every computer on Earth runs on bits and bytes — and every bit is, at bottom, a debt to the concept of nothing of Bhārat that is something.\"]', '[{\"text\": \"The Sanskrit concept of emptiness raised to a working number.\", \"title\": \"Shunya\"}, {\"text\": \"The decimal system that made arithmetic fast and universal.\", \"title\": \"Place Value\"}, {\"text\": \"The first arithmetic of zero — adding, subtracting, even negatives.\", \"title\": \"Brahmagupta\'s Rules\"}, {\"text\": \"The word travelled from Bhārat through Arabia to Europe.\", \"title\": \"From Sifr to Zero\"}, {\"text\": \"Binary code and all modern computation rest on the zero.\", \"title\": \"The Computer\'s Debt\"}]', 'The zero is the foundation of every equation, every computer, every rocket trajectory. The scientist who \'discovered\' the Ramanujan number, the engineer coding an app — all of them stand on an invention of Bhārat about nothing. There is no greater gift from Bhārat to human thought.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (290, 'create', 'aryabhata-astronomy', 'Aryabhata\'s Astronomy', 'आर्यभट का खगोलशास्त्र', 'The 5th-century stargazer who knew the Earth spins', 'Mathematics & Astronomy', '476 – 550 CE', 'Aryabhata, of Kusumapura (Patna)', 'Bihar', NULL, NULL, 'Orbit', 'from-[#1E3A8A] to-[#3B82F6]', 'bg-blue-50 text-blue-700 border-blue-200', 'text-blue-600', 'The sphere of the stars is at rest; the Earth, turning on its axis, causes the rising and setting of the planets.', 'Aryabhata, Aryabhatiya (499 CE)', 'Fifteen hundred years ago, Aryabhata declared that the Earth rotates on its axis, explained eclipses as shadows rather than demons, and calculated the length of the year and the value of pi with astonishing accuracy. Bhārat named its first satellite after him.', '[\"Aryabhata was born around 476 CE and worked at Kusumapura, near modern Patna. At the age of 23 he composed the Aryabhatiya, a brilliant little book of mathematics and astronomy that laid out the decimal place-value system, solutions to quadratic equations, and a table of sines — five hundred years before these ideas reached Europe.\", \"His astronomy was breathtakingly modern: the Earth rotates on its axis, he said, which is why the stars appear to move — a claim Europe would not fully accept for a thousand years. He explained solar and lunar eclipses correctly, as shadows cast by the Moon and the Earth. He even calculated the length of the year as 365.3586 days — remarkably close to the true value.\", \"He computed pi to 3.1416 and gave an approximation accurate enough for most purposes. The modern space programme of Bhārat honoured him by naming its first satellite, launched in 1975, Aryabhata — a fitting tribute to the first person of Bhārat who truly understood the sky.\"]', '[{\"text\": \"He knew the Earth rotates on its axis, a millennium before Europe.\", \"title\": \"The Spinning Earth\"}, {\"text\": \"Shadows, not demons — a scientific account 1,500 years early.\", \"title\": \"Eclipses Explained\"}, {\"text\": \"A compact masterpiece of mathematics and astronomy.\", \"title\": \"The Aryabhatiya\"}, {\"text\": \"Pi to 3.1416 and a year-length accurate to hours.\", \"title\": \"Pi & The Year\"}, {\"text\": \"ISRO named its first spacecraft after him.\", \"title\": \"First Satellite of Bhārat\"}]', 'Aryabhata stands at the head of astronomy and mathematics of Bhārat — the man who made the sky a science. His name flies around the Earth daily, aboard Bhārat\'s first satellite and in the pride of every astronomer of Bhārat.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (291, 'create', 'ayurveda', 'Ayurveda', 'आयुर्वेद', 'The 5,000-year-old science of life — the world\'s oldest medicine', 'Medicine', 'c. 6th c. BCE, with roots 5,000 years old', 'Compiled by Charaka & Sushruta; wisdom of generations', 'Bhārat', NULL, NULL, 'Leaf', 'from-[#065F46] to-[#059669]', 'bg-emerald-50 text-emerald-700 border-emerald-200', 'text-emerald-600', 'The root of all healing is the balance of the three doshas; health is not merely the absence of disease.', 'Charaka Samhita', 'Ayurveda — \'the science of life\' — is the world\'s oldest continuously practised system of medicine. For five thousand years it has treated the whole person — body, mind, and spirit — through diet, herbs, yoga, and daily rhythm. Today, the world is rediscovering what Bhārat never forgot.', '[\"Ayurveda\'s roots reach into the ancient Vedas, and its classical form was fixed in the great compendiums — the Charaka Samhita on medicine and the Sushruta Samhita on surgery — written around 2,500 years ago. These texts are astonishingly systematic, with chapters on diagnosis, pharmacy, hygiene, and even medical ethics.\", \"Its core idea is the three doshas — vata, pitta, and kapha — the energies that govern the body. Health, Ayurveda teaches, is the balance of these doshas; disease is their disturbance. Treatment is personal: two people with the same illness may receive completely different medicines, because Ayurveda treats the person, not just the disease.\", \"Ayurveda\'s pharmacy is Bhārat\'s garden itself: turmeric, neem, ashwagandha, tulsi, and hundreds of herbs and preparations. In recent decades, modern laboratories have confirmed many of its claims — turmeric\'s curcumin, for instance, is now studied worldwide for its healing power. The World Health Organization recognises Ayurveda as a system of traditional medicine practised by millions.\"]', '[{\"text\": \"Vata, pitta, kapha — the energies whose balance is health.\", \"title\": \"The Three Doshas\"}, {\"text\": \"Medicine tailored to the individual, not just the illness.\", \"title\": \"Treat the Person\"}, {\"text\": \"Turmeric, neem, tulsi, ashwagandha — Bhārat\'s healing garden.\", \"title\": \"The Herbal Pharmacy\"}, {\"text\": \"Classical compendiums of medicine and surgery, 2,500 years old.\", \"title\": \"Charaka & Sushruta\"}, {\"text\": \"Daily rhythm, diet, and yoga — health as a way of life.\", \"title\": \"Prevention First\"}]', 'Ayurveda is Bhārat\'s oldest export — practised by millions in Bhārat and now embraced by wellness seekers worldwide. It is the original \'whole-person\' medicine, and its herbs are the ancestors of many modern drugs.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (292, 'create', 'sushruta-surgery', 'Sushruta\'s Surgery', 'शल्य चिकित्सा', 'The father of plastic surgery — 2,600 years ahead of his time', 'Medicine', 'c. 6th c. BCE', 'Sushruta, physician of Varanasi', 'Varanasi, Uttar Pradesh', NULL, NULL, 'Stethoscope', 'from-[#831843] to-[#DB2777]', 'bg-pink-50 text-pink-700 border-pink-200', 'text-pink-600', 'The surgeon who operates with confidence, cleanliness, and knowledge fears no failure.', 'Sushruta Samhita', 'Twenty-six centuries ago, in Varanasi, a physician named Sushruta was performing surgeries the modern world thought it had invented — including plastic surgery. His Sushruta Samhita describes 300 operations, 120 instruments, and techniques that surgeons use to this day.', '[\"Sushruta, often called the Father of Plastic Surgery, compiled the Sushruta Samhita around 600 BCE. The book describes over 300 surgical procedures and 120 surgical instruments — forceps, scalpels, needles, even a speculum — many of which have direct modern counterparts.\", \"His most famous operation is the forehead flap rhinoplasty: rebuilding a nose from a flap of cheek skin, a procedure performed for crimes and punishments of the era. When British surgeons learned of it in the 18th century, they called it the \'method of Bhārat\' — and it became the foundation of modern plastic surgery. Sushruta also performed cataract surgery, stone removal, and cesarean sections.\", \"He taught the principles that every surgeon still follows: cleanliness and hygiene, detailed training on models (he had students practise on gourds and animal skins), careful patient preparation, and gentle post-operative care. His students took a solemn oath to put the patient\'s welfare first — long before Hippocrates.\"]', '[{\"text\": \"Rhinoplasty via forehead flap — 2,600 years before the West.\", \"title\": \"The First Plastic Surgery\"}, {\"text\": \"A complete surgical toolkit, many designs still recognisable.\", \"title\": \"120 Instruments\"}, {\"text\": \"Cataract, stone, cesarean — an astonishing surgical catalogue.\", \"title\": \"300 Procedures\"}, {\"text\": \"Cleanliness and preparation — surgery\'s eternal rules.\", \"title\": \"Hygiene First\"}, {\"text\": \"Students trained on gourds and skins before touching patients.\", \"title\": \"Practice on Models\"}]', 'Sushruta\'s techniques became the \'method\' that founded of Bhārat Western plastic surgery. Every rhinoplasty, every careful surgeon\'s oath, owes something to a physician of Varanasi who operated two and a half millennia ago.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (293, 'create', 'chaturanga-chess', 'Chaturanga — the Original Chess', 'चतुरंग', 'The war game of Bhārat that became the world\'s favourite board', 'Games & Play', 'c. 6th c. CE', 'The Gupta Empire, Bhārat', 'North Bhārat', NULL, NULL, 'Crown', 'from-[#92400E] to-[#D97706]', 'bg-amber-50 text-amber-700 border-amber-200', 'text-amber-600', 'Chaturanga — a game of four divisions, born on the battlefields of the mind.', 'The meaning of the name', 'Chess began in Bhārat as chaturanga — \'four divisions\' — a war game of elephants, chariots, cavalry, and infantry played 1,500 years ago. From courts it travelled of Bhārat to Persia, the Arab world, and Europe, becoming the most played board game in history.', '[\"Chaturanga — from chatur (four) and anga (divisions) — was invented in Bhārat around the 6th century CE, modelling a four-limbed army: elephants, chariots, cavalry, and infantry. Each piece moved as its real counterpart did — elephants like today\'s bishops, chariots like rooks, horses like knights.\", \"The game spread along the trade routes. In Persia it became shatranj, in the Arab world it grew into a science of the mind, and in medieval Europe it evolved into the chess we know — with a queen who rules the board and castling and checkmate named after the Arabic \'shah mat\' (the king is dead).\", \"Bhārat\'s own versions still thrive: chaturanga variants in Kerala, and the circular Ashtapada boards mentioned in ancient texts. Today, chess is played by hundreds of millions, with world champions trained in Chennai — the city of Vishwanathan Anand, and now the global capital of chess.\"]', '[{\"text\": \"Elephants, chariots, cavalry, infantry — the original chess pieces.\", \"title\": \"Four Divisions\"}, {\"text\": \"From Bhārat to Persia, Arabia, and Europe — conquering the world.\", \"title\": \"The Silk Road Spread\"}, {\"text\": \"Even the word \'checkmate\' is an ancient Persian-phrase of Bhārat.\", \"title\": \"Shah Mat\"}, {\"text\": \"The Arab world called chess the game of kings and scholars.\", \"title\": \"A Science of the Mind\"}, {\"text\": \"Modern world champions train in the land where chess was born.\", \"title\": \"Back to Chennai\"}]', 'Every chess board on Earth is a battlefield of Bhārat. The game that began in Gupta Bhārat is now a global sport, a field of AI research, and proof that Bhārat\'s greatest export was sometimes just a board of sixty-four squares.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (294, 'create', 'moksha-patam', 'Moksha Patam — Snakes & Ladders', 'मोक्षपटम', 'The game of karma of Bhārat — ladders to virtue, snakes to vice', 'Games & Play', 'Ancient Bhārat — centuries old', 'Bhārat — a game of spiritual teaching', 'Bhārat', NULL, NULL, 'MoveUpRight', 'from-[#166534] to-[#22C55E]', 'bg-green-50 text-green-700 border-green-200', 'text-green-600', 'The game is a ladder of virtues and a snake of vices — every throw is a lesson.', 'The teaching of Moksha Patam', 'Long before it was a children\'s board game, Snakes & Ladders was a moral lesson of Bhārat: Moksha Patam, where ladders carried you up to heaven and snakes dragged you down to rebirth. Every square taught something — the game was invented to teach values.', '[\"Moksha Patam (the \'path of liberation\') was invented in Bhārat as a moral and spiritual teaching game. The board\'s squares represented virtues and vices: faith, generosity, and knowledge were ladders upward; greed, anger, and falsehood were snakes that pulled you down. The goal was moksha — liberation, at the top of the board.\", \"The ladders and snakes were not random: reaching a virtue square let you climb, landing on a vice square sent you sliding back. Children and adults alike learned that good actions lift you and bad actions drag you — a whole philosophy in a dice throw.\", \"British colonisers carried the game to England in the 19th century, where it became \'Snakes and Ladders\', with the moral squares stripped away. In 2010, the game returned home in spirit when researchers at Nalanda showed it had been played in Bhārat for centuries — the world\'s most famous moral lesson, disguised as a children\'s toy.\"]', '[{\"text\": \"Ladders of virtue, snakes of vice — a board game that taught ethics.\", \"title\": \"A Lesson in Karma\"}, {\"text\": \"Reaching the top meant liberation from the cycle of rebirth.\", \"title\": \"The Goal Is Moksha\"}, {\"text\": \"The virtues that carried a player upward.\", \"title\": \"Faith, Generosity, Truth\"}, {\"text\": \"The vices that sent players sliding back to the start.\", \"title\": \"Greed & Anger\"}, {\"text\": \"England turned it into \'Snakes and Ladders\' — keeping the board, losing the lesson.\", \"title\": \"The World\'s Toy\"}]', 'Moksha Patam survives in every child\'s Snakes & Ladders set worldwide. It is the only board game ever invented to teach the soul a lesson — and it conquered the world without anyone noticing the sermon.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (295, 'create', 'shampoo', 'Shampoo (Champu)', 'शैंपू', 'The head massage of Bhārat that gave the world a word', 'Everyday Inventions', '16th – 17th c. (carried to Europe in the 18th c.)', 'Bhārat\'s herbal champi tradition', 'Bhārat', NULL, NULL, 'Droplets', 'from-[#0E7490] to-[#22D3EE]', 'bg-cyan-50 text-cyan-700 border-cyan-200', 'text-cyan-600', 'Champi — a scalp massage with herbs, carried from Bhārat to the world.', 'The origin of the word \'shampoo\'', 'Every time you wash your hair, you say a word of Bhārat: shampoo comes from the Hindi champi — the traditional head and body massage with herbal oils. When British travellers returned from Bhārat, they brought back the practice and the word — and the modern hair-care industry was born.', '[\"For centuries, barbers and family of Bhārat elders performed champi — a vigorous massage of the scalp and body with herbal oils and infusions, made from soapberries (reetha), shikakai, and other plants. It was both hygiene and therapy, a daily ritual for healthy hair and a calm mind.\", \"When British traders and soldiers in 18th-century Bhārat experienced champi, they were fascinated. \'To shampoo\' entered the English language by the 1760s, meaning to massage; by the 19th century, European barbers offered \'shampooing\' as a service, and soap-makers created the first liquid hair cleansers — naming the whole product after the practice of Bhārat.\", \"Today the global shampoo industry is worth billions of dollars, and the word is spoken in almost every language on Earth — Turkish, Japanese, Swahili, and all of them trace back to champi. Meanwhile, companies like Wipro and Marico have carried the heritage full circle, with Ayurvedic shampoos sold worldwide.\"]', '[{\"text\": \"The herbal scalp massage that is part of daily life of Bhārat.\", \"title\": \"Champi\"}, {\"text\": \"\'Shampoo\' entered English in the 18th century from Hindi.\", \"title\": \"A Word That Travelled\"}, {\"text\": \"Bhārat\'s natural soaps — the original \'no-chemical\' hair care.\", \"title\": \"Reetha & Shikakai\"}, {\"text\": \"Champi was therapy, grooming, and relaxation in one.\", \"title\": \"Hygiene as Ritual\"}, {\"text\": \"Billions of dollars and every language now carry the word of Bhārat.\", \"title\": \"A Global Industry\"}]', 'Shampoo is the everyday proof of Bhārat\'s quiet influence: a word, a practice, and a product used by every human being on the planet — all born from a head massage in a courtyard of Bhārat.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (296, 'create', 'cotton-calico', 'Cotton & Calico', 'कपास', 'The Indus Valley cloth that clothed the world', 'Textiles', 'c. 2500 BCE — first cotton cultivation', 'The Indus Valley civilisation', 'Indus Valley (Bhārat & Pakistan)', NULL, NULL, 'Flower2', 'from-[#475569] to-[#94A3B8]', 'bg-slate-100 text-slate-700 border-slate-200', 'text-slate-600', 'A piece of calico, and the world was dressed in Bhārat\'s fields.', 'A tribute to the cotton trade', 'Bhārat was the first civilisation to grow cotton and weave it into cloth — 4,500 years ago in the Indus Valley. calico and muslin of Bhārat became the world\'s most prized fabrics, and the very words \'calico\' and \'cotton\' come from places and languages of Bhārat.', '[\"Archaeologists have found cotton threads and fabrics at Mohenjo-daro dating to around 2500 BCE — making the Indus Valley the world\'s first cotton civilisation. The plant itself was domesticated in Bhārat, and the Sanskrit name for cotton, karpasa, may be the ancestor of the word \'cotton\' itself.\", \"weavers produced marvels of Bhārat the world had never seen: calico, named after the port of Calicut (Kozhikode) in Kerala, and muslin, so fine that it was called \'woven air\'. Roman emperors paid in gold for cloth of Bhārat; the medieval world traded silver for it.\", \"The fame of cotton drove empires of Bhārat: European powers sailed to Bhārat precisely for its textiles, and the British East India Company built its fortune on them. The word \'calico\', \'chintz\' (from chhint, a painted fabric), and \'khaki\' (from khaki, \'dust-coloured\') all entered English from textile traditions of Bhārat.\"]', '[{\"text\": \"The Indus Valley grew and wove cotton 4,500 years ago.\", \"title\": \"First in Cotton\"}, {\"text\": \"Bengal muslin so fine it was legendary across the ancient world.\", \"title\": \"Woven Air\"}, {\"text\": \"Fabrics named after ports and Hindi words.\", \"title\": \"Calico & Chintz\"}, {\"text\": \"Europe\'s empires sailed to Bhārat for its cloth.\", \"title\": \"The Trade That Built Empires\"}, {\"text\": \"Bhārat\'s cotton soul — from Indus looms to Gandhi\'s spinning wheel.\", \"title\": \"Khadi\'s Ancestor\"}]', 'Bhārat\'s cotton dressed the ancient world and bankrolled the modern one. Every cotton shirt on Earth traces back to an Indus Valley field — and Gandhi\'s spinning wheel carried the story full circle.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (297, 'create', 'buttons', 'Buttons', 'बटन', 'An Indus Valley gift — the oldest buttons on Earth', 'Everyday Inventions', 'c. 2000 BCE', 'The Indus Valley civilisation', 'Mohenjo-daro, Indus Valley', NULL, NULL, 'Disc', 'from-[#6D28D9] to-[#8B5CF6]', 'bg-violet-50 text-violet-700 border-violet-200', 'text-violet-600', 'The world\'s first buttons were carved in the Indus Valley 4,000 years ago.', 'Archaeological record', 'The button — that tiny fastener on every shirt you own — was first made in the Indus Valley around 2000 BCE. Archaeologists at Mohenjo-daro found carved shell buttons, some in the shape of discs with holes, making Bhārat the birthplace of the world\'s most used fastener.', '[\"At Mohenjo-daro, one of the great cities of the Indus Valley civilisation, archaeologists found small discs of shell and stone, carved into shapes with two holes in the middle. These 4,000-year-old objects are the earliest known buttons in the world — likely used to fasten clothing or as ornaments.\", \"The word \'button\' itself comes from the French bouton, from bouter, \'to push\' — but the object\'s oldest home is Bhārat. While buttons became everyday fasteners in Europe only in the 13th century, the Indus Valley was crafting them two thousand years before Rome was founded.\", \"The Indus people were masters of small, precise manufacture — beads, seals, weights, and these tiny buttons made to standardised sizes, evidence of one of the world\'s first industrial traditions. A simple shell button from 2000 BCE tells us that even the smallest inventions have ancient of Bhārat pedigree.\"]', '[{\"text\": \"The world\'s earliest known buttons, found at Mohenjo-daro.\", \"title\": \"4,000 Years Old\"}, {\"text\": \"Carved discs with holes — the first fasteners.\", \"title\": \"Shell & Stone\"}, {\"text\": \"Made to uniform sizes — ancient mass production.\", \"title\": \"Standardised Craft\"}, {\"text\": \"The button on your collar began in the Indus Valley.\", \"title\": \"Every Shirt\'s Debt\"}, {\"text\": \"Bhārat\'s genius for precision in the smallest objects.\", \"title\": \"Small Wonders\"}]', 'Buttons are the most used fastener in human history — and they began in the Indus Valley. It is the perfect small proof of a big claim: so much of everyday modern life was first thought of in ancient Bhārat.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (298, 'create', 'isro-space', 'ISRO & the Space Programme', 'इसरो', 'The space agency that reached Mars on its first attempt', 'Modern Creations', '1969 – present', 'Founded by Dr. Vikram Sarabhai', 'Bengaluru, Karnataka', NULL, NULL, 'Rocket', 'from-[#1E1B4B] to-[#4F46E5]', 'bg-indigo-50 text-indigo-700 border-indigo-200', 'text-indigo-600', 'We must be second to none in the application of advanced technologies to the real problems of man and society.', 'Dr. Vikram Sarabhai, ISRO\'s founder', 'Bhārat\'s space agency ISRO is the world\'s most economical path to the stars — it reached Mars on its first attempt, found water on the Moon, and launched a record 104 satellites in a single mission. It is proof that a developing nation can lead the space age.', '[\"ISRO was founded in 1969 by Dr. Vikram Sarabhai, who believed space technology could solve Bhārat\'s earthly problems — communication, weather, education, and agriculture. From a humble start with bicycles carrying rocket parts in Kerala, ISRO has grown into one of the world\'s premier space agencies.\", \"Its record is dazzling: in 2008, Chandrayaan-1 discovered water molecules on the Moon; in 2013, Mangalyaan reached Mars on its very first attempt — a feat no other nation has matched; in 2017, a single PSLV rocket placed 104 satellites in orbit; and in 2023, Chandrayaan-3 made Bhārat the first nation to land near the Moon\'s south pole.\", \"ISRO does all this on a budget that is a fraction of NASA\'s — the Mars mission cost less than the film Gravity. Its technology serves people of Bhārat daily: satellites for farmers, fishermen, weather forecasters, and students; and its rockets, built in Bhārat, launch satellites for nations around the world.\"]', '[{\"text\": \"Mangalyaan reached Mars on its maiden attempt — a world first.\", \"title\": \"Mars on First Try\"}, {\"text\": \"Chandrayaan-3, the first spacecraft to land near the Moon\'s south pole.\", \"title\": \"South Pole Landing\"}, {\"text\": \"Chandrayaan-1\'s discovery that changed lunar science.\", \"title\": \"Water on the Moon\"}, {\"text\": \"A world record from a single rocket of Bhārat.\", \"title\": \"104 Satellites at Once\"}, {\"text\": \"Satellites for farmers, fishers, and schools — not just spectacles.\", \"title\": \"Space for the People\"}]', 'ISRO has made Bhārat the space pioneer of the developing world — proof that ambition, not budget, conquers the sky. From the cycling priests of Thumba to the moon\'s south pole, it is the modern creation every person of Bhārat is proudest of.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (299, 'create', 'cinema-of-bharat', 'cinema of Bhārat', 'भारतीय सिनेमा', 'From a silent epic to the largest film industry on Earth', 'Modern Creations', '1913 – present', 'Founded by Dadasaheb Phalke', 'Mumbai & film cities across Bhārat', NULL, NULL, 'Clapperboard', 'from-[#B45309] to-[#F59E0B]', 'bg-amber-50 text-amber-700 border-amber-200', 'text-amber-600', 'Let all the earth make way for the chariot of cinema of Bhārat.', 'A tribute to 100+ years of film of Bhārat', 'In 1913, Dadasaheb Phalke released Raja Harishchandra — Bhārat\'s first feature film — a silent epic shot with an all-cast of Bhārat. Over a century later, Bhārat produces more films than any nation on Earth, and its cinema — Bollywood, Tamil, Telugu, and more — is loved across the planet.', '[\"Dadasaheb Phalke, a magician-turned-filmmaker, was moved to make films after watching a silent movie about Christ. He travelled to London, bought a camera, and in 1913 released Raja Harishchandra — a silent retelling of a tale from the Mahabharata, shot entirely in Bhārat with actors of Bhārat. cinema of Bhārat was born.\", \"Through the decades it grew into a world of its own: the golden singing films of the 1940s and \'50s, the parallel cinema of Satyajit Ray, whose Pather Panchali won Cannes, the masala epics of the 1970s, and the global explosion of films today of Bhārat. Bhārat now makes between 1,500 and 2,000 films a year — more than any other country.\", \"cinema of Bhārat is not one industry but many: Bollywood in Mumbai, Tamil cinema in Chennai, Telugu cinema in Hyderabad, plus Malayalam, Kannada, Bengali, Marathi, and more. Together they reach billions of fans — and films like RRR, Dangal, and Baahubali have conquered screens from Japan to the United States.\"]', '[{\"text\": \"Raja Harishchandra — Bhārat\'s first feature film, by Dadasaheb Phalke.\", \"title\": \"Born in 1913\"}, {\"text\": \"More films made in Bhārat than anywhere else on Earth.\", \"title\": \"The World\'s Largest\"}, {\"text\": \"Bollywood, Tamil, Telugu, Malayalam, Bengali — a federation of dreams.\", \"title\": \"Many Cinemas, One Art\"}, {\"text\": \"Art-house masterpieces and global blockbusters side by side.\", \"title\": \"From Satyajit Ray to RRR\"}, {\"text\": \"films now dominate of Bhārat screens across Asia and the world.\", \"title\": \"Billions of Fans\"}]', 'cinema of Bhārat is the country\'s greatest modern creation — a dream factory watched by billions, winner of Oscars and Cannes awards, and the joyful proof that Bhārat tells stories like no one else on Earth.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (263, 'culture', 'diwali', 'Diwali', 'दिवाली', 'The festival of lights — a billion lamps against the dark', 'Festivals', 'Celebrated for over 2,000 years', 'The return of Lord Rama; celebrated by all Bhārat', 'Celebrated across Bhārat and the world', NULL, NULL, 'Flame', 'from-[#D97706] to-[#FBBF24]', 'bg-yellow-50 text-yellow-700 border-yellow-200', 'text-yellow-600', 'May the light of Diwali fill your home with joy and your heart with peace.', 'A traditional Diwali greeting', 'Diwali — Deepavali, the festival of lights — is Bhārat\'s most loved celebration. When millions of diyas (oil lamps) glow in every home, when rangoli colours the doorsteps and sweets fill the air, Bhārat is saying one thing: light always defeats darkness, and good always wins.', '[\"Diwali celebrates the return of Lord Rama to Ayodhya after fourteen years in exile and his victory over the demon king Ravana. The people of Ayodhya welcomed him by lighting rows of earthen lamps — diyas — and the tradition has burned brightly ever since, for over two thousand years.\", \"The festival runs for five days: Dhanteras opens it with prosperity; Naraka Chaturdashi (Chhoti Diwali) scrubs away evil; the main night of Diwali is given to Lakshmi, the goddess of wealth, with lamps in every corner; Govardhan Puja honours nature; and Bhai Dooj celebrates the bond of brothers and sisters.\", \"Diwali is a festival of the senses: the fragrance of marigolds and incense, the crackle of fireworks, the shimmer of new clothes, the exchange of sweets (mithai) and gifts. It is also a festival of the heart — of forgiving old quarrels, visiting family, and beginning anew. people of Bhārat worldwide — Hindu, Sikh, and Jain alike — light up the planet on this one magical night.\"]', '[{\"text\": \"Diyas in every window symbolise the victory of light over darkness.\", \"title\": \"Lamps Against Darkness\"}, {\"text\": \"The festival marks the homecoming of Lord Rama to Ayodhya.\", \"title\": \"Rama\'s Return\"}, {\"text\": \"The main night welcomes the goddess of wealth and good fortune.\", \"title\": \"Lakshmi Puja\"}, {\"text\": \"Coloured floor art and mithai — the delicious language of Diwali.\", \"title\": \"Rangoli & Sweets\"}, {\"text\": \"Celebrated by Hindus, Sikhs, and Jains across the world.\", \"title\": \"A Festival of All\"}]', 'Diwali is Bhārat\'s greatest cultural export — celebrated by communities from London to Singapore, and even marked in some world parliaments. It is the night when a billion people, and one planet, choose light.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (264, 'culture', 'holi', 'Holi', 'होली', 'The festival of colours — where Bhārat paints the spring', 'Festivals', 'Celebrated for centuries across Bhārat', 'The legends of Prahlad & Radha-Krishna', 'Celebrated across Bhārat and the world', NULL, NULL, 'Palette', 'from-[#BE123C] to-[#F97316]', 'bg-rose-50 text-rose-700 border-rose-200', 'text-rose-600', 'Bura na mano, Holi hai! — \'Don\'t be upset, it\'s Holi!\'', 'The classic Holi reply to being drenched in colour', 'Holi is the festival where all of Bhārat — and increasingly the world — throws caution to the wind and drenches each other in coloured powder and water. It is a celebration of spring, of good over evil, and of the beautiful chaos of joy.', '[\"The night before Holi, bonfires blaze across Bhārat for Holika Dahan, remembering the legend of Prahlad: a boy whose devotion saved him from the demoness Holika, proving that faith defeats evil. The next morning, the real festival begins — the streets erupt in gulal (coloured powder), water balloons, and laughter.\", \"The second legend of Holi is pure joy: young Krishna, playful and mischievous, complained to his mother that dark-skinned Radha might not love him. She suggested he simply colour Radha\'s face — and so Holi celebrates the playful, teasing love of Radha and Krishna, with colours that erase all differences.\", \"On Holi, barriers vanish: rich and poor, young and old, stranger and friend all become one rainbow. People throw colours, dance to dhol drums, share gujiya and thandai, and end the day with visits to family. In recent decades, \'Festivals of Holi\' have spread to cities across Europe and America.\"]', '[{\"text\": \"A city-wide riot of coloured powder and joyful chaos.\", \"title\": \"Gulal & Colour\"}, {\"text\": \"Bonfires the night before — good defeating evil.\", \"title\": \"Holika Dahan\"}, {\"text\": \"The playful legend of Krishna colouring Radha\'s face.\", \"title\": \"Radha & Krishna\"}, {\"text\": \"Age, caste, and rank vanish for one day of equality.\", \"title\": \"No Barriers\"}, {\"text\": \"Gujiya, malpuas, and thandai — the sweets of spring.\", \"title\": \"The Holi Feast\"}]', 'Holi has become one of the world\'s favourite festivals — a global celebration of colour and spring. It shows the world Bhārat\'s gift: the ability to turn joy itself into a national holiday.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (265, 'culture', 'navaratri-durga-puja', 'Navaratri & Durga Puja', 'नवरात्रि', 'Nine nights of the Goddess — dance, drums, and devotion', 'Festivals', 'Ancient — celebrated for over a millennium', 'The worship of Goddess Durga & Shakti', 'Pan-Bhārat — grandest in Bengal, Gujarat & South Bhārat', NULL, NULL, 'Drum', 'from-[#7C3AED] to-[#C026D3]', 'bg-violet-50 text-violet-700 border-violet-200', 'text-violet-600', 'Ya Devi Sarvabhuteshu Shakti Rupena Samsthita — \'She who dwells in all beings as power, salutations to her.\'', 'The Durga Saptashati', 'For nine nights, Bhārat worships the Goddess in all her power — and then explodes into celebration. Navaratri means dandiya and garba in Gujarat, Durga Puja pandals in Bengal, and nine nights of devotion across the South. It is the festival of Shakti — divine feminine energy.', '[\"Navaratri — \'nine nights\' — honours the Goddess Durga in her nine forms, from the fierce Kali to the gentle Saraswati. The tenth day, Vijayadashami or Dussehra, celebrates her victory over the buffalo demon Mahishasura — and, in the North, the victory of Lord Rama over Ravana, whose effigies burn in grand pyres.\", \"In Gujarat, Navaratri becomes the world\'s longest dance festival: every night, thousands swirl in the circles of garba and strike dandiya sticks in rhythm, wearing mirror-work chaniya cholis under strings of lights. In Bengal, Durga Puja transforms Kolkata into a city of art — towering pandals (temporary temples) are built, themed and decorated, and the goddess is worshipped for four days before her idol is immersed in the river.\", \"In the South, Navaratri is a festival of music and dolls — homes display intricate golu arrangements of miniature figures, and classical music concerts honour Saraswati, the goddess of learning, on Saraswati Puja day. One festival, a thousand ways to celebrate — but always the same goddess of power and creativity.\"]', '[{\"text\": \"Nine nights honouring Durga\'s nine divine forms.\", \"title\": \"Nine Forms of the Goddess\"}, {\"text\": \"Gujarat\'s nightly swirl of sticks, circles, and mirror-work.\", \"title\": \"Dandiya & Garba\"}, {\"text\": \"Kolkata\'s colossal art temples, immersed in the river at the end.\", \"title\": \"Durga Puja Pandals\"}, {\"text\": \"The tenth day — victory of good, when Ravana\'s effigies burn.\", \"title\": \"Vijayadashami\"}, {\"text\": \"The South\'s day for books, music, and the goddess of knowledge.\", \"title\": \"Saraswati & Learning\"}]', 'Navaratri is Bhārat\'s grandest theatre of faith — where art, dance, music, and devotion fuse into one festival. It is also the world\'s largest celebration of the feminine divine.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (266, 'culture', 'bharatanatyam', 'Bharatanatyam', 'भरतनाट्यम', 'The oldest classical dance — two thousand years of stories in movement', 'Classical Dance', 'c. 2,000 years old', 'Rooted in the Natya Shastra of Bharata Muni', 'Tamil Nadu', NULL, NULL, 'Music', 'from-[#BE123C] to-[#F43F5E]', 'bg-rose-50 text-rose-700 border-rose-200', 'text-rose-600', 'Where the hand moves, the eyes follow; where the eyes go, the mind follows.', 'The Natya Shastra', 'Bharatanatyam is the oldest of Bhārat\'s classical dances — a two-thousand-year-old language of the body that tells the stories of gods, heroes, and lovers. With anklets of bells, arched feet, and expressive eyes, its dancers turn the human body into poetry.', '[\"Bharatanatyam traces its roots to the Natya Shastra, the ancient treatise on performing arts attributed to the sage Bharata, written perhaps two thousand years ago. It flowered in the temples of Tamil Nadu, where devadasis — women dedicated to the temple — performed it as a form of worship.\", \"The dance is built on extraordinary discipline: the legs form a deep araimandi (half-seated posture), the feet stamp in precise rhythms to the mridangam, and the hands speak in mudras — codified gestures with over a hundred meanings. Every eyebrow, every glance, every bell-ring has grammar.\", \"A Bharatanatyam recital follows a classical structure: the alarippu (pure invocation), the jatiswaram (pure rhythm), the varnam (the heart — story and rhythm woven), and the tillana (a joyful finale). Today it is performed on world stages, taught in academies from Chennai to California, and remains the very symbol of classical arts of Bhārat.\"]', '[{\"text\": \"A codified vocabulary of hand gestures that can speak entire stories.\", \"title\": \"Mudras\"}, {\"text\": \"The deep, powerful half-seated posture that gives the dance its strength.\", \"title\": \"Araimandi\"}, {\"text\": \"Born as worship in the temples of Tamil Nadu.\", \"title\": \"Temple Roots\"}, {\"text\": \"The art of expression — eyes, face, and emotion in perfect sync.\", \"title\": \"Abhinaya\"}, {\"text\": \"Ghungroos that turn every stamp into music.\", \"title\": \"The Bell-Anklets\"}]', 'Bharatanatyam is the mother of the classical tradition — UNESCO-listed, danced on every continent, and still taught with the same rigor it had in the temple courtyards of Tamil Nadu two millennia ago.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (267, 'culture', 'kathak', 'Kathak', 'कथक', 'The storyteller\'s dance — spins, bells, and the courts of emperors', 'Classical Dance', 'c. 2,000 years old; refined in Mughal courts', 'Wandering kathakars (storytellers) of North Bhārat', 'North Bhārat — Lucknow, Jaipur & Benaras gharanas', NULL, NULL, 'Footprints', 'from-[#9A3412] to-[#EA580C]', 'bg-orange-50 text-orange-700 border-orange-200', 'text-orange-600', 'The dancer spins, and the universe spins with her.', 'A tribute to Kathak\'s chakkars', 'Kathak began as the dance of wandering storytellers who acted out the epics with song and gesture — and grew into the glittering court dance of Lucknow and Jaipur, famous for lightning-fast spins, complex footwork, and the thunder of a hundred ankle bells.', '[\"The word kathak comes from katha — \'story\'. Its earliest performers, the kathakars, travelled North Bhārat reciting and acting the Mahabharata and Ramayana. Over centuries, the art absorbed Persian and Mughal influence, moving from temple courtyards into the durbar — where emperors applauded its grace.\", \"Kathak is famous for two things above all: the chakkar, the rapid spin that can blur a dancer into a whirl of colour, and the tatkar, footwork so precise that the dancer\'s bells — ghungroos, sometimes 200 of them per ankle — ring out rhythms like a drum. The dancer becomes percussion, singer, and story at once.\", \"It developed three great gharanas (schools): Lucknow, known for its grace and abhinaya; Jaipur, for its technical fireworks; and Benaras, for its earthy vigour. Today, from Bollywood choreography to world festivals, Kathak\'s spins are among the most recognised movements in dance of Bhārat.\"]', '[{\"text\": \"Born as katha — recited, acted, and danced epics.\", \"title\": \"The Storytellers\"}, {\"text\": \"Blurring spins that are Kathak\'s signature.\", \"title\": \"Chakkars\"}, {\"text\": \"Footwork so rhythmic the dancer plays the drum with her feet.\", \"title\": \"Ghungroo Percussion\"}, {\"text\": \"Lucknow, Jaipur, and Benaras — three schools, three flavours.\", \"title\": \"Three Gharanas\"}, {\"text\": \"From Mughal durbar to the world\'s festival stages.\", \"title\": \"Court to Stage\"}]', 'Kathak is North Bhārat\'s gift to the classical world — a dance of both devotion and dazzle, still spinning its stories after two thousand years.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (268, 'culture', 'kathakali', 'Kathakali', 'कथाकली', 'Kerala\'s painted gods — a dance-drama in full war-paint', 'Classical Dance', 'c. 400 years old (17th c. Kerala)', 'The royal courts of Kerala', 'Kerala', NULL, NULL, 'Theater', 'from-[#14532D] to-[#16A34A]', 'bg-green-50 text-green-700 border-green-200', 'text-green-600', 'Kathakali is not a dance to be watched — it is a world to be entered.', 'Lovers of Kerala\'s theatre', 'Kathakali is the most theatrical of Bhārat\'s classical arts — a dance-drama where performers wear towering crowns, painted faces, and billowing skirts, and tell stories with their eyes alone. For hours, a single gaze can be the entire story of the Mahabharata.', '[\"Kathakali was born in 17th-century Kerala as a court art combining dance, music, and drama. Its performers are trained for years in a discipline that includes chavittu adi (stamping footwork) and the terrifying daily eye exercises that let a dancer hold a single expression — joy, fury, love — for minutes on end.\", \"Every element is oversized: the makeup (vesham) takes hours to apply, with green for heroes, red-black for demons, and yellow for women; the elaborate crowns and stiff skirts make the performer look twice human size; and the singer (the \'vocalist\') narrates the story while drummers pound the chenda and maddalam.\", \"A Kathakali performance traditionally begins at night and can run until dawn, re-enacting episodes from the Ramayana and Mahabharata. There are no spoken lines — the entire story is told through mudras (hand gestures) and the nine emotions (navarasa) of the face. It is opera, ballet, and silent film in one.\"]', '[{\"text\": \"Hours of makeup — green for heroes, black-red for demons.\", \"title\": \"The Painted Face\"}, {\"text\": \"Mudras plus eye-work alone tell stories that can last all night.\", \"title\": \"The Eyes Have It\"}, {\"text\": \"Towering crowns and skirts make gods loom larger than life.\", \"title\": \"Oversized Theatre\"}, {\"text\": \"Traditional shows begin at night and end as the sun rises.\", \"title\": \"Dawn Performances\"}, {\"text\": \"Kerala\'s thunderous drums drive the drama.\", \"title\": \"The Chenda\"}]', 'Kathakali is one of the world\'s great theatrical traditions — a Kerala art so bold that it has been performed from Edinburgh to Tokyo. It proves that storytelling stops at nothing, not even the size of the stage.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (269, 'culture', 'classical-music-of-bharat', 'classical music of Bhārat', 'शास्त्रीय संगीत', 'Raga and tala — the mathematics of the soul, in sound', 'Music & Arts', 'c. 3,000 years old (roots in the Samaveda)', 'The sages of the Samaveda; two living systems today', 'Hindustani (North) & Carnatic (South) traditions', NULL, NULL, 'Music2', 'from-[#1E40AF] to-[#3B82F6]', 'bg-indigo-50 text-indigo-700 border-indigo-200', 'text-indigo-600', 'Music is the speech of angels; the raga is its grammar.', 'A tribute to the classical tradition', 'classical music of Bhārat is one of the world\'s oldest continuous musical systems — a universe built on raga (melody) and tala (rhythm) where a single evening can unfold one raga for hours. It lives in two great streams: Hindustani in the North, Carnatic in the South.', '[\"Its roots reach into the Samaveda, one of the four ancient Vedas, whose chants are considered the origin of melody of Bhārat. Over millennia, the tradition crystallised into ragas — precise melodic frameworks, each tied to a time of day, a season, and a mood. Dawn, noon, and midnight each have their own raga, and a master musician knows their language perfectly.\", \"Two streams flowered: Hindustani music of the North, enriched by Persian influence and the courts of Delhi, famous for the sitar, sarod, and tabla, and Carnatic music of the South, temple-born and intricately rhythmic, with the veena, mridangam, and violin. Both share the same ancient foundation — yet each sounds utterly itself.\", \"There is no \'piece\' to memorise in classical music — there is improvisation within a raga, unfolding like a flower: the slow, searching alap, the gradual rhythm, and finally the lightning improvisations. This is why a concert can last three hours and never repeat itself — every performance is being composed, live, for the first time.\"]', '[{\"text\": \"Melodic frameworks with their own seasons, hours, and moods.\", \"title\": \"Raga\"}, {\"text\": \"Rhythmic cycles of astonishing mathematical intricacy.\", \"title\": \"Tala\"}, {\"text\": \"Two living systems — North and South — from one ancient root.\", \"title\": \"Hindustani & Carnatic\"}, {\"text\": \"Every concert is improvised within the raga — never repeated.\", \"title\": \"Live Composition\"}, {\"text\": \"Sitar, sarod, tabla; veena, mridangam, violin.\", \"title\": \"The Instruments\"}]', 'classical music of Bhārat has inspired the Beatles, jazz musicians, and film scores worldwide. UNESCO recognises it as part of the world\'s intangible cultural heritage — a 3,000-year-old stream that still flows through every home of Bhārat.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (270, 'culture', 'madhubani-painting', 'Madhubani Painting', 'मधुबनी चित्रकला', 'Bihar\'s wall of wonder — painted with fingers, twigs, and natural dye', 'Folk Art', 'Practised for centuries; discovered by the world in 1930s', 'The women of Mithila, Bihar', 'Mithila region, Bihar', NULL, NULL, 'Paintbrush', 'from-[#991B1B] to-[#DC2626]', 'bg-red-50 text-red-700 border-red-200', 'text-red-600', 'A Madhubani wall is a prayer written in colour.', 'Mithila\'s artists', 'In the villages of Mithila in Bihar, women have painted their walls and floors for centuries — covering mud homes with gods, fish, peacocks, and sacred symbols, using fingers, twigs, and dyes made from flowers and soot. Madhubani art went from village walls to the world\'s museums.', '[\"Madhubani (or Mithila) painting was born as ritual wall art: during weddings and festivals, women of Mithila decorated the mud walls and floors of their homes with paintings of gods, sun and moon, fish, turtles, and peacocks — each symbol rich with meaning of fertility, protection, and prosperity.\", \"The art is unique in its tools: there are no brushes. Artists use fingers, twigs, matchsticks, and even nibs, drawing bold outlines filled with dense geometric patterns — dots, lines, and flowers — in colours made from rice paste, turmeric, flowers, and lampblack.\", \"The world \'discovered\' Madhubani in the 1930s, after a severe earthquake, when British officials noticed the dazzling walls. Artists moved the paintings from walls to paper, and today Madhubani is one of Bhārat\'s most celebrated art forms — exhibited globally and a major source of livelihood for thousands of Mithila women.\"]', '[{\"text\": \"Painted with fingers, twigs, and matchsticks.\", \"title\": \"No Brushes\"}, {\"text\": \"Colours from rice paste, turmeric, flowers, and soot.\", \"title\": \"Natural Dyes\"}, {\"text\": \"An art of ritual and identity carried by village women.\", \"title\": \"The Women of Mithila\"}, {\"text\": \"Fish, peacocks, sun, and moon — a language of auspiciousness.\", \"title\": \"Sacred Symbols\"}, {\"text\": \"Village walls now hang in museums across the planet.\", \"title\": \"From Wall to World\"}]', 'Madhubani is the pride of Bihar and a UNESCO-listed craft tradition. It turned the hidden art of village women into a global phenomenon — proof that the greatest art often starts of Bhārat on a mud wall.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (271, 'culture', 'warli-art', 'Warli Art', 'वारली चित्रकला', 'Maharashtra\'s white-on-mud stick figures — 3,000 years old', 'Folk Art', 'c. 3,000 years old', 'The Warli tribe of Maharashtra', 'Palghar district, Maharashtra', NULL, NULL, 'Brush', 'from-[#78350F] to-[#B45309]', 'bg-amber-50 text-amber-800 border-amber-200', 'text-amber-700', 'The circle is the sun, the triangle the mountain, the square the sacred space.', 'The geometry of Warli art', 'For three thousand years, the Warli tribe of Maharashtra has painted its walls in a deceptively simple style: white stick figures and circles on mud-brown walls, depicting dance, harvest, and daily life. It is one of the oldest and purest art forms on Earth.', '[\"Warli art is drawn on the walls of village huts with a paste of rice flour and water, in stark white on mud-brown. Its entire vocabulary is geometry: the circle is the sun and moon, the triangle is mountains and trees, the square is the sacred chaukat, the ritual space where gods are invoked.\", \"The art\'s most famous figure is the tarpa dancer: a ring of humans, all linked in a circle, dancing around a tarpa player. These human figures — two triangles for a body, circles for heads — capture the joy of community life, harvests, weddings, and festivals with astonishing economy.\", \"Once purely ritual (painted on the chaukat walls for weddings), Warli has been rediscovered by the design world: it now adorns fabric, pottery, and gallery canvases. Yet its heart remains the same — a people drawing their own world with rice paste and geometry.\"]', '[{\"text\": \"Rice-paste figures drawn on dark mud walls.\", \"title\": \"White on Mud\"}, {\"text\": \"Circle, triangle, and square — the entire universe in three shapes.\", \"title\": \"Sacred Geometry\"}, {\"text\": \"The famous ring of dancers — community itself, drawn in a circle.\", \"title\": \"The Tarpa Dance\"}, {\"text\": \"One of the world\'s oldest continuously practised art traditions.\", \"title\": \"3,000 Years Old\"}, {\"text\": \"Harvests, weddings, and daily life in a language of pure line.\", \"title\": \"Village Life\"}]', 'Warli art has gone from village walls to international galleries and design studios. It is living proof that some of Bhārat\'s oldest art needs nothing more than rice paste, a wall, and a steady hand.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (272, 'culture', 'handloom-saree', 'Handloom & the Saree', 'हथकरघा और साड़ी', 'Six yards of silk and thread — Bhārat\'s wearable masterpiece', 'Crafts & Weaves', 'Saree\'s origins over 2,000 years ago', 'Bhārat\'s weavers, village by village', 'Weaving clusters across Bhārat', NULL, NULL, 'Shirt', 'from-[#134E4A] to-[#0D9488]', 'bg-teal-50 text-teal-700 border-teal-200', 'text-teal-600', 'The saree is not just a garment; it is a memory woven on a loom.', 'Bhārat\'s weavers', 'The saree — six yards of unstitched cloth — is one of Bhārat\'s greatest works of art, and the handloom is its living loom. From the gold thread of Banarasi to the temple borders of Kanjeevaram, every weaver\'s village of Bhārat has its own masterpiece.', '[\"The saree is ancient — worn for over two thousand years, referenced in Sanskrit and Tamil literature, draped in a hundred different regional styles: the Nivi of Andhra, the seedha pallu of Gujarat, the Coorgi of Karnataka. Unstitched and timeless, it is perhaps the oldest surviving garment style on Earth.\", \"Behind every saree stands the handloom — a wooden frame where fingers, not machines, set thousands of threads. The craft reached its peak in the silk of Kanjeevaram, the brocade of Banaras, the muslin of Bengal, the ikat of Odisha, and the Chanderi of Madhya Pradesh — each weave a distinct language of pattern, colour, and pride.\", \"textiles were once of Bhārat the world\'s most sought-after luxury — Roman senators complained that silk was bankrupting of Bhārat Rome. Today, the handloom supports millions of weaver families, and the saree remains the garment of every celebration of Bhārat — wedding, festival, and office alike.\"]', '[{\"text\": \"An unstitched garment — a single length of woven cloth, worn a hundred ways.\", \"title\": \"Six Yards, No Seams\"}, {\"text\": \"Silk brocade woven with real gold thread.\", \"title\": \"Banarasi Gold\"}, {\"text\": \"Temple designs and rich silks of Tamil Nadu.\", \"title\": \"Kanjeevaram Borders\"}, {\"text\": \"Every thread set by hand — a machine cannot make a true Banarasi.\", \"title\": \"The Human Loom\"}, {\"text\": \"Roman senators once paid a fortune for cloth of Bhārat.\", \"title\": \"Luxury of the Ancient World\"}]', 'The handloom saree is Bhārat\'s oldest industry and newest pride — UNESCO-listed as intangible heritage, worn by every bride and celebrated on National Handloom Day. It is a garment that carries six yards of genius of Bhārat.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (273, 'culture', 'cuisine-of-bharat', 'cuisine of Bhārat', 'भारतीय व्यंजन', 'The spice trail — a thousand regional kitchens in one land', 'Cuisines', 'The spice trade is over 4,000 years old', 'Every region\'s grandmothers and tandoor masters', 'Every state of Bhārat', NULL, NULL, 'ChefHat', 'from-[#C2410C] to-[#F97316]', 'bg-orange-50 text-orange-700 border-orange-200', 'text-orange-600', 'cooking is an alchemy of Bhārat — of spice, fired in a clay oven of centuries.', 'A tribute to the kitchen of Bhārat', 'food is not one cuisine of Bhārat but a hundred — from the fire of a tandoor in Punjab to the coconut rivers of Kerala, from street chaat to the endless courses of a royal thali. It is the cuisine that conquered the world, one spice at a time.', '[\"Bhārat\'s love affair with food began over 4,000 years ago with the spice trade — pepper, cardamom, and cinnamon made ports the richest of Bhārat in the ancient world. The Roman empire, and later Europe, waged trade wars for the taste of Malabar pepper. Today, curry is the world\'s most beloved dish.\", \"Every region cooks a different Bhārat: the tandoor and butter chicken of the North, the idli and dosa of the South, the fish curries of Bengal, the dhokla and thepla of Gujarat, the thukpa of the Himalayas. A single thali — a platter of small dishes — can carry half a dozen kitchens at once.\", \"The secret of food of Bhārat is the art of tempering — tarka — spices sizzled in hot oil or ghee, releasing flavours that no other cuisine matches. Vegetarian or not, sweet or fierce, every meal of Bhārat ends with the same ritual: the sharing of food, which in Bhārat is the sharing of love.\"]', '[{\"text\": \"spices built the ancient world\'s richest trade routes.\", \"title\": \"The Spice Trail\"}, {\"text\": \"The clay oven of the North that bakes naan and burns like a star.\", \"title\": \"The Tandoor\"}, {\"text\": \"Regional cuisines from the Himalayas to the coconut coasts.\", \"title\": \"A Hundred Kitchens\"}, {\"text\": \"The tempering of spices in hot ghee — Bhārat\'s flavour secret.\", \"title\": \"Tarka\"}, {\"text\": \"A platter of small dishes — a whole region on one plate.\", \"title\": \"The Thali\"}]', 'cuisine of Bhārat is one of the world\'s great cultural exports — curry houses on every continent, spices in every kitchen, and a tradition of sharing that feeds the soul as much as the body.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (274, 'culture', 'rangoli', 'Rangoli', 'रांगोली', 'Colourful floor art that welcomes every doorstep', 'Folk Art', 'Practised for over 1,500 years', 'The women of every home of Bhārat', 'Pan-Bhārat — kolam in Tamil Nadu, muggu in Telangana', NULL, NULL, 'Flower', 'from-[#A21CAF] to-[#EC4899]', 'bg-pink-50 text-pink-700 border-pink-200', 'text-pink-600', 'A rangoli is a greeting drawn on the earth, an invitation to joy.', 'A tribute to the doorstep art', 'Before every home of Bhārat, at dawn and festival time, a carpet of colour appears: rangoli — floor art drawn with coloured powder, rice, and flower petals. It is Bhārat\'s way of saying the doorstep itself is sacred, and the guest is divine.', '[\"Rangoli comes from the Sanskrit rangavalli — \'a garland of colours\'. Drawn on the ground at entrances, it is both decoration and ritual: the patterns welcome Lakshmi, the goddess of prosperity, keep away evil, and turn an ordinary doorstep into a work of art.\", \"Every region draws it differently: in Tamil Nadu it is the kolam, drawn with rice flour in fine geometric grids to feed ants and birds (and welcome them home); in Telangana it is the muggu; in Maharashtra and the North, the festival rangoli blazes with five-coloured powders, flowers, and even diyas.\", \"The art needs almost nothing — fingers, powder, and imagination. Yet its symmetries are astonishing: peacocks, lotus, lamps, and intricate dots-and-lines patterns passed down from mother to daughter for generations. During Diwali and Pongal, entire streets compete to draw the most beautiful welcome.\"]', '[{\"text\": \"Coloured powders, rice flour, and flower petals — nothing more.\", \"title\": \"Powder & Petals\"}, {\"text\": \"The South\'s fine rice-flour grids — also a meal for ants and birds.\", \"title\": \"Kolam\"}, {\"text\": \"Patterns that invite prosperity into the home.\", \"title\": \"Welcome to Lakshmi\"}, {\"text\": \"Symmetries taught mother to daughter for generations.\", \"title\": \"Passed Down\"}, {\"text\": \"At Diwali, whole streets compete in the art of welcome.\", \"title\": \"Festival Competitions\"}]', 'Rangoli is Bhārat\'s most democratic art — no canvas, no cost, no gallery, just powder on the ground and joy at the doorstep. It survives in every home and now of Bhārat inspires designers worldwide.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (275, 'culture', 'turban', 'The Turban', 'पगड़ी', 'The crown of the common man — ten metres of honour', 'Attire', 'Worn for over 2,000 years', 'Worn by kings, farmers, and warriors alike', 'Rajasthan, Punjab & across Bhārat', NULL, NULL, 'Crown', 'from-[#B45309] to-[#F59E0B]', 'bg-amber-50 text-amber-700 border-amber-200', 'text-amber-600', 'The turban is the crown of the common man.', 'A tribute to the pagdi', 'The turban — pagdi, safa, or dastar — is Bhārat\'s headwear of honour, tied fresh each morning from metres of cloth. From the rulers of Rajasthan to the farmers of Punjab, it is a living symbol of dignity, pride, and identity.', '[\"The turban is one of Bhārat\'s oldest garments — a draped headdress shown on Indus Valley seals thousands of years old and worn by kings, warriors, and sages ever since. In Rajasthan, presenting your own turban to a guest is considered the highest mark of respect a host can offer.\", \"Bhārat ties a hundred different turbans: the Rajasthani safa with its flaring tail, the Mysore peta of Karnataka, the tall Nihang dastar of Punjab, and the folded styles of every region in between. The colour and style of a turban can announce a man\'s region, his family, even the festival being celebrated.\", \"For Sikhs, the dastar is a sacred article of faith — worn with pride, never removed in public. Today, turbans are seen at weddings, in offices, and on soldiers\' heads, and turban-tying has become a beloved craft taught at schools and museums across Bhārat.\"]', '[{\"text\": \"Giving your turban to a guest is the highest mark of respect.\", \"title\": \"Honour in Cloth\"}, {\"text\": \"Safa, peta, dastar — every region ties it differently.\", \"title\": \"A Hundred Styles\"}, {\"text\": \"A sacred article of faith, worn with pride.\", \"title\": \"The Sikh Dastar\"}, {\"text\": \"Draped headdresses appear on ancient Indus Valley seals.\", \"title\": \"Old as the Indus\"}, {\"text\": \"Turban-tying is celebrated at schools and festivals today.\", \"title\": \"A Living Craft\"}]', 'The turban is Bhārat\'s everyday crown — a symbol that dignity does not come from gold but from how a man carries himself. It is honour, identity, and faith, folded into ten metres of cloth.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (276, 'culture', 'dhoti-kurta', 'Dhoti & Kurta', 'धोती-कुर्ता', 'Five yards of cloth and a tunic — the timeless dress of men of Bhārat', 'Attire', 'Worn for millennia', 'The everyday cloth of men for centuries of Bhārat', 'Pan-Bhārat', NULL, NULL, 'Shirt', 'from-[#0F766E] to-[#14B8A6]', 'bg-teal-50 text-teal-700 border-teal-200', 'text-teal-600', 'Six yards of cloth, and a man is dressed in dignity.', 'A tribute to the dhoti', 'The dhoti — an unstitched five-yard drape — is perhaps the oldest garment still worn on Earth. Paired with the kurta, it has been the classic dress of men from village of Bhārat farmers to Mahatma Gandhi, who made its hand-spun khadi the uniform of freedom.', '[\"The dhoti is a single piece of cloth, never cut or stitched, tied around the waist and pleated between the legs. It has been worn since antiquity — the same draped style appears on ancient sculptures, in temple art, and in every village of Bhārat today, making it one of the world\'s oldest surviving garments.\", \"Every region drapes it its own way: the Bengali panchakachha with its long pleats, the Tamil veshti, the Kerala mundu, the pleated styles of Maharashtra and Andhra. Above it, the kurta — a loose tunic, plain or embroidered — completes the classic dress of men of Bhārat.\", \"Mahatma Gandhi gave the dhoti-kurta its greatest meaning: he wore the simple khadi dhoti to make hand-spun cloth the symbol of swadeshi and self-reliance, and millions followed. Today the dhoti-kurta remains the dress of weddings, festivals, and parliament itself — timeless and unmistakably of Bhārat.\"]', '[{\"text\": \"One unstitched length of cloth — among the oldest garments on Earth.\", \"title\": \"Never Stitched\"}, {\"text\": \"Panchakachha, veshti, mundu — a hundred ways to tie it.\", \"title\": \"A Drape for Every Region\"}, {\"text\": \"The khadi dhoti became the dress of Bhārat\'s freedom.\", \"title\": \"Gandhi\'s Uniform\"}, {\"text\": \"The tunic that completes the classic dress of Bhārat.\", \"title\": \"Kurta\'s Companion\"}, {\"text\": \"Worn at weddings, festivals, and even in parliament.\", \"title\": \"Still Formal\"}]', 'The dhoti-kurta is Bhārat\'s most democratic garment — worn by farmers and prime ministers, sages and film stars. Unstitched, unchangeable, it has dressed Bhārat for thousands of years.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (277, 'culture', 'salwar-kameez', 'Salwar Kameez', 'सलवार कमीज़', 'Loose trousers, long tunic, flowing dupatta — comfort and grace', 'Attire', 'c. 12th c. CE onwards', 'The everyday grace of North Bhārat women', 'Punjab & North Bhārat', NULL, NULL, 'Shirt', 'from-[#9D174D] to-[#EC4899]', 'bg-pink-50 text-pink-700 border-pink-200', 'text-pink-600', 'Comfort and grace, stitched into the everyday.', 'A tribute to the salwar kameez', 'The salwar kameez — loose trousers, a long tunic, and a flowing dupatta — is the everyday dress of millions of women of Bhārat. In Punjab it was born; across Bhārat it became the perfect blend of comfort, modesty, and grace.', '[\"The salwar kameez came to Bhārat with the cultures of Central and West Asia and found its true home in Punjab, where it became the everyday dress of women — loose enough for farm work, graceful enough for festivals. From there it spread across North Bhārat and beyond.\", \"Its three parts are a study in balance: the salwar (trousers, loose at the top and gathered at the ankle), the kameez (a long tunic with side slits), and the dupatta (the scarf draped over the shoulders). Regional styles add their own flair — the tight churidar, the voluminous Patiala salwar, the embroidered phulkari dupatta.\", \"Today the salwar kameez is worn from villages to boardrooms — practical for the bus, elegant for the wedding. With phulkari embroidery it is festive; with simple cotton it is everyday. Few garments on Earth balance comfort and beauty so perfectly.\"]', '[{\"text\": \"Salwar, kameez, and dupatta — loose, long, and flowing.\", \"title\": \"Three Perfect Parts\"}, {\"text\": \"The dress that Punjab gave to all of Bhārat.\", \"title\": \"Born in Punjab\"}, {\"text\": \"Regional styles from tight-fitted to gloriously loose.\", \"title\": \"Churidar & Patiala\"}, {\"text\": \"The famous flower-embroidery of Punjab.\", \"title\": \"Phulkari Flowering\"}, {\"text\": \"The everyday elegance of millions of women of Bhārat.\", \"title\": \"Village to Boardroom\"}]', 'The salwar kameez is Bhārat\'s most-worn garment of grace — a dress that proves comfort need never be sacrificed for beauty. It is everyday Bhārat, dressed at its best.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (278, 'culture', 'sherwani', 'Sherwani', 'शेरवानी', 'The long coat of honour — Bhārat\'s royal wedding dress', 'Attire', 'Mughal era (16th c.) to today', 'The royal dress of weddings and ceremonies', 'Mughal courts; now pan-Bhārat weddings', NULL, NULL, 'Shirt', 'from-[#312E81] to-[#6366F1]', 'bg-indigo-50 text-indigo-700 border-indigo-200', 'text-indigo-600', 'A sherwani is a poem tailored in velvet.', 'A tribute to the sherwani', 'The sherwani — a long coat with a high collar and gold buttons — is Bhārat\'s grand formal dress. Born in the Mughal court and worn by leaders and grooms ever since, it is the most elegant outfit men of Bhārat own.', '[\"The sherwani grew out of the Mughal court\'s formal dress in the 16th century — a long, close-fitting coat with a stand-up collar and buttons down the front. It combined Persian tailoring with elegance and became of Bhārat the ceremonial dress of the nobility.\", \"In modern Bhārat it never went out of style: Jawaharlal Nehru\'s bandhgala coat descended from it (the \'Nehru jacket\' is the sherwani\'s shorter cousin), and grooms across Bhārat still marry in richly embroidered sherwanis with turbans and juttis.\"]', '[{\"text\": \"Born from the court dress of the 16th-century Mughal empire.\", \"title\": \"Mughal Roots\"}, {\"text\": \"The Nehru jacket is the sherwani\'s shorter, modern form.\", \"title\": \"The Bandhgala Cousin\"}, {\"text\": \"Bhārat\'s most-loved wedding dress for men.\", \"title\": \"The Groom\'s Choice\"}, {\"text\": \"Silk, velvet, and gold thread — a statement of celebration.\", \"title\": \"Richly Embroidered\"}]', 'The sherwani is Bhārat\'s answer to the tuxedo — a coat that carries five centuries of royal elegance into every wedding of Bhārat.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (279, 'culture', 'street-food', 'Street Food of Bhārat', 'स्ट्रीट फूड', 'Pani puri, vada pav, chaat, and chai — the taste of Bhārat is sold on its streets', 'Cuisines', 'Ages-old; thriving today', 'The hawkers and chaatwalas of every city of Bhārat', 'Every city of Bhārat', NULL, NULL, 'Utensils', 'from-[#9A3412] to-[#EA580C]', 'bg-orange-50 text-orange-700 border-orange-200', 'text-orange-600', 'The taste of Bhārat is sold on its streets.', 'A tribute to street food of Bhārat', 'No cuisine in the world lives on the street like Bhārat\'s. Pani puri, vada pav, golgappa, chaat, kathi rolls, and a thousand more — served in seconds, eaten standing, loved by kings and schoolchildren alike.', '[\"street food of Bhārat is a civilisation of its own — stalls and handcarts that have fed the cities for centuries. Its genius is speed and balance: a single pani puri holds crunch, spice, sweet, and tang in one mouthful.\", \"Every city has its star: Mumbai\'s vada pav and bhel puri, Delhi\'s chaat and golgappa, Kolkata\'s kathi rolls, Chennai\'s dosa and murukku, Hyderabad\'s Irani chai and biscuits. And everywhere, cutting chai — the small sweet milky tea that is Bhārat\'s true national drink.\", \"Street food is Bhārat\'s great equalizer — a billionaire and a college student share the same chaat stall. It is fast food, but it is also art: each chaatwala\'s tamarind, yoghurt, and sev recipe is a family secret.\"]', '[{\"text\": \"The king of street snacks — crunch, spice, and tang in one bite.\", \"title\": \"Pani Puri & Golgappa\"}, {\"text\": \"Vada pav in Mumbai, chaat in Delhi, kathi rolls in Kolkata.\", \"title\": \"City Stars\"}, {\"text\": \"The small sweet tea that fuels the whole country.\", \"title\": \"Cutting Chai\"}, {\"text\": \"Everyone — rich and poor — eats at the same stall.\", \"title\": \"The Great Equalizer\"}, {\"text\": \"Every chaatwala\'s chutneys are a guarded heirloom.\", \"title\": \"Family Secrets\"}]', 'street food of Bhārat has gone global — from London\'s Brick Lane to New York\'s Jackson Heights. It is the taste of Bhārat\'s everyday: fast, fearless, and full of flavour.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (280, 'culture', 'south-cuisine-of-bharat', 'South cuisine of Bhārat', 'दक्षिण भारतीय खाना', 'Idli, dosa, and banana-leaf feasts — the genius of the South', 'Cuisines', 'Over 1,000 years', 'The kitchens of the four southern states', 'Tamil Nadu, Kerala, Karnataka & Andhra', NULL, NULL, 'Leaf', 'from-[#065F46] to-[#059669]', 'bg-emerald-50 text-emerald-700 border-emerald-200', 'text-emerald-600', 'In the South, a meal is served on a leaf and eaten with the heart.', 'A tribute to South Bhārat food', 'cuisine of South Bhārat is built on rice, lentils, and coconut — idli and dosa from fermented batters, fiery Andhra spice, Kerala\'s banana-leaf sadya, and a tumbler of filter coffee to finish. It is one of Bhārat\'s oldest and healthiest kitchens.', '[\"The South is a rice civilisation, and its genius is fermentation: idli and dosa batters are left to sour overnight, making them light, digestible, and full of natural goodness — a tradition of \'probiotic\' food a thousand years old.\", \"Every state adds its own fire: Tamil Nadu\'s sambar and rasam, Kerala\'s coconut-rich sadya served on a banana leaf, Karnataka\'s bisi bele bath, and the famously fiery curries of Andhra. Meals are eaten with the hands, served on leaves, and finished with strong filter coffee.\", \"The dosa — crisp, golden, and vast — has conquered the world, but its soul remains the same: a fermented rice-lentil crepe served with chutneys, sambar, and ghee, morning or midnight.\"]', '[{\"text\": \"Fermented rice-lentil batters — ancient and healthy.\", \"title\": \"Idli & Dosa\"}, {\"text\": \"Kerala\'s festival feast served on a green leaf.\", \"title\": \"Banana-Leaf Sadya\"}, {\"text\": \"The tangy lentils that accompany every meal.\", \"title\": \"Sambar & Rasam\"}, {\"text\": \"The frothy, sweet ending to a South Bhārat meal.\", \"title\": \"Filter Coffee\"}]', 'South Bhārat food has crossed every border — dosa is now a world breakfast. It is the taste of a region that has been cooking the same beautiful way for a thousand years.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (281, 'culture', 'sweets-mithai', 'Sweets & Mithai', 'मिठाई', 'Laddu, gulab jamun, jalebi — Bhārat\'s love language', 'Cuisines', 'Centuries of mithai tradition', 'The halwais (sweet-makers) of Bhārat', 'Pan-Bhārat — every region its own mithai', NULL, NULL, 'Candy', 'from-[#92400E] to-[#D97706]', 'bg-amber-50 text-amber-700 border-amber-200', 'text-amber-600', 'Mithai is Bhārat\'s love language.', 'A tribute to sweets of Bhārat', 'No celebration is complete of Bhārat without mithai — the laddu, gulab jamun, jalebi, and barfi that sweeten every festival, wedding, and milestone. It is the first gift given, the last course eaten, and the taste of every happy moment.', '[\"In Bhārat, sweetness is ritual: a new home, a new job, a festival, a birth — all begin with \'muh meetha karo\', let the mouth be sweetened. The halwai, the sweet-maker, is one of Bhārat\'s oldest crafts, and every region has its masterpiece.\", \"Bengal gave the world the rosogolla and sandesh; Punjab offers pinni and petha; Rajasthan\'s ghevar and Gujarat\'s mohanthal; the South\'s payasam and Mysore pak. Each mithai is made from just a few ingredients — milk, sugar, flour, ghee — transformed by patience into art.\", \"The classics are loved everywhere: the golden jalebi, crisp and soaked in syrup; the spongy gulab jamun; and the laddu, the prince of prasad, offered to gods before it is offered to guests. Mithai is the taste of generosity of Bhārat.\"]', '[{\"text\": \"Every happy occasion in Bhārat begins with something sweet.\", \"title\": \"Muh Meetha Karo\"}, {\"text\": \"Rosogolla in Bengal, Mysore pak in the South, ghevar in Rajasthan.\", \"title\": \"Regional Masters\"}, {\"text\": \"The all-Bhārat favourites, from temples to weddings.\", \"title\": \"Laddu & Jalebi\"}, {\"text\": \"Milk, sugar, and ghee — transformed by patience into gold.\", \"title\": \"The Halwai\'s Art\"}]', 'Mithai is Bhārat\'s sweetest export — rosogolla now has its own GI tag, and sweets are loved of Bhārat on every continent. It is the taste of celebration itself.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (282, 'culture', 'namaste', 'The Namaste', 'नमस्ते', 'Bhārat\'s greeting — the divine light in me bows to the light in you', 'Traditions & Customs', 'Ancient — as old as Sanskrit itself', 'Every home and heart of Bhārat', 'Pan-Bhārat', NULL, NULL, 'Hand', 'from-[#B45309] to-[#F59E0B]', 'bg-amber-50 text-amber-700 border-amber-200', 'text-amber-600', 'Namaste — the divine in me bows to the divine in you.', 'The meaning of the greeting', 'Namaste — palms joined at the heart with a slight bow — is Bhārat\'s timeless greeting. It means \'I bow to you\', and in its deepest reading, \'the divine light in me honours the divine light in you\'. One gesture, a thousand years of grace.', '[\"The word namaste comes from Sanskrit: namah (bow) + te (to you). Pressing the palms together at the heart, with a gentle nod of the head, is the traditional way people of Bhārat greet, welcome, thank, and say farewell. It costs nothing, and it says everything.\", \"The gesture — the anjali mudra — places the two hands together to represent the meeting of the individual soul with the universal. Yogis hold it in meditation; dancers begin their performances with it; hosts greet guests with it at the door.\", \"Unlike a handshake, namaste keeps a respectful distance and is offered with a smile. It has travelled the world with yoga — today you hear \'namaste\' in studios from California to Tokyo, a greeting that carries Bhārat\'s warmth wherever it goes.\"]', '[{\"text\": \"Namah + te — \'bow to you\' in Sanskrit.\", \"title\": \"I Bow to You\"}, {\"text\": \"The anjali mudra joins the individual with the universal.\", \"title\": \"Palms at the Heart\"}, {\"text\": \"Welcome, thanks, farewell — one gesture for every moment.\", \"title\": \"A Greeting for All\"}, {\"text\": \"Carried across the globe by yoga and warmth of Bhārat.\", \"title\": \"The World\'s Namaste\"}]', 'Namaste is Bhārat\'s gift of grace to the world — a greeting that needs no touch, no title, no words. In one small bow, it teaches the whole planet how to say hello with humility and love.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (283, 'culture', 'tulsi', 'Tulsi — The Holy Basil', 'तुलसी', 'The sacred plant that guards the home of Bhārat', 'Traditions & Customs', 'Worshipped for over 3,000 years', 'Every courtyard of Bhārat', 'Pan-Bhārat', NULL, NULL, 'Sprout', 'from-[#166534] to-[#22C55E]', 'bg-green-50 text-green-700 border-green-200', 'text-green-600', 'The tulsi is the queen of herbs — worshipped by day, medicinal by night.', 'An old saying of Bhārat', 'The tulsi plant — holy basil — stands in the courtyard of nearly every home of Bhārat, worshipped twice a day as the goddess Tulsi. Sacred to Vishnu, it is also the \'elixir of life\' of Ayurveda — a leaf that has healed Bhārat for millennia.', '[\"Tulsi (Ocimum tenuifolium) is Bhārat\'s most sacred plant. A small shrine — the tulsi vrindavan — is built in the courtyard of Hindu homes, and every morning and evening the family lights a lamp, offers water, and circles it with prayers. The plant is treated as a living goddess, an avatar of Lakshmi.\", \"In legend, Tulsi was a devoted princess who became a plant, and Vishnu is said to love the tulsi leaf above all offerings — no prayer is complete without it. Even the gods are said to need a tulsi leaf to be remembered. Tulsi leaves are placed on the tongue of the dying to grant them liberation.\", \"Science caught up with devotion: tulsi is antibacterial, antiviral, and adaptogenic — it helps the body handle stress. Ayurveda calls it the \'incomparable one\', used for coughs, fevers, and digestion. It is the only plant in the world that is both worshipped and prescribed.\"]', '[{\"text\": \"Worshipped twice daily in a shrine in every Hindu home.\", \"title\": \"The Courtyard Goddess\"}, {\"text\": \"No offering to the gods is complete without a tulsi leaf.\", \"title\": \"Vishnu\'s Favourite\"}, {\"text\": \"Ayurveda\'s elixir of life for fevers, coughs, and stress.\", \"title\": \"The Incomparable One\"}, {\"text\": \"Antibacterial, antiviral, adaptogenic — and worshipped.\", \"title\": \"Faith Meets Science\"}]', 'Tulsi is where faith and medicine of Bhārat meet in a single green leaf. It is the daily symbol of the home\'s sacredness, and a living proof that Bhārat has always healed what it honours.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (284, 'culture', 'mehndi', 'Mehndi — Henna Art', 'मेहंदी', 'Fragile brown lace painted on hands — joy drawn in henna', 'Traditions & Customs', 'A bridal art for over 5,000 years', 'The mehndi artists of every town', 'Pan-Bhārat', NULL, NULL, 'Flower2', 'from-[#9A3412] to-[#D97706]', 'bg-orange-50 text-orange-700 border-orange-200', 'text-orange-700', 'Mehndi ki mehek — the fragrance of henna, the scent of celebration.', 'A bridal saying', 'Mehndi — intricate henna patterns painted on hands and feet — is the art of celebration of Bhārat. On brides, on festival mornings, and at weddings, the brown lace of henna turns hands into jewellery, and its stain deepens with love.', '[\"The use of henna for adornment goes back over 5,000 years in Bhārat. The mehndi ceremony — a joyful evening before the wedding, full of song and dance — is when the bride\'s hands and feet are covered in the finest patterns: peacocks, vines, paisleys, and the groom\'s name hidden in the lace.\", \"Mehndi is made by crushing the leaves of the henna plant into a paste, applied through a fine cone. Left to dry and kept warm, it stains the skin a rich brown that deepens over hours — the deeper the colour, the deeper the love, say the elders.\", \"Beyond weddings, mehndi marks festivals like Karva Chauth, Teej, and Eid, and adorns dancers and children on happy days. It is a living folk art, with each region — Rajasthani, Mughlai, Arabic — adding its own swirls to the design.\"]', '[{\"text\": \"A night of song and henna before the wedding day.\", \"title\": \"The Bridal Ceremony\"}, {\"text\": \"The groom\'s name is hidden somewhere in the bride\'s pattern.\", \"title\": \"A Hidden Name\"}, {\"text\": \"Dark henna means deep love — so the colour is kept warm and long.\", \"title\": \"The Deeper the Stain\"}, {\"text\": \"Karva Chauth, Teej, Eid — and dancers on happy days.\", \"title\": \"Festival & Folk Art\"}]', 'Mehndi is Bhārat\'s most intimate art — painted on skin, gone in weeks, remembered forever. It turns the bride\'s hands into a poem of blessing, and every festival into a moment of grace.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (285, 'culture', 'folk-music', 'Folk Music of Bhārat', 'लोक संगीत', 'The songs of the soil — work, rain, and wedding songs of every village', 'Folk Art', 'As old as the villages themselves', 'Every region\'s singers and drummers', 'Pan-Bhārat — a music for every land', NULL, NULL, 'Music3', 'from-[#7C2D12] to-[#C2410C]', 'bg-orange-50 text-orange-700 border-orange-200', 'text-orange-600', 'Folk music is the voice of the land — it sings with the rain and dances with the harvest.', 'A tribute to Bhārat\'s village music', 'Folk music is Bhārat\'s oldest soundtrack — the work songs of farmers, the wedding songs of every region, the lullabies and festival drums that need no stage. From the Bauls of Bengal to the Bhangra of Punjab, every soil has its song.', '[\"Before films and streams, Bhārat sang. Farmers sang while sowing and reaping, women sang while grinding grain, and whole villages sang at weddings, births, and festivals. Folk music is the music of everyday life — passed ear to ear, never written down, and never forgotten.\", \"Every region has its voice: the Bauls of Bengal wandering with their ektara, the powerful Bhangra and Giddha of Punjab, the Lavani of Maharashtra, the Garba of Gujarat, and the soulful Bihu songs of Assam. Each carries the accent, rhythm, and stories of its soil.\", \"The instruments are born of the land too — the dhol, dholak, and tabla for rhythm, the shehnai for weddings, the ektara and dotara for wandering minstrels. Folk songs speak of love, longing, seasons, and gods — and many became film hits, carrying the village into the city.\"]', '[{\"text\": \"Work songs, lullabies, and festival songs passed ear to ear.\", \"title\": \"Music of Daily Life\"}, {\"text\": \"Baul, Bhangra, Lavani, Garba, Bihu — a music for every soil.\", \"title\": \"One Land, Many Voices\"}, {\"text\": \"Dhol, shehnai, ektara, and dholak — born of the land.\", \"title\": \"Instruments of the Earth\"}, {\"text\": \"Folk melodies became Bhārat\'s most-loved film songs.\", \"title\": \"From Village to Film\"}]', 'Folk music is the beating heart of culture of Bhārat — the sound of millions of villages, kept alive by people who sing because they are happy, not because they are paid. It is Bhārat\'s truest music.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (286, 'culture', 'pattachitra', 'Pattachitra Painting', 'पट्टचित्र', 'Stories painted on cloth — Odisha\'s scroll of the gods', 'Folk Art', 'A living art for over 1,000 years', 'The chitrakaras of Odisha', 'Raghurajpur & Puri, Odisha', NULL, NULL, 'Scroll', 'from-[#92400E] to-[#EAB308]', 'bg-amber-50 text-amber-800 border-amber-200', 'text-amber-700', 'Every line is a prayer; every colour a story of the gods.', 'The chitrakaras\' credo', 'Pattachitra — \'picture on cloth\' — is Odisha\'s thousand-year-old scroll painting, born in the shadow of the Jagannath temple. Its artists, the chitrakaras, paint the epics with fine brushwork and natural colours that have not faded in a millennium.', '[\"The word pattachitra comes from patta (cloth) and chitra (picture). It began as an offering to Lord Jagannath of Puri — the painting itself was an act of worship, and the chitrakaras who made it were keepers of a sacred craft passed down within families.\", \"The art is defined by its discipline: a single unbroken line for each figure, colours drawn only from nature — white from conch shell, black from burnt coconut, red from minerals, yellow from turmeric. The cloth is coated with chalk and gum and polished with a smooth stone until it gleams.\", \"The themes are the eternal ones: Krishna\'s leela, the ten incarnations of Vishnu, the epic of the Mahabharata, and the three gods of Jagannath — Subhadra, Balabhadra, and Jagannath himself. Today pattachitra also adorns bags, saris, and walls, carrying a thousand-year-old line of art into every home.\"]', '[{\"text\": \"Patta (cloth) + chitra (picture) — sacred scroll art.\", \"title\": \"Picture on Cloth\"}, {\"text\": \"Each figure is drawn in a single, flawless stroke.\", \"title\": \"One Unbroken Line\"}, {\"text\": \"White from shell, black from coconut, red from minerals.\", \"title\": \"Colours of the Earth\"}, {\"text\": \"An offering to the temple of Puri, painted in worship.\", \"title\": \"Born of Jagannath\"}]', 'Pattachitra is a bridge across a thousand years — an art that still paints the same gods with the same natural colours as its creators. It is Odisha\'s living scripture, drawn on cloth.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (287, 'culture', 'film-music-of-bharat', 'film music of Bhārat', 'फ़िल्मी संगीत', 'The songs that Bhārat hums — from the gramophone to the streaming era', 'Music & Arts', 'Born with the talkies in 1931', 'Composers, singers & lyricists of Hindi and regional cinema', 'Pan-Bhārat — every language has its film songs', NULL, NULL, 'Clapperboard', 'from-[#1E3A8A] to-[#3B82F6]', 'bg-blue-50 text-blue-700 border-blue-200', 'text-blue-600', 'A film without songs is like a body without a heartbeat.', 'An old film-industry saying', 'film music of Bhārat is the most loved music in Bhārat — a billion people hum the songs of the movies. From the first talkie \'Alam Ara\' in 1931 to today\'s streaming hits, the film song has carried classical ragas, folk tunes, and new trends into every home of Bhārat.', '[\"When \'Alam Ara\' brought sound to cinema of Bhārat in 1931, it also gave birth to a new art: the film song. Within a decade, songs were the heart of every movie of Bhārat — the reason people bought tickets, and the music they carried home humming.\", \"The golden age followed: composers like S.D. Burman, Naushad, and Shankar-Jaikishan, and the immortal voices of Lata Mangeshkar, Kishore Kumar, and Mohammed Rafi. Their songs blended ragas with Western orchestras, creating a sound that belonged to no country and every country.\", \"Today, film music spans every language of Bhārat — Tamil, Telugu, Bengali, Marathi, and more — and has gone global through streaming. The playback song remains Bhārat\'s shared heartbeat: the tune played at weddings, the melody in every earphone, and the soundtrack of a billion lives.\"]', '[{\"text\": \"The first talkie \'Alam Ara\' launched the film song of Bhārat.\", \"title\": \"Born in 1931\"}, {\"text\": \"classical melodies fused of Bhārat with Western arrangements.\", \"title\": \"Ragas Meet Orchestras\"}, {\"text\": \"Lata, Kishore, Rafi — voices every person of Bhārat grew up with.\", \"title\": \"Golden Voices\"}, {\"text\": \"Film songs thrive in Hindi and all regional cinemas.\", \"title\": \"Every Language\"}]', 'film music of Bhārat is Bhārat\'s most democratic art — loved by every class, in every language, for ninety years. It is the sound of Bhārat itself: classical, folk, modern, and endlessly singing.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (288, 'culture', 'kalamkari', 'Kalamkari — Pen Craft', 'कलमकारी', 'Stories of gods drawn with a bamboo pen on cloth', 'Crafts & Weaves', 'A temple art for over 700 years', 'The kalamkari artists of Andhra Pradesh', 'Srikalahasti & Machilipatnam, Andhra Pradesh', NULL, NULL, 'Paintbrush', 'from-[#9A3412] to-[#C2410C]', 'bg-orange-50 text-orange-800 border-orange-200', 'text-orange-700', 'The pen (kalam) paints what the heart believes.', 'The kalamkari artists\' credo', 'Kalamkari — \'pen work\' — is Andhra\'s ancient art of painting temple cloth with a bamboo pen dipped in natural dyes. Every panel tells a story: the epics, the gods, the seasons — drawn in earthy reds, blues, and yellows that never fade.', '[\"The name kalamkari comes from kalam (pen) and kari (craft). For over 700 years, artists of Srikalahasti have painted scenes from the Ramayana and Mahabharata on cloth that hung as temple backdrops, while Machilipatnam\'s block printers made the craft a fabric for everyday life.\", \"The process is patient and natural: the cloth is washed, treated with milk and myrobalan, then drawn with a sharp bamboo pen. Colours come from the earth and the plant — red from madder root, blue from indigo, yellow from pomegranate rind. Nothing synthetic touches the cloth.\", \"The style is unmistakable — bold outlines, floral borders, and figures of gods and dancers in flat, warm colours. Today kalamkari adorns sarees, dupattas, and home linens worldwide, carrying the temple\'s stories into wardrobes on every continent.\"]', '[{\"text\": \"Kalam (pen) + kari (craft) — drawn with a bamboo nib.\", \"title\": \"Pen on Cloth\"}, {\"text\": \"Madder red, indigo blue, pomegranate yellow — no synthetics.\", \"title\": \"Natural Only\"}, {\"text\": \"Panels of Ramayana and Mahabharata for temple backdrops.\", \"title\": \"Temple Stories\"}, {\"text\": \"Srikalahasti\'s hand-painting and Machilipatnam\'s block prints.\", \"title\": \"Two Schools\"}]', 'Kalamkari is a seven-century conversation between pen and cloth — a craft that turned temple walls into wearable art. It proves Bhārat\'s villages have always known how to paint with patience and the earth\'s own colours.', '2026-08-10 14:36:40', '2026-08-13 21:55:17') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (1, 'ideas', 'vedanta', 'Vedanta', 'वेदान्त', 'The end of the Vedas — the eternal inquiry into the nature of the Self', 'Vedic', 'c. 8th c. BCE – present', 'Badarayana (Vyasa); Advaita by Adi Shankaracharya', 'Everywhere — born in the forests of North Bhārat', NULL, NULL, 'Infinity', 'from-[#5B21B6] to-[#8B5CF6]', 'bg-violet-50 text-violet-700 border-violet-200', 'text-violet-600', 'Tat Tvam Asi — \'That Thou Art\'', 'Chandogya Upanishad 6.8.7', 'Vedanta — the \'end of the Vedas\' — is the profound philosophy distilled from the Upanishads. It asks the deepest question of all: who are you, really? Its answer — that the individual soul (Atman) and the ultimate reality (Brahman) are one — has inspired thinkers from Shankaracharya to Swami Vivekananda, and scientists like Erwin Schrödinger.', '[\"Vedanta literally means the \'end of the Vedas\' — both because it closes the four Vedas and because it represents the final, highest goal of Vedic wisdom. Its root texts are the Upanishads, written by forest-dwelling sages who abandoned ritual performance to meditate on the great questions: What is real? What is the Self? What happens after death?\", \"The tradition flowered into many schools. Advaita Vedanta, taught by Adi Shankaracharya in the 8th century CE, holds that only Brahman — pure, infinite consciousness — is real, and the world of separate things is Maya (appearance). Ramanuja\'s Vishishtadvaita and Madhva\'s Dvaita offered theistic visions where God and soul remain distinct. Each school was debated fiercely and rigorously — proof that ancient Bhārat prized argument over blind belief.\", \"At its heart is a single luminous idea: the Atman — the innermost self in every being — is identical to Brahman, the ground of all existence. Realising this unity, said the sages, is liberation (Moksha). It is the end of fear, the end of suffering, and the discovery that you were never separate from the whole.\", \"Vedanta never stayed inside temples. It travelled to the West with Swami Vivekananda\'s 1893 speech in Chicago, inspired poets like Ralph Waldo Emerson, and shaped the thinking of physicists probing the nature of reality. Today it remains one of humanity\'s boldest answers to the question of what we are.\"]', '[{\"text\": \"The individual self and the universal reality are, at the deepest level, one and the same.\", \"title\": \"Atman & Brahman\"}, {\"text\": \"The everyday world is not unreal, but it is not the final truth either — it is a play of appearances over one reality.\", \"title\": \"Maya\"}, {\"text\": \"The path of knowledge — self-inquiry (\'Who am I?\') — is the direct route to liberation.\", \"title\": \"Jnana Marga\"}, {\"text\": \"Freedom is realising your oneness with Brahman, ending the cycle of birth and rebirth.\", \"title\": \"Moksha\"}, {\"text\": \"Vedanta schools argued for centuries in writing — proof that wisdom welcomed questioning of Bhārat.\", \"title\": \"Debate & Reason\"}]', 'Vedanta is the philosophical backbone of modern Hinduism, the inspiration behind the Ramakrishna Mission, the theme of Vivekananda\'s world-famous speeches, and a wellspring for poets, scientists, and seekers worldwide. Its core teaching — that every being carries the divine within — remains one of Bhārat\'s greatest gifts to humanity.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (2, 'ideas', 'samkhya', 'Samkhya', 'सांख्य', 'Bhārat\'s oldest systematic philosophy — the science of counting reality', 'Vedic', 'c. 6th–2nd c. BCE', 'Sage Kapila', 'North Bhārat', NULL, NULL, 'Eye', 'from-[#9A3412] to-[#EA580C]', 'bg-orange-50 text-orange-700 border-orange-200', 'text-orange-600', 'Duhkha-trayabhighata-jijnasa — \'From the torment of threefold suffering arises the inquiry into its cause\'', 'Samkhya Karika 1', 'Samkhya — literally \'counting\' or \'enumeration\' — is thought to be the oldest systematic philosophy of Bhārat, and possibly the world. It seeks to end suffering not through faith but through precise analysis, listing the twenty-five principles (tattvas) that make up all of existence.', '[\"Samkhya, attributed to the sage Kapila, is Bhārat\'s great rationalist philosophy. Its name means \'enumeration\' because it sets out to explain the universe by counting its fundamental building blocks — exactly twenty-five of them. No gods are required: reality explains itself.\", \"Its two pillars are Purusha (pure consciousness, the silent witness) and Prakriti (matter, energy, nature). From Prakriti evolve intellect, mind, the five senses, the five elements — the entire show of creation. Suffering begins when consciousness forgets it is the witness and mistakes itself for the show.\", \"Samkhya\'s method is startlingly modern. It is analytical, logical, and relentlessly clear — closer in spirit to a science textbook than a holy book. It taught that the universe can be understood and that liberation comes from knowledge, not from pleasing any deity.\", \"Samkhya\'s ideas radiate everywhere in thought of Bhārat. The Bhagavad Gita is saturated with it; the concept of the three gunas (qualities of nature) — sattva, rajas, tamas — used in everyday Hindi today, comes straight from Samkhya.\"]', '[{\"text\": \"Two eternal realities: pure awareness and evolving nature. Their union begins creation.\", \"title\": \"Purusha & Prakriti\"}, {\"text\": \"Everything in existence reduces to twenty-five principles, from earth and water to intellect and consciousness.\", \"title\": \"The 25 Tattvas\"}, {\"text\": \"Sattva (clarity), rajas (activity), tamas (inertia) — the three qualities that weave every moment of experience.\", \"title\": \"The Three Gunas\"}, {\"text\": \"Liberation is the soul realising it was always the untouched witness — free, calm, and alone.\", \"title\": \"Kaivalya\"}, {\"text\": \"Samkhya explains the universe without a creator — a bold, rational leap for its time.\", \"title\": \"No God Required\"}]', 'Samkhya shaped the Bhagavad Gita, Ayurveda\'s theory of the body, and the everyday language of the three gunas. Its insistence that reality can be understood by analysis and that liberation comes through knowledge makes it a philosophical ancestor of science itself.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (3, 'ideas', 'yoga', 'Yoga', 'योग', 'The science of union — stilling the mind to see clearly', 'Vedic', 'c. 2nd c. BCE (classical)', 'Sage Patanjali', 'North Bhārat & the Himalayas', NULL, NULL, 'Flame', 'from-[#0F766E] to-[#14B8A6]', 'bg-teal-50 text-teal-700 border-teal-200', 'text-teal-600', 'Yogah chittavritti nirodhah — \'Yoga is the stilling of the fluctuations of the mind\'', 'Yoga Sutra 1.2, Sage Patanjali', 'Born in Bhārat and now practised by millions worldwide, Yoga is far more than exercise. It is a complete science of self-transformation — a step-by-step path to calm the mind, master the body, and awaken the spirit within.', '[\"The word yoga comes from the Sanskrit root yuj — \'to join\' or \'to yoke\'. Its goal is union: of body and mind, of the individual with the whole. While asanas (postures) made yoga famous worldwide, classical yoga as codified by Sage Patanjali in the Yoga Sutras is an eight-limbed path to inner mastery.\", \"Patanjali\'s eight limbs are Yama and Niyama (ethical living), Asana (steady posture), Pranayama (breath control), Pratyahara (withdrawing the senses), Dharana (concentration), Dhyana (meditation), and Samadhi (absorption). Each step builds on the last — from how you treat others to how you sit still for five minutes.\", \"Yoga teaches that the mind is like a lake. When thoughts ripple across it, you cannot see the bottom — your own true self. By calming the ripples through breath, posture, and meditation, the water becomes still and you see clearly. This is not mysticism; it is training in attention, and modern neuroscience keeps confirming its effects.\", \"In 2014, the United Nations declared 21 June the International Day of Yoga, at the proposal of Bhārat. Today, from schoolyards in Delhi to studios in New York, the world bends, breathes, and meditates — all thanks to a science perfected on soil over two of Bhārat thousand years ago.\"]', '[{\"text\": \"A complete path from ethical living to deep meditation — not just exercise, but a way of life.\", \"title\": \"The Eight Limbs\"}, {\"text\": \"Yoga begins with how you treat others (non-violence, truth) and how you treat yourself (purity, contentment).\", \"title\": \"Yama & Niyama\"}, {\"text\": \"The breath is the bridge between body and mind — control the breath and you begin to control the mind.\", \"title\": \"Pranayama\"}, {\"text\": \"Through sustained meditation the mind settles into stillness, revealing the peaceful self beneath the noise.\", \"title\": \"Dhyana & Samadhi\"}, {\"text\": \"Still the ripples of thought and the depths of your own nature become visible.\", \"title\": \"Mind as Lake\"}]', 'Yoga is Bhārat\'s most exported philosophy — UNESCO-listed, UN-celebrated, and practised by hundreds of millions. Beyond the mats and studios, its deeper teaching remains: peace, clarity, and self-mastery are skills that anyone, anywhere, can cultivate.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (4, 'ideas', 'nyaya', 'Nyaya', 'न्याय', 'The philosophy of logic — Bhārat\'s ancient school of reasoning', 'Vedic', 'c. 6th–2nd c. BCE', 'Sage Akshapada Gautama', 'Mithila (Bihar) & Kashmir', NULL, NULL, 'Scale', 'from-[#4338CA] to-[#6366F1]', 'bg-indigo-50 text-indigo-700 border-indigo-200', 'text-indigo-600', 'Pramanyam prameya-jnanam — knowledge is true when it is grounded in valid evidence', 'Nyaya Sutra tradition', 'Long before formal logic was studied in Europe, Bhārat\'s Nyaya school was building the science of reasoning. It asked: how do we know anything at all? What counts as proof? Its answers — perception, inference, comparison, and testimony — still underpin how we think today.', '[\"Nyaya means \'that by which the mind is led\' — logic. Founded by Sage Akshapada Gautama (not the Buddha), it is Bhārat\'s school of epistemology and reasoning, devoted to the question: how can we know what is true? The answer mattered, because everything else — ethics, liberation, science — depended on getting knowledge right.\", \"Nyaya identified four pramanas, or valid means of knowledge: Pratyaksha (perception), Anumana (inference), Upamana (comparison), and Shabda (trustworthy testimony). Its most famous tool is the five-member syllogism — a formal proof with premise, reason, example, application, and conclusion. Scholars used it for centuries to win debates across the subcontinent.\", \"The Nyaya method is unmistakably scientific: define terms precisely, demand evidence, expose fallacies. Its analysis of fallacies (hetvabhasa) — defective reasons that look valid — reads like an ancient textbook on critical thinking. The great debate halls of Mithila and Kashmir were, in effect, Bhārat\'s first universities of logic.\", \"Navya-Nyaya, the \'new logic\' developed in 13th-century Mithila, refined these tools into a razor-sharp technical language so precise that modern scholars compare it to formal mathematical logic. logicians were exploring of Bhārat quantified logic centuries before it appeared in the West.\"]', '[{\"text\": \"Perception, inference, comparison, and testimony — the four trustworthy routes to knowledge.\", \"title\": \"Four Pramanas\"}, {\"text\": \"A formal argument structure: thesis, reason, example, application, conclusion.\", \"title\": \"The Five-Member Proof\"}, {\"text\": \"A meticulous catalogue of bad arguments — the world\'s first textbook on critical thinking.\", \"title\": \"Fallacy Detection\"}, {\"text\": \"Clear reasoning was not academic vanity — right knowledge was the road to freedom from suffering.\", \"title\": \"Logic for Liberation\"}, {\"text\": \"Medieval Mithila\'s \'new logic\' produced a technical language of staggering precision.\", \"title\": \"Navya-Nyaya\"}]', 'Nyaya built the intellectual toolkit scholars of Bhārat used for two thousand years. Its rigorous methods spread into every school of philosophy of Bhārat, influenced mathematics and linguistics, and remain a testament to Bhārat\'s ancient love affair with reason.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (5, 'ideas', 'vaisheshika', 'Vaisheshika', 'वैशेषिक', 'The atomists — Bhārat\'s philosophy of matter and motion', 'Vedic', 'c. 6th–2nd c. BCE', 'Sage Kanada', 'North Bhārat', NULL, NULL, 'Atom', 'from-[#155E75] to-[#0891B2]', 'bg-cyan-50 text-cyan-700 border-cyan-200', 'text-cyan-600', 'Dravya-guna-karma-samanya-vishesa-samavaya — the six categories through which all reality is known', 'Vaisheshika Sutra tradition', 'Nearly three thousand years ago, the sage Kanada declared that the entire universe is built from tiny, indivisible particles — atoms. His philosophy, Vaisheshika, is Bhārat\'s great attempt to understand matter, motion, and change with pure reason, and it eerily prefigures modern physics.', '[\"Vaisheshika means \'the school of particularities\'. Its founder, the sage Kanada — whose name means \'atom-eater\' — reasoned that if you keep dividing any object, you must eventually reach pieces that cannot be divided further. These indivisible particles he called anu, the atoms.\", \"Kanada proposed that all things are made of four kinds of atoms — earth, water, fire, and air — which combine in different ways. He described how atoms join, how qualities like smell and taste arise, and how motion works. He even speculated about a fifth element, space, and about time as a fundamental reality.\", \"To organise all of this, Vaisheshika created a complete taxonomy of reality: six categories (padarthas) — substance, quality, action, generality, particularity, and inherence. Everything that exists, it claimed, fits into these six. It is the most systematic attempt at a \'periodic table of being\' in the ancient world.\", \"Vaisheshika is also famously scientific in spirit: it held that only perception and inference can establish truth, that the world is real (not an illusion), and that explanation should be natural, not supernatural. The sage who \'ate atoms\' had built a physics of the unseen from pure thought.\"]', '[{\"text\": \"Reality is built from anu — indivisible particles too small to be seen, eternal and unchanging.\", \"title\": \"The Atom\"}, {\"text\": \"Earth, water, fire, and air atoms combine in endless ways to create the material world.\", \"title\": \"Four Elements\"}, {\"text\": \"Substance, quality, action, generality, particularity, inherence — the complete map of what exists.\", \"title\": \"Six Categories\"}, {\"text\": \"The world is explained by atoms, motion, and laws — not by miracles or divine whim.\", \"title\": \"Natural Explanation\"}, {\"text\": \"The world you perceive is real, not an illusion — knowledge comes from perception and inference.\", \"title\": \"Realism\"}]', 'Vaisheshika is one of the earliest atomistic theories in human history, developed centuries before Greek atomism matured. Its daring idea — that unseen building blocks explain the visible world — is the same wager that modern physics makes every day.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (6, 'ideas', 'mimamsa', 'Mimamsa', 'मीमांसा', 'The philosophy of action — dharma through right duty, rite, and word', 'Vedic', 'c. 6th–2nd c. BCE', 'Sage Jaimini', 'North Bhārat', NULL, NULL, 'Scroll', 'from-[#92400E] to-[#D97706]', 'bg-amber-50 text-amber-700 border-amber-200', 'text-amber-600', 'Dharma jijnasa — \'The inquiry into dharma, the law of right action\'', 'Mimamsa Sutra 1.1.1', 'While other schools chased liberation, Mimamsa asked a more practical question: what makes an action right? It built a rigorous philosophy of duty, ritual, language, and ethics — arguing that dharma is not something you believe, but something you do.', '[\"Mimamsa means \'investigation\' or \'deep reflection\'. Founded by Sage Jaimini, it focuses on dharma — the law of right action — as revealed in the ritual and moral injunctions of the Vedas. Its founding question is simple and powerful: what should I do?\", \"Unlike schools that dismissed the world as illusion, Mimamsa took the world and human action absolutely seriously. Every action has consequences (karma), and performing one\'s duties with care and skill was seen as the path to a flourishing life. It built a complex hermeneutics — a science of interpreting sacred texts — unmatched in the ancient world.\", \"Mimamsa developed a brilliant philosophy of language. It argued that words carry meaning through eternal connection to their referents, and that sentences convey their sense through the relationship of command and action. Its analysis of how meaning works influenced linguistics for centuries of Bhārat.\", \"Later Mimamsakas like Prabhakara and Kumarila debated epistemology and ethics so sharply that they became the intellectual gatekeepers of tradition of Bhārat — no one could claim to interpret the scriptures without answering their challenges.\"]', '[{\"text\": \"Righteousness is not a belief but a discipline — what you do, with skill and intention.\", \"title\": \"Dharma Is Action\"}, {\"text\": \"Every deed returns to its doer; careful action ripples into a well-lived life.\", \"title\": \"Karma\"}, {\"text\": \"Mimamsa pioneered the study of how words and sentences carry meaning.\", \"title\": \"The Science of Meaning\"}, {\"text\": \"The core unit of sacred text is the command — the \'ought\' that guides human conduct.\", \"title\": \"Injunction\"}, {\"text\": \"Rites and duties train the mind in precision, order, and commitment to the whole.\", \"title\": \"Ritual as Discipline\"}]', 'Mimamsa gave civilization its deep of Bhārat reverence for duty and its unmatched skills in textual interpretation. Its philosophy of language seeded linguistics of Bhārat, and its insistence that ethics lives in action — not belief — remains profoundly relevant today.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (7, 'ideas', 'buddhism', 'Buddhism', 'बौद्ध धर्म', 'The Middle Path — compassion and awakening born at Bodh Gaya', 'Śramaṇa', 'c. 6th–5th c. BCE – present', 'Siddhartha Gautama, the Buddha', 'Bodh Gaya (Bihar), Sarnath (Uttar Pradesh)', NULL, NULL, 'Flower', 'from-[#B45309] to-[#F59E0B]', 'bg-amber-50 text-amber-800 border-amber-200', 'text-amber-700', 'Peace comes from within. Do not seek it without.', 'Attributed to the Buddha', 'Under a peepal tree at Bodh Gaya, a prince from Kapilavastu became the Buddha — the Awakened One. His diagnosis of human suffering and its cure spread from Bihar across Asia, and today Buddhism is one of the great world religions: a philosophy of compassion, mindfulness, and the Middle Path.', '[\"Siddhartha Gautama was a prince who, upon seeing old age, sickness, and death for the first time, left his palace to understand why beings suffer. After six years of seeking — first luxury, then extreme asceticism — he sat beneath the Bodhi tree at Bodh Gaya in Bihar and vowed not to rise until he understood. At dawn, he became the Buddha: the Awakened One.\", \"His first teaching, delivered at Sarnath near Varanasi, was the Four Noble Truths: life involves suffering; suffering has a cause (craving); suffering can end; and there is a path to its end. That path — the Noble Eightfold Path — is a practical programme of right view, right intention, right speech, right action, right livelihood, right effort, right mindfulness, and right concentration.\", \"Buddhism rejected both extremes — the luxury of the palace and the self-torture of the ascetics — choosing the Middle Path. It also rejected the caste hierarchy of its time: anyone, from any birth, could walk the path to awakening. This radical openness made it a movement of the people.\", \"From Bihar and Uttar Pradesh, the dharma travelled the Silk Road. It shaped the great empires of Ashoka and Kanishka, built stupas and universities like Nalanda, and eventually became the dominant faith of East and Southeast Asia. In the 20th century, Dr. B.R. Ambedkar revived it in Bhārat as a path of dignity and equality for millions.\", \"Today, mindfulness — Buddhism\'s ancient technology of attention — is taught in hospitals, schools, and boardrooms worldwide. The philosophy born under a peepal tree of Bhārat now illuminates the planet.\"]', '[{\"text\": \"Suffering exists; it has a cause; it can end; there is a path to its end.\", \"title\": \"The Four Noble Truths\"}, {\"text\": \"Avoid extremes — neither indulgence nor self-torture — and walk the balanced way.\", \"title\": \"The Middle Path\"}, {\"text\": \"A practical eight-step programme of wisdom, ethics, and mental training.\", \"title\": \"The Eightfold Path\"}, {\"text\": \"All things change, and there is no permanent self — freedom comes from seeing this clearly.\", \"title\": \"Anatta & Impermanence\"}, {\"text\": \"Seeing the suffering of others and acting to ease it is the very heart of the dharma.\", \"title\": \"Compassion (Karuna)\"}]', 'Buddhism carried thought to half of Bhārat the world, inspired Emperor Ashoka\'s pillar of non-violence, and built the university of Nalanda. Its teachings of compassion and mindfulness are now among the most influential ideas on Earth — a gift from the land of Bodh Gaya.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (8, 'ideas', 'jainism', 'Jainism', 'जैन धर्म', 'The way of absolute non-violence — ahimsa as the highest law', 'Śramaṇa', 'c. 6th c. BCE (classical)', 'Tirthankara Mahavira (24th Tirthankara)', 'Bihar & Western Bhārat', NULL, NULL, 'Hand', 'from-[#047857] to-[#10B981]', 'bg-emerald-50 text-emerald-700 border-emerald-200', 'text-emerald-600', 'Ahimsa Paramo Dharma — \'Non-violence is the highest duty\'', 'Jain teaching', 'Jainism — born in the same Ganges valley ferment as Buddhism — is the world\'s most radical philosophy of non-violence. Its central vow, ahimsa, extends compassion to every living being, and its followers\' discipline of harmlessness has shaped Bhārat\'s vegetarian soul.', '[\"Jainism was shaped most famously by Mahavira, the 24th and last Tirthankara — \'ford-maker\' across the river of existence. Born a prince in Bihar around the 6th century BCE, he renounced everything to live as a wandering ascetic, and after twelve years of intense discipline attained Kevala Jnana — perfect, all-seeing knowledge.\", \"The first principle of Jainism is ahimsa — absolute non-violence toward all living beings, in thought, word, and deed. Jains take care even with the air they breathe and the ground they walk on, filtering water and sweeping paths to avoid harming invisible creatures. This extreme care is not weakness; it is the highest expression of reverence for life.\", \"Jainism teaches that every soul is eternal, pure, and capable of infinite knowledge and bliss. Karma is not a punishment but a fine dust of past actions that clings to the soul; liberation is the gradual removal of that dust through right faith, right knowledge, and right conduct — the Three Jewels.\", \"Its cosmology is breathtaking in ambition: a universe without beginning or end, populated with gods, humans, animals, and beings in countless realms, all bound by the same laws of karma. Jain monks mapped this cosmos in intricate diagrams centuries ago.\", \"Though its followers were never numerous, Jain influence is everywhere in Bhārat — in vegetarianism, in the ecological care now being rediscovered by environmentalists, and in the dazzling temples of Rajasthan and Gujarat built to honour non-violence.\"]', '[{\"text\": \"Absolute non-violence to all living beings in thought, word, and deed — the supreme law.\", \"title\": \"Ahimsa\"}, {\"text\": \"Reality is many-sided; truth can be seen from multiple viewpoints, so stay humble and open.\", \"title\": \"Anekantavada\"}, {\"text\": \"Right faith, right knowledge, and right conduct — together they dissolve the karmic dust from the soul.\", \"title\": \"The Three Jewels\"}, {\"text\": \"Past actions cling to the soul like fine dust; liberation is total purification.\", \"title\": \"Karma as Particles\"}, {\"text\": \"From the elephant to the ant, every being carries a soul worthy of protection.\", \"title\": \"Respect for All Life\"}]', 'Jainism gave Bhārat its tradition of vegetarianism, its most rigorous environmental ethics, and the profound idea that truth has many faces. Mahatma Gandhi, the apostle of non-violence, named the Jains as a source of his ahimsa — a philosophy born in Bihar that helped free a nation.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (9, 'ideas', 'charvaka', 'Charvaka', 'चार्वाक', 'The materialists — Bhārat\'s ancient voice of doubt and joy', 'Śramaṇa', 'c. 7th–6th c. BCE', 'Brihaspati (legendary) — the Lokayata tradition', 'North Bhārat', NULL, NULL, 'Sparkles', 'from-[#475569] to-[#94A3B8]', 'bg-slate-100 text-slate-700 border-slate-200', 'text-slate-600', 'Yavaj jivet sukham jivet — \'Live happily as long as you live\'', 'Charvaka aphorism', 'Not every philosopher of ancient Bhārat believed in the soul, the gods, or the afterlife. The Charvakas — also called Lokayatas — were Bhārat\'s hard-headed materialists: only what you can see, touch, and prove is real. Enjoy life now, they said, for this world is all there is.', '[\"In a civilization famous for its mysticism, Charvaka was the great exception — and proof that ancient Bhārat tolerated radical dissent. The Charvakas (or Lokayatas, \'those who hold to this world\') rejected the Vedas, the soul, rebirth, and the gods as unfounded inventions. Their only pramana was perception: if you cannot see it, test it, or taste it, do not believe it.\", \"Their famous motto — \'Live happily as long as you live\' — is a complete philosophy in a line. Since no one returns from the dead to report on the afterlife, they argued, the wise person enjoys the life they can actually verify. They recommended simple pleasures: good food, friendship, and honest work.\", \"Charvaka\'s role was not to be the final word but to be the permanent question-mark — the devil\'s advocate of philosophy of Bhārat. Every serious school had to answer the Charvaka challenge. When the idealists said the world was an illusion, the Charvakas pointed at a stone and said, \'Then drop it on your foot.\' Their arguments forced everyone else to think harder.\", \"Few Charvaka texts survive — their opponents burned and quoted them selectively — but their questions echo through all of thought of Bhārat. Even today, every debate about faith and evidence in Bhārat walks in the footprints of these ancient doubters.\"]', '[{\"text\": \"What you cannot perceive or prove is, until proven, unworthy of belief.\", \"title\": \"Only Perception\"}, {\"text\": \"The good life is the verifiable one: pleasure, friendship, honest work, and no borrowed guilt.\", \"title\": \"Enjoy This Life\"}, {\"text\": \"Scripture and tradition are not evidence; ask \'who saw it?\' before you believe.\", \"title\": \"Against Authority\"}, {\"text\": \"Scepticism is a service to truth — it forces every belief to prove itself.\", \"title\": \"The Noble Doubt\"}, {\"text\": \"The physical world is not illusion; matter, energy, and the body are the true arena of life.\", \"title\": \"The World Is Real\"}]', 'Charvaka is proof that ancient Bhārat was no echo chamber — it hosted some of the world\'s earliest and boldest materialism. Its spirit of healthy doubt lives on in every person of Bhārat who asks for evidence, and its joy-of-life philosophy remains a refreshing counterweight to world-denying asceticism.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (10, 'ideas', 'ajivika', 'Ajivika', 'आजीविक', 'The fatalists — destiny rules all, so live with serene acceptance', 'Śramaṇa', 'c. 6th–4th c. BCE', 'Makkhali Gosala', 'Bihar & Karnataka (Sravanabelagola)', NULL, NULL, 'Moon', 'from-[#581C87] to-[#9333EA]', 'bg-purple-50 text-purple-700 border-purple-200', 'text-purple-600', 'Niyati — \'All things are governed by destiny; nothing can change the course of fate\'', 'Ajivika teaching', 'The Ajivikas were a fierce, ascetic order that taught a startling idea: everything is decided by niyati, an iron law of destiny. No effort, prayer, or penance can change what is written. Their ruthless honesty — and their disappearance — is one of the strangest chapters of Bhārat\'s philosophical history.', '[\"Founded by Makkhali Gosala, a contemporary of both Mahavira and the Buddha, the Ajivikas flourished in the very same Ganges valley debates of the 6th century BCE. They were among the six great teachers of that age whom the Buddhist and Jain scriptures record — respected enough to be argued with, feared enough to be remembered.\", \"The Ajivika doctrine was niyati — destiny. The universe, they taught, unfolds according to a fixed cosmic law: every soul must transmigrate through millions of existences, rising and falling, until after a precisely determined span it reaches liberation — for everyone, without exception, and without anyone\'s effort mattering. Even the gods were bound by the same iron necessity.\", \"Their lifestyle was extreme: naked asceticism, total indifference to comfort, begging, and a life of astonishing discipline. Their fatalism did not make them lazy — by all accounts they practised an asceticism as intense as any in Bhārat. Accepting fate, they seemed to say, is not surrender; it is clarity.\", \"Ajivika centres existed across Bhārat, from Bihar to Karnataka, and the Mauryan emperor Bindusara was said to be sympathetic to them. But without monasteries of scriptures to preserve them, the order slowly faded, leaving only fragments quoted in the texts of their rivals.\"]', '[{\"text\": \"An iron law of destiny governs every event; nothing is random and nothing can be changed.\", \"title\": \"Niyati\"}, {\"text\": \"Every soul will eventually reach the end of its journey — liberation is guaranteed by cosmic law.\", \"title\": \"Universal Liberation\"}, {\"text\": \"Since fate rules, the wise live free of desire — with a discipline that awed their rivals.\", \"title\": \"Radical Asceticism\"}, {\"text\": \"Effort cannot alter the outcome — an idea that provoked the sharpest rebuttals of its age.\", \"title\": \"No Free Will\"}, {\"text\": \"The Ajivikas forced Buddhism and Jainism to defend free will — sharpening both in the process.\", \"title\": \"A Serious Challenge\"}]', 'The Ajivikas are Bhārat\'s great \'lost\' philosophy — the road not taken. Their fate, and the questions they raised about free will and destiny, sharpened every rival school and still haunt ethical debate today: how much of our life is choice, and how much is written?', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (11, 'ideas', 'bhakti', 'The Bhakti Movement', 'भक्ति', 'Love is the path — the democracy of devotion that swept Bhārat', 'Devotional', '6th – 17th c. CE', 'The Alvars & Nayanars; carried by Kabir, Mirabai, Tukaram & countless others', 'Born in Tamil Nadu, spread to every corner of Bhārat', NULL, NULL, 'Heart', 'from-[#BE123C] to-[#F43F5E]', 'bg-rose-50 text-rose-700 border-rose-200', 'text-rose-600', 'Dhai akshar prem ke, padhe so pandit hoy — \'One who reads the two-and-a-half letters of love is the true scholar\'', 'Sant Kabir', 'Bhakti — devotion — is not one philosophy but a revolution of the heart. Beginning with Tamil saints singing in the streets, it swept across Bhārat: saints of every caste and gender, composing songs in ordinary languages, declaring that God needs no priest, no temple, no Sanskrit — only love.', '[\"Around the 6th century CE, in Tamil Nadu, a movement began that would transform Bhārat. The Alvars, devoted to Vishnu, and the Nayanars, devoted to Shiva, composed ecstatic hymns in Tamil — the language of the people, not the priests. They walked from temple to temple, singing that the divine was not far away but closer than one\'s own breath.\", \"For the first time, spirituality was thrown open to everyone. The Bhakti saints included a weaver (Kabir), a princess (Mirabai), a cobbler (Ravidas), a potter (Gora Kumbhar), a low-caste farmer\'s son (Namdev), and a widow (Akka Mahadevi). Caste, gender, and wealth became irrelevant before the single qualification of love.\", \"In the 12th century, Basavanna\'s Lingayat movement in Karnataka preached \'work is worship\' and the equality of all devotees. In the 15th century, Kabir in Varanasi mocked empty ritual — \'pothi padh padh jag mua\' — while the Sufi tradition of the same age shared the same language of divine love. The streams mingled.\", \"The Bhakti saints composed in their mother tongues — Tamil, Kannada, Marathi, Braj, Awadhi, Punjabi — creating the literatures that people of Bhārat still sing and recite today. They taught that the path to God is not through head-learning but through surrender, song, and service.\", \"From the Rajput princess Mirabai dancing before Krishna to the Maratha saint Tukaram singing of Vithoba, from Guru Nanak\'s hymns to Chaitanya\'s kirtans in Bengal, the Bhakti movement became the single greatest cultural force of history of Bhārat — and it continues in every bhajan sung in every home of Bhārat.\"]', '[{\"text\": \"Sincere devotion matters more than any ceremony, pilgrimage, or priestly rite.\", \"title\": \"Love Over Ritual\"}, {\"text\": \"Caste, gender, and wealth do not reach God; only the heart does.\", \"title\": \"Equality of All\"}, {\"text\": \"Compose in the mother tongue — let the street hear what the temple whispered.\", \"title\": \"Songs of the People\"}, {\"text\": \"The divine is near — a friend, a beloved, a parent — not a distant judge.\", \"title\": \"God Within Reach\"}, {\"text\": \"Serving others is the truest worship of the divine.\", \"title\": \"Seva (Service)\"}]', 'Bhakti gave Bhārat its saint-poets, its bhajans, its culture of congregational singing, and a thousand-year tradition of social levelling. It inspired Guru Nanak, shaped modern Hinduism, and planted the seeds of the social reform movements that would one day help free Bhārat.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (12, 'ideas', 'sikhism', 'Sikhism', 'सिख धर्म', 'The path of the disciple — One God, honest work, and service to all', 'Devotional', '15th c. CE – present', 'Guru Nanak Dev (1469–1539)', 'Punjab', NULL, NULL, 'Sun', 'from-[#1D4ED8] to-[#3B82F6]', 'bg-blue-50 text-blue-700 border-blue-200', 'text-blue-600', 'Ik Onkar — \'There is but One God, and all humanity is one family\'', 'Mool Mantra, Guru Granth Sahib', 'Born in the land of five rivers, Sikhism began when Guru Nanak emerged from a river bath declaring, \'There is no Hindu, there is no Muslim.\' His message — one God, honest work, sharing with all, and loving service — grew into a world religion of warrior-saints whose gurdwaras feed millions, free of charge.', '[\"In 1499, at the town of Sultanpur Lodhi in Punjab, the young Guru Nanak went to bathe in the river — and vanished for three days. He emerged transformed, with a single sentence: \'Na koi Hindu, na koi Musalman\' — there is no Hindu, there is no Muslim. Humanity, he declared, is one family under one God.\", \"Guru Nanak then walked across Bhārat and far beyond — to Mecca, Tibet, and Sri Lanka — singing and teaching. His message was radical in its simplicity: believe in one formless God (Ik Onkar); live by honest work (kirt karo); share your earnings with the needy (vand chhako); and treat all people as equals, for caste and gender mean nothing before God.\", \"He rejected ritualism, idol worship, and fasting — and instead of renouncing the world, he taught that the householder\'s life, lived with integrity, is the truest spiritual path. Service (seva) became the highest worship: his followers ran free kitchens (langar) where prince and peasant ate together, side by side.\", \"Nine Gurus followed Nanak, each adding to the tradition. The tenth, Guru Gobind Singh, created the Khalsa — the community of the pure — and declared that after him, the scripture itself, the Guru Granth Sahib, would be the eternal Guru. Its 1,430 pages of hymns and teachings, composed by Sikhs, Hindus, and Muslims alike, are treated with the reverence due to a living teacher.\", \"Sikh history is a story of both profound peace and fierce defence. When the Mughal empire began executing those who refused to convert, the Gurus taught that the saint must also be a soldier — the sant-sipahi. The Golden Temple at Amritsar, the langar that feeds a hundred thousand visitors daily, and the Sikh diaspora serving communities worldwide all carry forward the vision of Guru Nanak.\"]', '[{\"text\": \"There is one formless God, beyond all names and forms — and humanity is one family under that One.\", \"title\": \"Ik Onkar\"}, {\"text\": \"Live by honest labour; earn your bread with your own hands and your own integrity.\", \"title\": \"Kirt Karo\"}, {\"text\": \"Share what you have — the langar kitchen where all eat together is Sikhism\'s living heart.\", \"title\": \"Vand Chhako\"}, {\"text\": \"Selfless service to others is the highest form of worship.\", \"title\": \"Seva\"}, {\"text\": \"The saint who is also a soldier: compassion in peace, courage in the defence of justice.\", \"title\": \"Sant-Sipahi\"}]', 'From a single seeker in 15th-century Punjab, Sikhism grew into a world faith of some 25 million people. Its gurdwaras feed millions daily, its soldiers of justice fought empires, and its ideals of equality, service, and honest work continue to inspire — a philosophy of the disciple, born in Bhārat.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (13, 'ideas', 'tantra', 'Tantra', 'तंत्र', 'The body as temple — the philosophy that sacredness lives in the world', 'Esoteric', 'c. 5th – 11th c. CE', 'Anonymous sages; perfected by Abhinavagupta in Kashmir', 'Kashmir, Bengal, Kerala', NULL, NULL, 'Zap', 'from-[#831843] to-[#DB2777]', 'bg-pink-50 text-pink-700 border-pink-200', 'text-pink-600', 'Yatha pinde tatha brahmande — \'As in the body, so in the cosmos\'', 'Tantric aphorism', 'Tantra is Bhārat\'s most misunderstood philosophy. In its classical form it is not about magic or excess — it is a daring claim that the body and the world are not prisons to escape but temples to be awakened. Everything in the cosmos, it says, is pulsating divine energy.', '[\"The word tantra means \'loom\' or \'system\' — a practical framework of practice. Between the 5th and 11th centuries CE, an extraordinary spiritual current rose in Kashmir, Bengal, and Kerala that rejected the idea of renouncing the world. Instead, it taught that the divine is not beyond creation — it is creation.\", \"In the philosophy of Kashmir Shaivism, associated with the great sage Abhinavagupta, the ultimate reality is Shiva — pure consciousness — which freely manifests the entire universe as its own play (leela). The world is therefore not illusion but the dance of the divine. Matter, body, senses — all are sacred.\", \"This is why tantra uses \'forbidden\' things as instruments: because nothing is truly forbidden when everything is divine. The tantric practitioner aims to transform energy — including sexuality, emotion, and desire — into awakened consciousness, through mantra (sacred sound), yantra (sacred geometry), ritual, and meditation.\", \"Tantra radically honoured the feminine. The Goddess (Devi) is not an auxiliary but the supreme power of the cosmos; Shakti is the dynamic energy of consciousness itself. Temples, rituals, and art across Bhārat — from Kali worship in Bengal to the kundalini yoga of the yogic tradition — carry this vision.\", \"Tantra\'s practical genius survives in the kundalini and chakra systems of yoga, in the mantras chanted daily across Bhārat, and in the stunning temple architecture built as three-dimensional yantras. Behind the sensational stories, its core teaching remains: awaken the divine energy within you, and you will see the cosmos shining in every particle.\"]', '[{\"text\": \"Creation is the body of the divine — the material world is not to be fled but awakened.\", \"title\": \"The World Is Sacred\"}, {\"text\": \"The feminine power of consciousness is the creative energy of the entire cosmos.\", \"title\": \"Shakti\"}, {\"text\": \"The human body contains the whole universe in miniature — a map of the cosmos.\", \"title\": \"Body as Temple\"}, {\"text\": \"Sacred sound and sacred geometry are practical technologies for transforming consciousness.\", \"title\": \"Mantra & Yantra\"}, {\"text\": \"The coiled energy at the base of the spine can be awakened to rise through the subtle body.\", \"title\": \"Kundalini\"}]', 'Tantra flows through every stream of later spirituality of Bhārat — the chakras and kundalini of yoga, the Devi worship of Bengal, the temple architecture of the South. It gave Bhārat its boldest claim: you need not leave the world to find God; the world itself is the doorway.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (14, 'places', 'taj-mahal', 'Taj Mahal', 'ताजमहल', 'A teardrop on the cheek of time — the world\'s great monument to love', 'Monuments & Forts', '1632 – 1653', 'Emperor Shah Jahan', 'Agra, Uttar Pradesh', 27.1750075, 78.0421013, 'Landmark', 'from-[#0A2240] to-[#1A3A5C]', 'bg-sky-50 text-sky-700 border-sky-200', 'text-sky-600', 'A teardrop on the cheek of time.', 'Rabindranath Tagore', 'The Taj Mahal is one of the New Seven Wonders of the World and Bhārat\'s most recognised face. Built by Emperor Shah Jahan in memory of his wife Mumtaz Mahal, its white marble dome seems to change colour with every hour of the sky.', '[\"When Mumtaz Mahal, the beloved wife of Emperor Shah Jahan, died in 1631, the grief-stricken emperor vowed to build her a tomb unlike any on Earth. Twenty thousand artisans worked for over twenty years, shaping pure white marble brought from Makrana in Rajasthan and inlaying it with jade, crystal, and turquoise from across Asia.\", \"The Taj is a masterclass in symmetry. Its four minarets lean slightly outward — an ingenious design so they would never fall on the tomb even in an earthquake. In front lies a long reflecting pool and a charbagh, a garden divided into four, meant to echo the gardens of paradise described in the Quran.\", \"The tomb\'s true magic is its changing light: pale pink at dawn, dazzling white at noon, golden at sunset, and silvery under the full moon. A UNESCO World Heritage Site since 1983, the Taj draws millions of visitors every year — and every one of them falls a little in love.\"]', '[{\"text\": \"Built by a grieving emperor for his wife — perhaps the most romantic building ever raised.\", \"title\": \"A Monument to Love\"}, {\"text\": \"Mirror-image design with leaning minarets that protect the tomb from earthquakes.\", \"title\": \"Perfect Symmetry\"}, {\"text\": \"Thousands of semi-precious stones inlaid in marble to create flowers that never fade.\", \"title\": \"Pietra Dura\"}, {\"text\": \"The charbagh garden represents the four rivers of paradise in Islamic thought.\", \"title\": \"Gardens of Paradise\"}, {\"text\": \"The marble shifts from pink to gold to silver-white with the passage of the sun.\", \"title\": \"Light that Breathes\"}]', 'More than a building, the Taj Mahal is the world\'s shorthand for love and the pride of Agra and Bhārat. It inspired countless imitations — from palaces in Delhi to a monument in Dhaka — and proves that one man\'s grief can become humanity\'s treasure.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (15, 'places', 'red-fort', 'Red Fort', 'लाल किला', 'The fortress from whose ramparts free Bhārat spoke its first words', 'Monuments & Forts', 1648, 'Emperor Shah Jahan', 'Delhi', 28.6560810, 77.2407959, 'Castle', 'from-[#7C2D12] to-[#C2410C]', 'bg-orange-50 text-orange-700 border-orange-200', 'text-orange-600', 'At the stroke of the midnight hour, when the world sleeps, Bhārat will awake to life and freedom.', 'Jawaharlal Nehru, 15 August 1947', 'The Red Fort — Lal Qila — is Delhi\'s great red-sandstone fortress, seat of Mughal power for two centuries and the stage where Bhārat\'s freedom was declared. Every Independence Day, the Prime Minister hoists the tricolour from its ramparts.', '[\"Shah Jahan, the builder of the Taj Mahal, moved his capital from Agra to Delhi in 1638 and raised a palace-fortress unlike any other: two kilometres of walls in blood-red sandstone, enclosing a world of marble halls, gardens, and fountains. It was called Shahjahanabad — and it became the heart of the Mughal empire.\", \"Inside its walls, the Diwan-i-Am (Hall of Public Audience) once thronged with petitioners, while the Diwan-i-Khas (Hall of Private Audience) glittered with the legendary Peacock Throne, studded with gems. A canal called the \'Stream of Paradise\' once ran through the fort, cooling its courtyards.\", \"On 15 August 1947, Jawaharlal Nehru raised the flag of free Bhārat from the fort\'s Lahore Gate and delivered his famous \'Tryst with Destiny\' speech. Since then, the Red Fort has been the symbol of independence of Bhārat — the place where the nation celebrates its freedom every year.\"]', '[{\"text\": \"Built by Shah Jahan to house the most powerful court on the subcontinent.\", \"title\": \"The Capital of an Empire\"}, {\"text\": \"Over two kilometres of massive walls and a masterwork of Mughal military architecture.\", \"title\": \"Red Sandstone Majesty\"}, {\"text\": \"The public and private audience halls where emperors ruled and legends were made.\", \"title\": \"Halls of Power\"}, {\"text\": \"From these ramparts, free Bhārat was proclaimed at the stroke of midnight, 1947.\", \"title\": \"Tryst with Destiny\"}, {\"text\": \"Every Independence Day, the nation\'s flag rises here — watched by all of Bhārat.\", \"title\": \"A Living Flag\"}]', 'The Red Fort is both a UNESCO World Heritage Site and the emotional centre of nationhood of Bhārat. It is where a dynasty lived, where an empire fell, and where a free republic declared itself to the world.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (16, 'places', 'qutub-minar', 'Qutub Minar', 'क़ुतुब मीनार', 'The world\'s tallest brick minaret — Delhi\'s soaring stone tower', 'Monuments & Forts', '12th – 13th c. CE', 'Qutbuddin Aibak & Iltutmish', 'Delhi', 28.5244130, 77.1854501, 'Building2', 'from-[#92400E] to-[#B45309]', 'bg-amber-50 text-amber-700 border-amber-200', 'text-amber-600', NULL, NULL, 'Rising 72.5 metres over Delhi, the Qutub Minar is the world\'s tallest brick minaret — five storeys of fluted sandstone and marble, carved with verses from the Quran. Beside it stands a mystery: an iron pillar that has refused to rust for 1,600 years.', '[\"Construction of the Qutub Minar began around 1192 under Qutbuddin Aibak, founder of the Delhi Sultanate, and was completed by his successor Iltutmish. Each of its five storeys tapers upward — the first three of red sandstone, the upper two faced with marble — ringed with balconies and intricate calligraphy.\", \"The tower is part of the Qutub Complex, a garden of ruins including the Quwwat-ul-Islam mosque — one of the earliest mosques in Bhārat — and a towering iron pillar that has baffled scientists. Cast in the 4th century, the pillar has withstood 1,600 monsoons without rusting, thanks to an ancient mastery of iron chemistry.\", \"Climbing the 379 steps rewards you with a view over Delhi\'s skyline, but the minaret itself — a statement of victory built in the language of stone and sky — is the true spectacle. On Independence Day and Republic Day, it is illuminated with the colours of the flag of Bhārat.\"]', '[{\"text\": \"72.5 metres high — the tallest brick minaret in the world.\", \"title\": \"Tallest Brick Minaret\"}, {\"text\": \"Five storeys carved with bands of Quranic verses and floral motifs.\", \"title\": \"Calligraphy in Stone\"}, {\"text\": \"A 1,600-year-old iron pillar near the tower that never rusts.\", \"title\": \"The Rustless Pillar\"}, {\"text\": \"Begun by Qutbuddin Aibak and finished by Iltutmish and Firoz Shah Tughlaq.\", \"title\": \"A Dynasty\'s Signature\"}, {\"text\": \"Part of Delhi\'s Qutub Complex, a UNESCO World Heritage Site.\", \"title\": \"UNESCO Heritage\"}]', 'The Qutub Minar has dominated Delhi\'s skyline for eight centuries and remains one of Bhārat\'s most visited monuments. Alongside its neighbour the Iron Pillar, it stands for an age when builders and metallurgists of Bhārat set world records.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (17, 'places', 'hampi', 'Hampi', 'हम्पी', 'The city of victory — ruins of a golden empire among the boulders', 'Ancient Marvels', '14th – 16th c. CE', 'The Vijayanagara Empire', 'Karnataka', 15.3358000, 76.4610201, 'Gem', 'from-[#9A3412] to-[#EA580C]', 'bg-orange-50 text-orange-700 border-orange-200', 'text-orange-600', 'Hampi is a city of palaces, a dream in stone and granite.', 'Abdul Razzaq, Persian traveller, 1443', 'Hampi was the capital of the Vijayanagara Empire — one of the richest cities in the world. Today its palaces, temples, and stone chariots lie scattered across a surreal landscape of giant boulders, whispering the glory of a vanished golden age.', '[\"At its peak in the 15th and 16th centuries, Hampi was said to rival Rome. Merchants from Persia, Portugal, and China crowded its markets of diamonds, pearls, and silks. The city stretched for miles, wrapped around the sacred Tungabhadra river and the hill where, legend says, Hanuman was born.\", \"The empire fell in 1565, but its stone genius survived. The Virupaksha Temple still rises 50 metres over the ruins, its gopuram alive with painted stories. The famous stone chariot at the Vittala Temple — carved from a single block, its wheels once turning — is the emblem of tourism itself of Bhārat.\", \"What makes Hampi otherworldly is its setting: boulders the size of houses, stacked by time into mountains, glowing pink and gold at sunset. Monkeys scramble over the ruins, and the whole site — a UNESCO World Heritage Site — feels like a city that simply walked away.\"]', '[{\"text\": \"Home of one of the richest empires in world history.\", \"title\": \"Capital of Vijayanagara\"}, {\"text\": \"Vittala Temple\'s chariot, carved from one rock, with wheels that once turned.\", \"title\": \"The Stone Chariot\"}, {\"text\": \"Still a living temple — worship continues amid the ruins after 600 years.\", \"title\": \"Virupaksha Temple\"}, {\"text\": \"A surreal terrain of giant granite boulders, sacred to Hanuman lore.\", \"title\": \"Boulder Landscape\"}, {\"text\": \"Traders from Persia, Portugal, and China thronged its markets.\", \"title\": \"Global Bazaar\"}]', 'Hampi is Bhārat\'s grandest ruin and one of its most magical sites. Its temples, chariots, and bazaar streets make it a living museum of a civilization that once dazzled the world.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (18, 'places', 'khajuraho', 'Khajuraho', 'खजुराहो', 'A thousand sculpted gods and lovers carved in sandstone', 'Ancient Marvels', '10th – 11th c. CE', 'The Chandela dynasty', 'Madhya Pradesh', 24.8515132, 79.9259786, 'Diamond', 'from-[#7E22CE] to-[#A855F7]', 'bg-purple-50 text-purple-700 border-purple-200', 'text-purple-600', 'The sculptures of Khajuraho are one of the greatest artistic achievements of the human race.', 'UNESCO', 'The Chandela kings of Bundelkhand raised 85 temples at Khajuraho, of which 22 survive — a sandstone gallery of gods, dancers, warriors, and lovers. Its sculptures celebrate every side of life, from the divine to the everyday, with an artistry the world still marvels at.', '[\"Between the 10th and 11th centuries, the Chandela dynasty built a city of temples at Khajuraho, each rising like a mountain of sculpted sandstone. Their shikharas (spires) climb in ever-ascending tiers, mimicking the peaks of the Himalayas where the gods were said to dwell.\", \"The temples are covered edge to edge with carving: celestial nymphs (apsaras) removing their anklets, elephants at war, musicians, dancers, and couples in embrace. For the sculptors of Khajuraho, nothing human was foreign to the divine — the temples show that sacred and everyday life are one.\", \"After the Chandelas fell, the temples were swallowed by the jungle for centuries, hidden under a canopy of khajur (date-palm) trees — which gave the town its name. Rediscovered in the 19th century and now a UNESCO World Heritage Site, Khajuraho draws pilgrims and art lovers from across the planet.\"]', '[{\"text\": \"85 temples built by the Chandela dynasty; 22 survive in marvellous condition.\", \"title\": \"A City of Temples\"}, {\"text\": \"Thousands of sculptures — gods, dancers, warriors, and celestial maidens.\", \"title\": \"Apsaras & Artistry\"}, {\"text\": \"A rare ancient monument that celebrates life\'s every dimension.\", \"title\": \"Sacred Meets Everyday\"}, {\"text\": \"Spires stacked to imitate the Himalayan abode of the gods.\", \"title\": \"Rising Shikharas\"}, {\"text\": \"Hidden under date-palm forests for centuries, rediscovered in the 1800s.\", \"title\": \"Lost in the Jungle\"}]', 'Khajuraho is a UNESCO World Heritage Site and one of the finest open-air sculpture galleries on Earth. It reminds the world that ancient Bhārat honoured not just the spirit but the full, joyful life of the body.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (19, 'places', 'konark-sun-temple', 'Konark Sun Temple', 'कोणार्क सूर्य मंदिर', 'The chariot of the Sun God, frozen mid-ride in stone', 'Ancient Marvels', '13th c. CE', 'King Narasimhadeva I', 'Konark, Odisha', 19.8875639, 86.0944895, 'Sun', 'from-[#B45309] to-[#F59E0B]', 'bg-amber-50 text-amber-700 border-amber-200', 'text-amber-600', 'Here the stones speak a language of poetry and prayer.', 'Inscription at the temple', 'Konark is a temple built as a colossal chariot: twenty-four carved wheels, seven horses, and a sanctum that once held a floating idol of Surya, the Sun God. The Black Pagoda, as sailors called it, is the pinnacle of Odisha\'s temple art.', '[\"In the 13th century, King Narasimhadeva I of the Ganga dynasty raised the Sun Temple at Konark on the shores of the Bay of Bengal. Built as a giant chariot of Surya, it was meant to ride the sky, drawn by seven galloping horses — the seven days of the week — on twelve pairs of wheels, the twelve months.\", \"Each wheel is a sundial carved in stone, its spokes marking the hours so precisely that modern astronomers can still read the time from their shadows. The temple walls teem with sculpture: musicians, dancers, elephants, and the legendary erotic carvings that crown Odisha\'s artistry.\", \"Seafarers called the temple the Black Pagoda — its dark silhouette guiding ships home. The main sanctum has partly collapsed, but the great wheel — the national symbol of Bhārat\'s tourism — still turns the imagination of every visitor who circles it.\"]', '[{\"text\": \"The whole temple is a giant chariot of the Sun God with 24 wheels and 7 horses.\", \"title\": \"A Chariot of Stone\"}, {\"text\": \"Each wheel is a precisely engineered sundial.\", \"title\": \"Wheels That Tell Time\"}, {\"text\": \"A lighthouse for ancient sailors, its silhouette guiding ships home.\", \"title\": \"The Black Pagoda\"}, {\"text\": \"The finest achievement of the Kalinga school of temple art.\", \"title\": \"Odisha\'s Sculptural Peak\"}, {\"text\": \"A World Heritage Site and the emblem of tourism of Bhārat.\", \"title\": \"UNESCO Heritage\"}]', 'The Konark Sun Temple is one of Bhārat\'s proudest UNESCO World Heritage Sites. Its wheel has become the symbol of Incredible India itself — a nation forever in motion, like the Sun God\'s chariot racing across the sky.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (20, 'places', 'ajanta-ellora', 'Ajanta & Ellora Caves', 'अजंता-एलोरा', 'Temples carved from the heart of mountains — a world heritage of wonder', 'Ancient Marvels', '2nd c. BCE – 8th c. CE', 'Buddhist, Hindu & Jain monks and artisans', 'Maharashtra', 19.5670323, 76.4164557, 'Mountain', 'from-[#44403C] to-[#78716C]', 'bg-stone-100 text-stone-700 border-stone-200', 'text-stone-600', 'Here art and faith were chiselled out of living rock for a thousand years.', 'UNESCO inscription', 'In the hills of Maharashtra, monks and artisans carved entire temples out of solid rock — over sixty caves of worship, monasteries, murals, and statues that span a thousand years. Ajanta holds the world\'s greatest surviving Buddhist paintings; Ellora holds the Kailasa, the largest monolith temple on Earth.', '[\"The Ajanta caves, cut into a horseshoe-shaped cliff, were carved between the 2nd century BCE and the 5th century CE as Buddhist monasteries and prayer halls. Their walls still glow with ancient murals — the finest surviving paintings of the ancient world — telling the life stories of the Buddha with grace and colour that time has not erased.\", \"Just a hundred kilometres away, the Ellora caves push the art even further: 34 caves of Buddhism, Hinduism, and Jainism carved side by side in peace. Its crowning glory is the Kailasa temple — an entire palace of gods, three times the size of the Parthenon, chiselled top-down from a single mountain.\", \"To build Kailasa, artisans reportedly removed three million cubic feet of rock. It is the largest monolithic sculpture on Earth — not assembled, not stacked, but simply revealed from within the mountain. Both sites together are a single UNESCO World Heritage listing and one of Bhārat\'s most breathtaking journeys into the past.\"]', '[{\"text\": \"Over 60 temples and monasteries carved from solid mountains.\", \"title\": \"Caves in Living Rock\"}, {\"text\": \"The greatest surviving paintings of the ancient world — 1,500 years old.\", \"title\": \"Ajanta\'s Murals\"}, {\"text\": \"Buddhist, Hindu, and Jain caves carved side by side in harmony.\", \"title\": \"Three Faiths Together\"}, {\"text\": \"The largest monolith temple on Earth, carved top-down from one rock.\", \"title\": \"The Kailasa Temple\"}, {\"text\": \"A thousand years of carving, from 200 BCE to 800 CE.\", \"title\": \"A Millennium of Art\"}]', 'Ajanta and Ellora are the ultimate proof of Bhārat\'s ancient patience and genius — a thousand years of art carved in darkness, now shining in the sunlight of world heritage.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (21, 'places', 'golden-temple', 'Golden Temple', 'स्वर्ण मंदिर', 'Amritsar\'s house of gold, where all are welcome and none go hungry', 'Spiritual Sites', '1589 – 1604 (completed)', 'Guru Arjan Dev, 5th Sikh Guru', 'Amritsar, Punjab', 31.6199787, 74.8765281, 'Droplets', 'from-[#1E40AF] to-[#3B82F6]', 'bg-amber-50 text-amber-600 border-amber-200', 'text-amber-600', 'My temple is open to all — high and low, prince and pauper, without distinction.', 'Guru Nanak\'s vision, embodied at Harmandir Sahib', 'The Harmandir Sahib — the Golden Temple — glows over the Amrit Sarovar, the \'pool of nectar\' that gives Amritsar its name. It is the holiest shrine of Sikhism, a sanctuary open to every person on Earth, where the largest free kitchen in the world feeds a hundred thousand visitors a day.', '[\"The fifth Sikh Guru, Arjan Dev, laid the temple\'s foundation in 1589 on an island in the middle of a sacred pool. Uniquely among great shrines, it has four doors — one on each side — declaring that people of every faith and station may enter and be equally welcome.\", \"In the early 19th century, Maharaja Ranjit Singh sheathed the upper floors in pure gold, giving the shrine its name. Inside, the Guru Granth Sahib — the Sikh scripture — is recited continuously from dawn to dusk, and the temple\'s marble walkways circle the pool where pilgrims bathe and pray.\", \"The temple\'s langar — its free community kitchen — is a miracle of everyday kindness: volunteers of every background peel, cook, and serve simple meals to anyone who arrives, prince or pauper, sitting side by side. Every day, the Golden Temple feeds more people than many restaurants feed in a year — and it never charges a single rupee.\"]', '[{\"text\": \"Doors on every side welcome people of all faiths and backgrounds.\", \"title\": \"Four Open Doors\"}, {\"text\": \"The Amrit Sarovar, the sacred tank that gives Amritsar its name.\", \"title\": \"The Pool of Nectar\"}, {\"text\": \"Ranjit Singh\'s gift — upper floors plated in pure gold.\", \"title\": \"Gilded Glory\"}, {\"text\": \"The Guru Granth Sahib is read aloud without pause, every single day.\", \"title\": \"The Eternal Reading\"}, {\"text\": \"The world\'s largest free kitchen — 100,000 meals a day, served to all.\", \"title\": \"The Langar\"}]', 'The Golden Temple is Sikhism\'s living heart and one of the world\'s most visited religious sites. Its message is carved in action, not just words: equality is not an idea to be discussed but a meal to be shared.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (22, 'places', 'meenakshi-temple', 'Meenakshi Temple', 'मीनाक्षी मंदिर', 'Madurai\'s rainbow of towers — fourteen gopurams painted with gods', 'Spiritual Sites', 'Rebuilt 17th c.; origins ancient', 'The Nayak dynasty', 'Madurai, Tamil Nadu', 9.9188911, 78.1195482, 'Flame', 'from-[#9F1239] to-[#E11D48]', 'bg-rose-50 text-rose-700 border-rose-200', 'text-rose-600', 'The most considerable and most beautiful temple in all Bhārat.', 'David Ochterlony, 19th-century visitor', 'The Meenakshi Temple is a city within a city — fourteen towering gopurams painted in every colour, a thousand-pillared hall of carved stories, and one of the most beloved temples of South Bhārat, where the goddess Meenakshi reigns as queen.', '[\"Madurai is built around its temple, and the temple is built around its goddess: Meenakshi, whose name means \'fish-eyed\' — the sign of a steady, all-seeing gaze. Legends tell that she was born a warrior princess who conquered the world before marrying Sundareshwarar (Shiva) and ruling Madurai with him as its eternal queen.\", \"The temple\'s fourteen gopurams — towering gateway towers — rise like painted mountains, covered with some 33,000 sculptures of gods, demons, musicians, and mythical beasts. The tallest soars 52 metres. Inside, the Hall of a Thousand Pillars turns every pillar into a statue, no two alike.\", \"During the Chithirai festival, the marriage of Meenakshi and Sundareshwarar is re-enacted in a month-long celebration that pulls millions of devotees. In the evening, the temple fills with the glow of lamps and the sound of temple music — a rhythm that has beaten in Madurai for over a thousand years.\"]', '[{\"text\": \"A skyline of painted towers with 33,000 sculptures.\", \"title\": \"Fourteen Gopurams\"}, {\"text\": \"The warrior-queen goddess who rules the city of Madurai.\", \"title\": \"Goddess Meenakshi\"}, {\"text\": \"Every pillar a sculpture — no two alike in the great mandapa.\", \"title\": \"Hall of a Thousand Pillars\"}, {\"text\": \"The Golden Lotus Tank, where devotees bathe in holy water.\", \"title\": \"The Sacred Tank\"}, {\"text\": \"One of the oldest continually active temples in the world.\", \"title\": \"Living Worship\"}]', 'The Meenakshi Temple is the soul of Tamil culture — a living masterpiece where faith, art, and music have intertwined for a millennium. It draws millions of pilgrims and remains one of the most photographed wonders of South Bhārat.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (23, 'places', 'varanasi', 'Varanasi', 'वाराणसी', 'The oldest living city on Earth — the City of Light on the Ganga', 'Spiritual Sites', '3,000+ years — one of the world\'s oldest cities', 'Grown over millennia by countless generations', 'Banks of the Ganga, Uttar Pradesh', 25.3356491, 83.0076292, 'Waves', 'from-[#A16207] to-[#EAB308]', 'bg-yellow-50 text-yellow-700 border-yellow-200', 'text-yellow-600', 'Benares is older than history, older than tradition, older even than legend.', 'Mark Twain', 'Varanasi — Kashi, the City of Light — has been lived in for over three thousand years without a break, making it one of the world\'s oldest continuously inhabited cities. Its eighty ghats step down to the Ganga, where dawn aarti, evening lamps, and the endless prayer of pilgrims have played out for millennia.', '[\"Mark Twain called Varanasi \'older than history, older than tradition, older even than legend.\' For Hindus, it is the holiest of the seven sacred cities — the earthly home of Shiva, and a place where bathing in the Ganga and dying in its light are believed to bring liberation from the cycle of rebirth.\", \"At dawn, the riverfront comes alive: priests perform the Ganga Aarti at Dashashwamedh Ghat with fire, incense, and conch shells, while pilgrims bathe in the golden water as the sun rises over the eastern bank. Labyrinthine lanes behind the ghats hide thousands of temples, including the famous Kashi Vishwanath, its spire plated in gold.\", \"Varanasi is also one of the great seats of learning and culture — home to Sanskrit universities, classical music, and the art of Banarasi silk, woven in gold thread for centuries. Its ghats, its music, and its people have inspired poets, saints, and seekers from the Buddha (who preached his first sermon nearby) to Rabindranath Tagore.\"]', '[{\"text\": \"Inhabited continuously for over 3,000 years — the City of Light.\", \"title\": \"The Oldest Living City\"}, {\"text\": \"Stepped riverfronts where ritual, prayer, and life unfold daily.\", \"title\": \"Eighty Ghats\"}, {\"text\": \"Dawn and dusk fire ceremonies at Dashashwamedh Ghat.\", \"title\": \"The Ganga Aarti\"}, {\"text\": \"The golden-spired temple of Shiva, one of Hinduism\'s holiest shrines.\", \"title\": \"Kashi Vishwanath\"}, {\"text\": \"Home to Sanskrit scholarship, classical music, and Banarasi silk.\", \"title\": \"City of Learning & Art\"}]', 'Varanasi is Bhārat\'s eternal city — a place where three millennia of worship, art, and learning flow on like the river beside it. It is the spiritual capital of Bhārat and a living lesson in the continuity of human faith.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (24, 'places', 'gateway-of-india', 'Gateway of India', 'गेटवे ऑफ इंडिया', 'Mumbai\'s great arch — where a century of history meets the sea', 'Modern Landmarks', 1924, 'Designed by George Wittet; British Raj', 'Mumbai, Maharashtra', 18.9219661, 72.8345657, 'Anchor', 'from-[#0F172A] to-[#475569]', 'bg-slate-100 text-slate-700 border-slate-200', 'text-slate-600', NULL, NULL, 'Rising 26 metres above Mumbai\'s harbour, the Gateway of India was built to welcome emperors — and ended up watching an empire leave. Today it is the city\'s most iconic landmark and the bustling heart of its waterfront.', '[\"In 1911, King George V and Queen Mary arrived in Bombay, and the British Raj decided to commemorate the visit with a grand archway on the waterfront. Designed by George Wittet in Indo-Saracenic style — a fusion of architecture of Bhārat and Islam — the 26-metre basalt structure was completed in 1924, using yellow basalt and concrete.\", \"History loves irony: the Gateway built to welcome imperial rulers became the exit of the empire. In February 1948, the last British troops sailed away through the arch, and independent Bhārat claimed its most famous gateway. The structure\'s name, however, now celebrates a different entry — that of every visitor to Mumbai.\", \"Today the Gateway is Mumbai\'s living room. Ferries to Elephanta Island and the harbour buzz around it, street photographers and vendors crowd its steps, and the five-star Taj Mahal Palace Hotel stands guard beside it — together framing one of the most photographed waterfronts in Bhārat.\"]', '[{\"text\": \"Commemorating the 1911 royal visit of King George V and Queen Mary.\", \"title\": \"Built for a King\"}, {\"text\": \"A fusion of architecture of Bhārat and Islam in yellow basalt.\", \"title\": \"Indo-Saracenic Style\"}, {\"text\": \"The last British troops left Bhārat through this arch in 1948.\", \"title\": \"The Empire\'s Exit\"}, {\"text\": \"The grand arch that frames Mumbai\'s harbour.\", \"title\": \"26 Metres of Stone\"}, {\"text\": \"Ferries, crowds, and the famous Taj Palace beside it.\", \"title\": \"Mumbai\'s Living Room\"}]', 'The Gateway of India is Mumbai\'s emblem — a monument that watched an empire arrive and depart, and now welcomes the world to Bhārat\'s most energetic city.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (25, 'places', 'kerala-backwaters', 'Kerala Backwaters', 'केरल बैकवाटर्स', 'A 900-kilometre river of canals, palms, and houseboat dreams', 'Natural Wonders', 'Ancient ecosystems — lived on for centuries', 'The lagoons and canals of coastal Kerala', 'Alleppey & Kollam, Kerala', 9.5003416, 76.4123364, 'Sailboat', 'from-[#065F46] to-[#059669]', 'bg-emerald-50 text-emerald-700 border-emerald-200', 'text-emerald-600', 'God\'s own country — a green dream on still water.', 'Kerala\'s famous slogan', 'The Kerala backwaters are a network of over 900 kilometres of canals, lagoons, and lakes running parallel to the Arabian Sea. Glide past palm groves and paddy fields on a traditional houseboat, and you\'ll understand why Kerala is called God\'s Own Country.', '[\"The backwaters were formed over thousands of years as rivers met the sea, creating a quiet inland waterway lined with coconut palms, rice paddies, and sleepy villages. For centuries they were the highways of Kerala — boats carried rice, spices, and people along routes that still function today.\", \"The kettuvallam, Kerala\'s traditional houseboat, was once a cargo boat that hauled rice and spices. Today these curved, palm-thatched boats have been reborn as floating homes, gliding silently past villages where fishermen cast nets, women wash clothes on stone steps, and kingfishers flash blue over the water.\", \"The most famous stretch runs through Alleppey (Alappuzha), often called the \'Venice of the East\', toward Kollam. At sunset the water turns to gold, the air fills with the smell of toddy and spices, and the entire green world seems to slow down to the rhythm of a single paddle stroke.\"]', '[{\"text\": \"A vast network of canals, lagoons, and lakes beside the sea.\", \"title\": \"900 Kilometres of Water\"}, {\"text\": \"Traditional cargo boats reborn as luxury houseboats.\", \"title\": \"The Kettuvallam\"}, {\"text\": \"Alleppey, the most famous of the backwater towns.\", \"title\": \"Venice of the East\"}, {\"text\": \"Fishing, farming, and daily life carried on beside the water.\", \"title\": \"Living Villages\"}, {\"text\": \"Palms, paddy, kingfishers, and sunsets of pure gold.\", \"title\": \"Nature\'s Palette\"}]', 'The backwaters are Kerala\'s most beloved experience and a model of gentle tourism — proof that some of Bhārat\'s greatest wonders are not monuments but ways of life, drifting quietly on the water.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (26, 'places', 'valley-of-flowers', 'Valley of Flowers', 'फूलों की घाटी', 'A hidden Himalayan valley carpeted in 600 alpine blooms', 'Natural Wonders', 'Discovered by the world in 1931', 'Found by mountaineer Frank Smythe; nature\'s own garden', 'Uttarakhand, in the Nanda Devi Biosphere', 30.7430879, 79.6177253, 'Flower2', 'from-[#166534] to-[#22C55E]', 'bg-green-50 text-green-700 border-green-200', 'text-green-600', 'In the Valley of Flowers, the earth itself seems to bloom.', 'A tribute to the Himalayan valley', 'Tucked in the high Himalaya of Uttarakhand, the Valley of Flowers is a UNESCO World Heritage Site where over 600 species of alpine flowers — blue poppies, brahma kamal, and a thousand more — carpet a glacial valley in bloom every summer.', '[\"The valley was unknown to the outside world until 1931, when the mountaineer Frank Smythe, returning from an expedition, wandered into it and found the valley floor buried under flowers. He named it the Valley of Flowers, and the world has been trying to describe its beauty ever since.\", \"For just a few months each year — roughly July to September, when the monsoon feeds the slopes — over 600 species of alpine flowers explode into colour: the endangered blue poppy, the sacred brahma kamal, orchids, daisies, and primulas in every shade. The valley is part of the Nanda Devi Biosphere Reserve, ringed by snow peaks.\", \"Reaching it is an adventure in itself: a trek from Govindghat through the village of Ghangaria, climbing into the high meadows. The valley is closed in winter and completely untouched by roads — a flower garden that remains, by design, wild.\"]', '[{\"text\": \"Blue poppies, brahma kamal, orchids — a living rainbow of alpine flora.\", \"title\": \"600 Species\"}, {\"text\": \"One of the world\'s great high-altitude wildflower sites.\", \"title\": \"UNESCO Heritage\"}, {\"text\": \"The valley blooms for barely three months a year, then sleeps under snow.\", \"title\": \"A Short Season\"}, {\"text\": \"Protected within one of Bhārat\'s most pristine reserves.\", \"title\": \"Nanda Devi Biosphere\"}, {\"text\": \"No roads — only a mountain walk leads to the garden.\", \"title\": \"A Trek to Reach It\"}]', 'The Valley of Flowers is proof that Bhārat\'s most beautiful places need no human hand. It is a World Heritage site, a trekker\'s dream, and a reminder that some wonders are best left wild.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (27, 'places', 'sundarbans', 'Sundarbans', 'सुंदरबन', 'The world\'s largest mangrove forest — kingdom of the Royal Bengal tiger', 'Natural Wonders', 'Ancient delta — home to mangroves for millennia', 'The great delta of the Ganga, Brahmaputra & Meghna', 'West Bengal (shared with Bangladesh)', 22.0315881, 88.6873161, 'Trees', 'from-[#14532D] to-[#16A34A]', 'bg-emerald-50 text-emerald-700 border-emerald-200', 'text-emerald-600', 'Here the land and the sea are one — a green maze of tides and tigers.', 'A tribute to the Sundarbans', 'Where the Ganga meets the Bay of Bengal, the world\'s largest mangrove forest rises from the tide — 10,000 square kilometres of swampy islands that are the last stronghold of the Royal Bengal tiger and one of Earth\'s most fragile ecosystems.', '[\"The Sundarbans — \'the beautiful forest\' — is the largest mangrove forest on Earth, spread across the delta where the Ganga, Brahmaputra, and Meghna rivers pour into the Bay of Bengal. Twice a day, the tide floods the islands; twice a day, it drains away, leaving mud, crabs, and the world\'s strangest trees on stilts.\", \"It is the kingdom of the Royal Bengal tiger, which here swims between islands and hunts the chital deer of the delta. The forest also shelters estuarine crocodiles, Ganges river dolphins, and hundreds of bird species — a biodiversity hotspot recognised as a UNESCO World Heritage Site.\", \"The people of the Sundarbans — fishermen, crab collectors, and the famous honey collectors (mouals) who brave tiger attacks for wild honey — have lived with the tides for centuries. But the forest is shrinking and the sea is rising, making it one of the front lines of climate change on Earth.\"]', '[{\"text\": \"10,000 sq km of tidal mangrove forest — the world\'s biggest.\", \"title\": \"Largest Mangroves\"}, {\"text\": \"The last great stronghold of the Royal Bengal tiger.\", \"title\": \"Tiger Kingdom\"}, {\"text\": \"A World Heritage Site and biosphere reserve.\", \"title\": \"UNESCO Heritage\"}, {\"text\": \"Islands that flood and empty twice every day.\", \"title\": \"Tide-Turned Land\"}, {\"text\": \"Mouals who brave the tigers for wild forest honey.\", \"title\": \"The Honey Hunters\"}]', 'The Sundarbans is one of the planet\'s last wild places — a green frontier between river and sea. Its tigers, dolphins, and honey hunters make it a wonder of nature and a warning about the climate to come.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (28, 'places', 'ladakh', 'Ladakh', 'लद्दाख', 'The \'Little Tibet\' — a cold desert of sky-blue lakes and golden monasteries', 'Natural Wonders', 'A high-altitude kingdom for over a thousand years', 'The high Himalaya & Karakoram; its Buddhist monasteries', 'Ladakh, Jammu & Kashmir', 34.1681148, 77.5841568, 'MountainSnow', 'from-[#0C4A6E] to-[#0EA5E9]', 'bg-sky-50 text-sky-700 border-sky-200', 'text-sky-600', 'A land of high passes and prayer flags, where the mountains touch the sky.', 'A tribute to Ladakh', 'Sandwiched between the Himalaya and the Karakoram, Ladakh is a high-altitude cold desert of otherworldly beauty — colour-changing lakes, golden Buddhist monasteries, and some of the highest motorable roads on Earth.', '[\"Ladakh — \'the land of high passes\' — sits at an average of 3,500 metres, a cold desert where rain almost never falls but the sky is the bluest in Bhārat. It has been a crossroads of trade and Buddhism for over a thousand years, called Little Tibet for its monasteries and culture.\", \"Its lakes are famous for changing colour: Pangong Tso, which shifts from blue to green to red across the day and was the backdrop of a Bollywood blockbuster, and Tso Moriri, a high-altitude lake ringed by snow peaks. Along the Indus river stand the gompas — monasteries like Thiksey and Hemis, with their giant Buddha statues and masked dance festivals.\", \"Ladakh also holds the thrills: Khardung La, among the highest motorable passes in the world, the sand dunes of Nubra Valley with their double-humped Bactrian camels, and the frozen Zanskar river trek of winter. It is Bhārat\'s rooftop adventure capital.\"]', '[{\"text\": \"Rain almost never falls in this 3,500-metre-high moon landscape.\", \"title\": \"The Cold Desert\"}, {\"text\": \"The colour-shifting lake that runs from blue to green to red.\", \"title\": \"Pangong Tso\"}, {\"text\": \"Golden gompas and a thousand years of Buddhist culture.\", \"title\": \"Little Tibet\"}, {\"text\": \"Khardung La and the world\'s highest motorable roads.\", \"title\": \"High Passes\"}, {\"text\": \"Sand dunes and Bactrian camels in a Himalayan valley.\", \"title\": \"Nubra\'s Camels\"}]', 'Ladakh is Bhārat\'s rooftop — a place where the mountains, the lakes, and the monasteries together make one of the most extraordinary landscapes on Earth, and where Buddhism found its last great Himalayan home.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (29, 'places', 'lonar-crater-lake', 'Lonar Crater Lake', 'लोनार सरोवर', 'The world\'s third-largest crater — a meteor\'s bowl of blue in a green forest', 'Natural Wonders', 'Created ~52,000 years ago', 'A meteor impact', 'Lonar, Buldhana district, Maharashtra', 19.9830917, 76.4911448, 'Orbit', 'from-[#0F766E] to-[#14B8A6]', 'bg-teal-50 text-teal-700 border-teal-200', 'text-teal-600', 'An asteroid left its mark on Bhārat — a perfect blue bowl among the trees.', 'A tribute to Lonar Lake', 'In the quiet of Buldhana district, Maharashtra, lies a lake that should not exist on flat basalt plains: a perfectly round crater formed when a meteor struck Earth about 52,000 years ago. Lonar is the world\'s third-largest impact crater and the only one on Earth found in basaltic rock.', '[\"About 52,000 years ago, a two-million-tonne meteorite slammed into the Deccan plateau, blasting a bowl 150 metres deep into the dark volcanic basalt. Today that scar holds saline, alkaline water — a startling disc of sky-blue in the middle of a sprawling emerald forest.\", \"The lake is a scientific rarity: the only known hypervelocity impact crater in basaltic rock anywhere on Earth. Its extreme saline-alkaline water hosts microorganisms found nowhere else, which is why astrobiologists study Lonar as a window into how life might survive on other planets.\", \"Around the crater stand temples, most of them in ruins, from the Chalukya era — the finest being the Daitya Sudan temple, which commemorates Vishnu\'s slaying of the demon Lonasura, the very demon legend says gave Lonar its name. At sunset the crater rim turns gold.\"]', '[{\"text\": \"The world\'s third-largest impact crater, carved some 52,000 years ago.\", \"title\": \"A Crater on Earth\"}, {\"text\": \"The only known meteor crater on Earth formed in basaltic rock.\", \"title\": \"Hypervelocity Basalt\"}, {\"text\": \"Extreme saline-alkaline water hosts microbes studied for space research.\", \"title\": \"Water Like Mars\"}, {\"text\": \"Legend says Vishnu slew the demon Lonasura here — giving the lake its name.\", \"title\": \"The Demon\'s Lake\"}, {\"text\": \"Chalukya-era temples circle the crater, the Daitya Sudan among them.\", \"title\": \"Temples in the Rim\"}]', 'Lonar is where astronomy and mythology share one lake — a meteorite\'s crater that legend turned into a battlefield of gods and demons, and that modern science studies as a window into other worlds.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (30, 'places', 'needle-hole-point', 'Needle Hole Point', 'नीडल होल पॉइंट', 'The elephant\'s face carved in the Deccan Traps of Mahabaleshwar', 'Natural Wonders', 'Sculpted over millions of years', 'The Deccan Traps', 'Mahabaleshwar, Maharashtra', 17.9242764, 73.6575799, 'Mountain', 'from-[#166534] to-[#22C55E]', 'bg-green-50 text-green-700 border-green-200', 'text-green-600', 'A rock formation so perfect it seems shaped by a craftsman\'s hand.', 'Travelers\' description of Needle Hole Point', 'High in the hill station of Mahabaleshwar, the Needle Hole Point offers a rare view of the Deccan Traps — dark basalt cliffs so eroded that one formation looks exactly like the face of an elephant. Known as Elephant Point, it is one of the Sahyadris\' most photographed rock sculptures.', '[\"Near Kate\'s Point on the Mahabaleshwar ridge, the great basalt cliffs of the Deccan Traps have been carved by wind and rain into the silhouette of an elephant\'s face — trunk, forehead, and all. The local name says it plainly: Elephant Point.\", \"The \'needle hole\' itself is a narrow vertical slit in the rock through which you glimpse the valleys and jungles far below. The point is one of three together — Kate\'s Point, Echo Point, and Needle Hole Point — that form one of the region\'s great wonder-trios.\", \"The best time to arrive is just after the monsoon, when the Sahyadris are their greenest and the views stretch over misty gorges. It is a short drive from Mahabaleshwar town, itself famous for strawberries, lakes, and endless viewpoints.\"]', '[{\"text\": \"A basalt formation that mirrors an elephant\'s silhouette.\", \"title\": \"The Elephant\'s Face\"}, {\"text\": \"A narrow slit in the rock framing the valleys below.\", \"title\": \"The Needle Hole\"}, {\"text\": \"Ancient volcanic basalt cliffs, millions of years old.\", \"title\": \"Deccan Traps\"}, {\"text\": \"Kate\'s, Echo, and Needle Hole — a trio of viewpoints.\", \"title\": \"Three Points\"}, {\"text\": \"Best seen fresh after the rains, when the hills are emerald.\", \"title\": \"Monsoon Magic\"}]', 'Needle Hole Point shows nature at its most sculptural — a landscape artist\'s trick in the Deccan Traps that has delighted travelers for generations.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (31, 'places', 'borra-caves', 'Borra Caves', 'बोर्रा गुफाएँ', 'Bhārat\'s deepest limestone caves, lit by 63 eternal lamps', 'Natural Wonders', 'Millions of years in the making', 'Limestone & dripping water', 'Ananthagiri hills, Andhra Pradesh', 18.2939056, 83.0597306, 'Layers', 'from-[#92400E] to-[#D97706]', 'bg-amber-50 text-amber-700 border-amber-200', 'text-amber-700', 'Nature\'s work in progress — a cave still being carved, drip by drip.', 'A tribute to the Borra Caves', 'Hidden in the Ananthagiri hills about 90 kilometres from Visakhapatnam, the Borra Caves plunge over 260 feet into the earth — among the deepest limestone caves in Bhārat. Inside, mineral-rich water has spent millennia growing stalactites and stalagmites in every strange shape.', '[\"The caves came to wider notice in 1807, when a British geologist on a hunting trip stumbled upon a natural opening in the forest floor. The name \'Borra\' comes from a local word for a hole in the ground — exactly what the cave mouth looks like from above.\", \"Inside, the caves are a cathedral of dripstone: stalactites hang like soda straws from the roof while stalagmites rise in conical cakes from the floor, slowly meeting over thousands of years. Mineral-rich water trickling from the ceiling deposits tiny rings of minerals — the cave still being built, drip by drip.\", \"Sixty-three lamps illuminate the chambers, throwing the giant formations into dramatic light. Devotees worship a shivalinga formed naturally at the cave\'s heart, while the Gosthani river — said to emerge from the very rock — flows out past the cave mouth toward the sea.\"]', '[{\"text\": \"Among the deepest limestone caves in Bhārat.\", \"title\": \"260 Feet Deep\"}, {\"text\": \"Soda straws, cones, and curtains grown from dripping minerals.\", \"title\": \"A Cathedral of Stalactites\"}, {\"text\": \"The cave\'s dramatic lighting — and a shivalinga at its heart.\", \"title\": \"63 Lamps\"}, {\"text\": \"Mineral deposits still forming, drip by drip.\", \"title\": \"Work in Progress\"}, {\"text\": \"The Gosthani river emerges from the rock nearby.\", \"title\": \"Birth of a River\"}]', 'Borra is a million-year-old work in progress — a cave still growing beneath the Ananthagiri hills, where geology and worship share the same dripping stone.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (32, 'places', 'dudhsagar-falls', 'Dudhsagar Falls', 'दूधसागर जलप्रपात', 'The Sea of Milk — Bhārat\'s second-tallest waterfall', 'Natural Wonders', 'A waterfall of the Western Ghats', 'The Mandovi river', 'Goa–Karnataka border', 15.3156176, 74.3142493, 'Waves', 'from-[#155E75] to-[#06B6D4]', 'bg-cyan-50 text-cyan-700 border-cyan-200', 'text-cyan-600', 'A sea of milk pouring over a 300-metre cliff.', 'The meaning of \'Dudhsagar\'', 'The Dudhsagar Falls — the \'Sea of Milk\' — tumble 310 metres down the Western Ghats in a single mighty drop, making them among the tallest waterfalls in Bhārat. In full monsoon roar, the white curtain is so broad it looks like a river of milk pouring off the mountain.', '[\"The name says it all: dudh means milk, sagar means sea. Spray from the falling water foams white as it plunges into the pool below, looking for all the world like milk being poured. The falls reach their thundering zenith during the monsoon.\", \"The falls shot to national fame as the backdrop of the Bollywood blockbuster Chennai Express, with Shah Rukh Khan and Deepika Padukone dancing before the curtain of water. Long before cinema, though, they were a landmark on the old railway route — the train line that runs beside the falls is still one of Bhārat\'s most scenic stretches.\", \"Reached through the Bhagwan Mahavir Wildlife Sanctuary on the Goa side, or from Karnataka via the Kulem–Castle Rock road, Dudhsagar is wrapped in dense, dripping rainforest — the reward for a 3–6 km trek from the nearest road.\"]', '[{\"text\": \"Dudhsagar — 1,017 feet of white water in one mighty drop.\", \"title\": \"The Sea of Milk\"}, {\"text\": \"After the rains the falls become a mile-wide curtain.\", \"title\": \"Monsoon Zenith\"}, {\"text\": \"Famous from the blockbuster Chennai Express.\", \"title\": \"Bollywood Backdrop\"}, {\"text\": \"The rail line running past the falls is among Bhārat\'s most scenic.\", \"title\": \"A Train Through the Spray\"}, {\"text\": \"Tucked inside the Bhagwan Mahavir Wildlife Sanctuary.\", \"title\": \"Rainforest Setting\"}]', 'Dudhsagar is the Western Ghats at their most theatrical — a waterfall so white and so powerful that Bhārat named it after milk and made it a star of the silver screen.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (33, 'places', 'magnetic-hill', 'Magnetic Hill', 'मैग्नेटिक हिल', 'Where cars roll uphill — Ladakh\'s gravity-defying road', 'Natural Wonders', 'A permanent optical illusion', 'The surrounding slopes', 'Near Leh, Ladakh', 34.1709853, 77.3524824, 'Magnet', 'from-[#5B21B6] to-[#8B5CF6]', 'bg-violet-50 text-violet-700 border-violet-200', 'text-violet-600', 'Switch off the engine, release the brake — and watch your car roll \'uphill\'.', 'Every traveler to Magnetic Hill', 'On the Leh–Kargil highway, about 30 kilometres from Leh, a short stretch of road defies expectation: put your car in neutral and it appears to roll uphill, against gravity. Magnetic Hill is the Himalaya\'s most famous optical illusion.', '[\"Magnetic Hill is a \'gravity hill\' — a place where the surrounding slopes are arranged so cleverly that a slight downhill gradient appears to be uphill. The illusion is so complete that cars left in neutral genuinely roll \'up\', gathering surprising speed.\", \"It is the same trick played by similar spots around the world — including Gujarat\'s Kalo Dungar — but here, framed by the vast brown Ladakh landscape, the effect feels genuinely supernatural. Many visitors are convinced a magnetic force is pulling their vehicle.\", \"Local lore adds its own magic — that the region is one great magnet that even forces aircraft to fly higher overhead. The science is quieter: no magnets, just a landscape that bends the eye. Stand at the marker, put your car in neutral, and enjoy the world\'s friendliest lesson in perception.\"]', '[{\"text\": \"An optical illusion that makes a downhill slope look uphill.\", \"title\": \"A Gravity Hill\"}, {\"text\": \"In neutral, vehicles roll backward up the slope.\", \"title\": \"Cars Roll \'Up\'\"}, {\"text\": \"On the Leh–Kargil highway, Ladakh.\", \"title\": \"30 km from Leh\"}, {\"text\": \"Pure perception — the slopes trick the eye.\", \"title\": \"No Magnets Involved\"}, {\"text\": \"Even the tale of aircraft diverting has grown around it.\", \"title\": \"A Myth Made Road\"}]', 'Magnetic Hill is one of the world\'s great optical illusions — a place where physics seems to take a holiday, and where every visitor leaves doubting their own eyes, and loving it.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (34, 'places', 'belum-caves', 'Belum Caves', 'बेलुम गुफाएँ', 'The second-largest caves in the Indian subcontinent', 'Natural Wonders', 'Formed over thousands of years', 'Underground water', 'Near Tadipatri, Andhra Pradesh', 15.1021750, 78.1116692, 'Cone', 'from-[#57534E] to-[#A8A29E]', 'bg-stone-100 text-stone-700 border-stone-200', 'text-stone-600', 'Three and a half kilometres of caverns and galleries beneath the plains.', 'A tribute to Belum Caves', 'Beneath the flat plains of Kurnool district lie the Belum Caves — the second-largest cave system in the Indian subcontinent and the longest on the plains. Its kilometres of explored passages hold galleries, freshwater chambers, and stalactites that have grown for thousands of years.', '[\"Formed by underground water slowly dissolving the limestone, the Belum Caves stretch 3,229 metres — the longest caves in the plains of the subcontinent. Of this, about 1.5 kilometres is open to visitors, descending as deep as 46 metres below the ground.\", \"The caves are famous for their stalactite and stalagmite formations, halls of them growing from floor and ceiling. Ancient relics found inside suggest the caves were used by Buddhist monks two millennia ago — some chambers still bear traces of that hidden past.\", \"Visitors descend through the main entrance and pass the Saptasvarala chamber, where dripping water is said to produce the seven musical notes, and the Banyan Tree hall, where a single great column seems to hold up the cave like a giant fig tree.\"]', '[{\"text\": \"3,229 metres of passages — the longest caves on the subcontinent\'s plains.\", \"title\": \"Second-Largest\"}, {\"text\": \"Limestone dissolved and reshaped over thousands of years.\", \"title\": \"Grown by Water\"}, {\"text\": \"Relics suggest monks sheltered here two millennia ago.\", \"title\": \"A Buddhist Past\"}, {\"text\": \"The chamber where dripping water sounds the seven musical notes.\", \"title\": \"Saptasvarala\"}, {\"text\": \"About 1.5 km of the caves is open to visitors.\", \"title\": \"46 Metres Deep\"}]', 'Belum is the subcontinent\'s underground masterpiece on the plains — a labyrinth of limestone galleries where water built cathedrals in the dark.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (35, 'places', 'living-root-bridges', 'Living Root Bridges', 'Jingkieng Jri', 'Bridges that grow — living roots woven by the Khasi people', 'Natural Wonders', 'Some bridges over 500 years old', 'The Khasi people', 'Cherrapunji & Nongriat, Meghalaya', 25.2510232, 91.6713764, 'Trees', 'from-[#14532D] to-[#16A34A]', 'bg-green-50 text-green-700 border-green-200', 'text-green-600', 'The only bridges in the world that grow stronger with every passing year.', 'A tribute to the living bridges', 'In one of the wettest places on Earth, the Khasi people of Meghalaya grow their bridges. Over fifteen years, the aerial roots of the Ficus elastica tree are trained across streams until they become load-bearing crossings — some of them 500 years old and 50 metres long.', '[\"In Cherrapunji, one of the wettest places on the planet, iron bridges rust and rot within decades. So the Khasis turned to living material: the strangler fig, whose aerial roots can be guided, year after year, across a river until they knit into a solid, living bridge.\", \"A bridge takes about fifteen years to become usable — and then it grows stronger forever. As the fig thrives, the roots thicken and interlock; some bridges are now centuries old and carry whole villages. The longest known, near Pynursla, spans about 50 metres.\", \"The famous double-decker root bridge at Nongriat is Meghalaya\'s emblem — two living decks stacked over a gorge, reached by a steep forest trek of 3,000 steps. In the monsoon, water thunders beneath while the roots hold firm, a living bridge doing its quiet work.\"]', '[{\"text\": \"Ficus roots trained across streams over fifteen years.\", \"title\": \"Grown, Not Built\"}, {\"text\": \"Living bridges grow stronger each year — some 500 years old.\", \"title\": \"Stronger With Age\"}, {\"text\": \"Nongriat\'s two-storey root bridge is the most famous.\", \"title\": \"The Double-Decker\"}, {\"text\": \"Roots were chosen because iron rots in Cherrapunji\'s rains.\", \"title\": \"Wettest Place on Earth\"}, {\"text\": \"A living tradition passed down through generations.\", \"title\": \"Khasi Engineering\"}]', 'The living root bridges are one of the world\'s great examples of human patience and natural genius — infrastructure that grows, heals, and improves itself, for centuries, without a single nail.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (36, 'places', 'marble-rocks', 'Marble Rocks of Bhedaghat', 'भेड़ाघाट की संगमरमर चट्टानें', 'The Narmada\'s white marble gorge at Bhedaghat', 'Natural Wonders', 'Ancient rock, carved by the Narmada', 'The Narmada river', 'Bhedaghat, Jabalpur, Madhya Pradesh', 23.1317464, 79.8009868, 'Gem', 'from-[#475569] to-[#94A3B8]', 'bg-slate-100 text-slate-700 border-slate-200', 'text-slate-600', 'White cliffs shimmering above a river of legend.', 'A tribute to the Marble Rocks', 'Just outside Jabalpur, the Narmada river has carved a three-kilometre gorge through walls of white marble — the famous Marble Rocks of Bhedaghat. A boat ride through the canyon, past cliffs streaked green and brown, is one of central Bhārat\'s most beautiful experiences.', '[\"For three kilometres, the Narmada threads through a gorge whose marble walls rise about a hundred feet on either side. The rock is the same marble that built the Taj Mahal, here left in its natural state — white, streaked, and polished by the water.\", \"As the boat glides through, the cliffs shimmer in the sunlight — white, veined with green moss and brown volcanic streaks. The river is the stage for one of Bhārat\'s most photographed sights: the Dhuandhar Falls, where the Narmada crashes over the rocks in a cascade of mist.\", \"On the cliff tops stand temples and caves, including the Chausath Yogini temple dedicated to 64 goddesses and a sunset viewpoint where the whole gorge turns gold. In the monsoon the river roars; in winter the water turns glassy and clear, mirroring the marble above.\"]', '[{\"text\": \"A gorge walled in the same marble as the Taj Mahal.\", \"title\": \"Three Kilometres of Marble\"}, {\"text\": \"The sacred river carved the canyon over millennia.\", \"title\": \"The Narmada\'s Work\"}, {\"text\": \"The misty cascade where the river roars over the rocks.\", \"title\": \"Dhuandhar Falls\"}, {\"text\": \"A 64-goddess temple watches from the cliff top.\", \"title\": \"Chausath Yogini\"}, {\"text\": \"The classic Bhedaghat ride, straight through the gorge.\", \"title\": \"A Boat Through the Canyon\"}]', 'The Marble Rocks show Bhārat\'s most sacred river at its most beautiful — carving a canyon of white marble that has drawn pilgrims, painters, and filmmakers for centuries.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (37, 'places', 'banni-grasslands', 'Banni Grasslands', 'બન્ની ઘાસના મેદાન', 'Kutch\'s wild grasslands — and the mysterious Chir Batti lights', 'Natural Wonders', 'A living grassland of Kutch', 'The marshes of the Rann', 'Rann of Kutch, Gujarat', 23.7905519, 70.4966137, 'Sparkles', 'from-[#9A3412] to-[#F59E0B]', 'bg-orange-50 text-orange-700 border-orange-200', 'text-orange-600', 'Dancing lights in the dark grasslands — ghosts, UFOs, or marsh gas?', 'The mystery of Chir Batti', 'On the southern edge of the Rann of Kutch lie the Banni grasslands, a vast wild expanse of grasses and acacia. By night, its marshlands glow with the mysterious Chir Batti — dancing balls of light that locals call ghosts and scientists call burning marsh gas.', '[\"Banni is one of Bhārat\'s great hidden landscapes — thousands of square kilometres of arid grassland in Kutch, grazed for centuries by the Maldhari pastoralists, whose buffalo herding is itself part of the region\'s living heritage.\", \"At night, the marshlands produce Chir Batti — \'ghost lights\' that appear as bright as mercury lamps, changing colour from blue to red to yellow, sometimes still, sometimes racing across the dark. Soldiers and locals alike have been startled by lights that seem to follow them.\", \"Science offers a quiet explanation: methane from the marshland soil oxidises and glows — a natural will-o\'-the-wisp. But for the Maldhari, the lights are the souls of the grassland, and their stories keep the mystery alive under the vast Kutch sky.\"]', '[{\"text\": \"Thousands of square kilometres of wild grass in Kutch.\", \"title\": \"A Great Arid Grassland\"}, {\"text\": \"Colour-changing balls of light that dance over the marshes at night.\", \"title\": \"Chir Batti Lights\"}, {\"text\": \"Locals call them spirits; scientists say oxidising marsh gas.\", \"title\": \"Ghosts or Methane?\"}, {\"text\": \"Pastoral herders who have grazed these lands for centuries.\", \"title\": \"The Maldharis\"}, {\"text\": \"One of Kutch\'s least-known and most mysterious landscapes.\", \"title\": \"A Hidden Wild\"}]', 'Banni is where a landscape and a legend share one sky — a grassland so remote that even its lights remain a story, told by herders under a vast desert night.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (38, 'places', 'loktak-lake', 'Loktak Lake', 'লোকটক পুখরী', 'The world\'s only floating national park — Manipur\'s phumdi lake', 'Natural Wonders', 'An ancient lake of floating islands', 'Vegetation, soil & water', 'Bishnupur district, Manipur', 24.5584253, 93.8132376, 'Ship', 'from-[#0D9488] to-[#2DD4BF]', 'bg-teal-50 text-teal-700 border-teal-200', 'text-teal-600', 'The only lake in the world with a floating national park on its back.', 'A tribute to Loktak Lake', 'About 54 kilometres from Imphal lies Loktak, the largest freshwater lake in northeast Bhārat — and the only lake on Earth that carries a floating national park. On its surface drift the phumdis, islands of vegetation and soil that the lake has carried for centuries.', '[\"The phumdis — heterogeneous masses of vegetation, soil, and organic matter at various stages of decomposition — float on Loktak\'s surface like miniature islands. They move with the wind and the water, some thick enough to walk on, and they give Loktak its otherworldly face.\", \"On these floating islands sits the Keibul Lamjao National Park — the world\'s only floating national park and the last natural home of the endangered brow-antlered deer, the sangai, Manipur\'s state animal. A single rare flower, the loktak lotus, also blooms nowhere else.\", \"Covering around 300 square kilometres, the lake is the lifeline of the region: it feeds hydropower, irrigates fields, supplies drinking water, and sustains thousands of fishermen whose stilt-house villages rise straight from its waters.\"]', '[{\"text\": \"Islands of vegetation and soil that drift on the water.\", \"title\": \"The Floating Phumdis\"}, {\"text\": \"Keibul Lamjao — the world\'s only one, on the lake\'s back.\", \"title\": \"A Floating National Park\"}, {\"text\": \"The endangered brow-antlered deer, Manipur\'s state animal.\", \"title\": \"Home of the Sangai\"}, {\"text\": \"The largest freshwater lake in northeast Bhārat.\", \"title\": \"300 sq km of Water\"}, {\"text\": \"Fishing villages rise directly from the lake\'s surface.\", \"title\": \"Stilt Villages\"}]', 'Loktak is a lake that carries a whole world on its back — national park, deer, flower, and fishing villages drifting together on the only floating ecosystem of its kind on Earth.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (39, 'places', 'amarnath-cave', 'Amarnath Cave', 'अमरनाथ गुफा', 'The ice lingam of Shiva, high in the Kashmir Himalaya', 'Natural Wonders', 'A shrine at 3,888 metres', 'Frozen water & Shiva legend', 'Kashmir Himalaya', 34.0008865, 74.7975922, 'Snowflake', 'from-[#0284C7] to-[#38BDF8]', 'bg-sky-50 text-sky-700 border-sky-200', 'text-sky-600', 'Where frozen water becomes a god — the ice lingam of Amarnath.', 'A tribute to the Amarnath Cave', 'At 3,888 metres in the Kashmir Himalaya, a cave holds one of the most miraculous shrines in the world: a lingam of ice that forms naturally every year, grows with the waxing moon, and melts away with the waning one. Millions of pilgrims trek to it through the snow every summer.', '[\"The ice lingam is a natural stalagmite: water drops trickle from the roof of the cave and freeze on the floor, slowly rising into a column that waxes and wanes with the moon. No hand carves it — winter grows it, and the cycle has repeated for as long as anyone remembers.\", \"Legend tells that this is the very cave where Lord Shiva revealed the secret of immortality — the amar katha — to his consort Parvati. A pair of doves is said to have overheard it and become immortal, and pilgrims say a pair of doves still nests in the cave.\", \"The annual Amarnath Yatra is one of the great pilgrimages of the world: a trek of over 100 kilometres through the Himalaya, past the lakes and passes of Kashmir, undertaken by hundreds of thousands of devotees in the short summer window when the cave is open.\"]', '[{\"text\": \"A shivalinga of ice that forms naturally, waxing with the moon.\", \"title\": \"The Ice Lingam\"}, {\"text\": \"A Himalayan cave reached by one of the world\'s great treks.\", \"title\": \"3,888 Metres Up\"}, {\"text\": \"Where Shiva is said to have revealed the secret of immortality.\", \"title\": \"The Amar Katha\"}, {\"text\": \"Legend says the doves who overheard the secret still nest there.\", \"title\": \"The Two Doves\"}, {\"text\": \"Hundreds of thousands of pilgrims trek in every summer.\", \"title\": \"The Annual Yatra\"}]', 'Amarnath is where geology and faith meet at the top of the world — a column of frozen water that millions believe to be a god, drawing the faithful on a Himalayan journey unlike any other.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (40, 'places', 'st-marys-islands', 'St. Mary\'s Islands', 'सेंट मैरी आइलैंड्स', 'The sea\'s hexagon — volcanic basalt columns off the Karnataka coast', 'Natural Wonders', 'A volcanic formation millions of years old', 'Cooling basaltic lava', 'Off Malpe, Karnataka', 13.3437929, 74.6844981, 'Flame', 'from-[#7E22CE] to-[#A855F7]', 'bg-purple-50 text-purple-700 border-purple-200', 'text-purple-600', 'A volcanic rock garden that looks shaped by human hands — but was shaped by fire.', 'A tribute to St. Mary\'s Islands', 'A short boat ride from the beach town of Malpe, the St. Mary\'s Islands rise from the Arabian Sea wearing a geological wonder: cliffs of perfectly formed hexagonal basalt columns, created millions of years ago when volcanic lava cooled and cracked into honeycomb shapes.', '[\"Millions of years ago, a volcano hurled out dense, viscous basaltic lava that cooled quickly. As the molten rock congealed, it contracted and cracked into a sequence of spider-web lines — forming the hexagons and polygons that today stand stacked like giant pencils on the shore.\", \"The columns look as if they were cut by a stone mason — regular, smooth-sided, and impossibly precise. On Coconut Island, the largest of the group, the formations march down to the water\'s edge, where the sea has polished them into one of Bhārat\'s strangest coastlines.\", \"Legend gives the islands a different origin story: local tradition says they are the petrified remains of the demon Darukasura, slain by the goddess Bhagavathi — making the site a place of both geology and pilgrimage, with an ancient church standing on the main island.\"]', '[{\"text\": \"Basalt cracked by cooling into perfect honeycomb shapes.\", \"title\": \"Hexagonal Columns\"}, {\"text\": \"Volcanic lava that cooled and contracted millions of years ago.\", \"title\": \"Born of Fire\"}, {\"text\": \"The largest isle, with columns marching to the sea.\", \"title\": \"Coconut Island\"}, {\"text\": \"Legend says the rocks are the demon Darukasura petrified.\", \"title\": \"A Demon\'s Tale\"}, {\"text\": \"An ancient church stands on the main island.\", \"title\": \"A Sea Church\"}]', 'St. Mary\'s Islands are a rare window into the Earth\'s volcanic past — a natural gallery of hexagonal stone off the Karnataka coast, where geology wears the mask of miracle.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (41, 'places', 'sambhar-lake', 'Sambhar Lake', 'सांभर झील', 'Bhārat\'s largest inland salt lake, shimmering in the Thar', 'Natural Wonders', 'The Thar\'s great salt bowl', 'The desert & goddess Shakambhari', 'Near Jaipur, Rajasthan', 26.9151658, 75.8099241, 'Sun', 'from-[#CA8A04] to-[#FACC15]', 'bg-yellow-50 text-yellow-700 border-yellow-200', 'text-yellow-600', 'A silver sea in the middle of the desert — where the earth itself is salt.', 'A tribute to Sambhar Lake', 'In the arid heart of Rajasthan, about 80 kilometres southwest of Jaipur, lies Sambhar — Bhārat\'s largest inland salt lake. A bowl of shallow, glittering water in the Thar Desert, it supplies a tenth of the country\'s salt and holds a legend as old as Rajasthan itself.', '[\"When desert land is usually desolate and barren, Sambhar is a dazzling exception: a huge bowl-shaped water body in the middle of the Thar, ringed by the historical town of the same name. In the dry months it is not water but a vast white salt field that crunches underfoot.\", \"Legend tells that Shakambhari Devi, the tutelary goddess of the Chauhan Rajputs and a form of the divine mother, once turned a dense forest into a land of silver as a reward for service. Fearing greed would overcome the people, she then converted the silver into salt — and the lake was born.\", \"Every year, Sambhar yields nearly two lakh tonnes of salt, harvested from the brine in great crystalline sheets. Migratory flamingos and thousands of other birds also make the lake one of Rajasthan\'s most important wetlands, drawn by its shallow, salty waters.\"]', '[{\"text\": \"A bowl of salt water in the Thar, southwest of Jaipur.\", \"title\": \"Bhārat\'s Largest Salt Lake\"}, {\"text\": \"Goddess Shakambhari turned a forest to silver, then to salt.\", \"title\": \"The Silver Legend\"}, {\"text\": \"Two lakh tonnes harvested here every year.\", \"title\": \"A Tenth of Bhārat\'s Salt\"}, {\"text\": \"In dry months the lake becomes a vast crystalline plain.\", \"title\": \"A White Winter Field\"}, {\"text\": \"Flamingos and migratory birds throng its shallow waters.\", \"title\": \"A Bird Haven\"}]', 'Sambhar is the desert\'s silver lining — a lake that feeds a nation\'s kitchens, shelters its birds, and carries a goddess\'s legend in every crystal of salt.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (42, 'places', 'chandipur-beach', 'Chandipur Hide-and-Seek Beach', 'ଚାନ୍ଦିପୁର ବେଳାଭୂମି', 'The beach that disappears twice a day — Odisha\'s tide-vanishing shore', 'Natural Wonders', 'A beach that vanishes twice a day', 'The Bay of Bengal\'s tides', 'Balasore district, Odisha', 21.4932273, 86.9357935, 'Waves', 'from-[#1E3A8A] to-[#3B82F6]', 'bg-blue-50 text-blue-700 border-blue-200', 'text-blue-600', 'Come in the morning and the sea is there. Come in the afternoon and there is only sand.', 'The wonder of Chandipur', 'At Chandipur in Odisha, the sea plays a daily game of hide-and-seek. During low tide, the water retreats as far as five kilometres from the shore, leaving a vast, empty beach of sand and casuarina trees — before the ocean returns, wave by wave, at high tide.', '[\"Few beaches on Earth reveal their floor like Chandipur. Twice a day, the Bay of Bengal recedes up to five kilometres, and where water once stood you can walk out onto a landscape of sand, crabs, and creeper-covered dunes — a rare phenomenon that draws the curious from across Bhārat.\", \"At high tide the sea returns, advancing over the exposed flats to reclaim its shore. Fishermen time their lives to the rhythm: they follow the retreating water to catch fish stranded in the shallows, then race the tide back to land with their day\'s catch.\", \"The beach is lined with the red-tipped flowers and casuarina trees that give the shoreline its look, and the low-tide expanse is a natural playground — a place where the horizon, the sand, and the sky seem to stretch into infinity.\"]', '[{\"text\": \"Water recedes up to 5 km at low tide, twice a day.\", \"title\": \"The Sea That Leaves\"}, {\"text\": \"Few beaches on Earth expose their floor like this one.\", \"title\": \"A Rare Phenomenon\"}, {\"text\": \"Local fishers follow the retreating water and race the tide back.\", \"title\": \"Fishermen\'s Rhythm\"}, {\"text\": \"Sand, crabs, and dunes where the ocean once stood.\", \"title\": \"A Walk on the Seabed\"}, {\"text\": \"The beach\'s trademark trees and creeper dunes.\", \"title\": \"Casuarina Shore\"}]', 'Chandipur is the Bay of Bengal\'s own magic trick — a beach that hides itself twice a day, reminding everyone who walks its seabed that the ocean\'s timetable is not ours, but its own.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (43, 'places', 'aleya-ghost-lights', 'Aleya Ghost Lights', 'আলেয়া ভূতের বাতি', 'The phantom lights of the Sundarbans\' swamps', 'Natural Wonders', 'A nightly mystery, unsolved', 'The swamps of the Sundarbans', 'Sundarbans, West Bengal', 22.0315881, 88.6873161, 'Moon', 'from-[#312E81] to-[#6366F1]', 'bg-indigo-50 text-indigo-700 border-indigo-200', 'text-indigo-600', 'Glowing lights that drift over the dark marshes — and the tales that follow them.', 'The mystery of the Aleya', 'In the swampy tidal flats of the Sundarbans, nights are lit by a strange and eerie phenomenon: the Aleya — ghostly balls of glowing light that drift over the marshland. Local fishermen call them the spirits of their drowned ancestors; science calls them a will-o\'-the-wisp.', '[\"The Aleya lights appear as soft, wavering glows above the marshes — floating, flickering, and moving in ways that seem to follow the fishermen who brave the dark waters. Many believe they are the souls of anglers who perished in the treacherous creeks, guiding — or misleading — the living.\", \"Old mariners would follow the lights at night, believing they led to land or to good fishing grounds. Some followed them into danger. These tales of ghostly lamps have been passed down through generations of Sundarbans fishing families, and they colour the whole delta with mystery.\", \"Scientists offer a natural explanation: marsh gases — methane and phosphine from decomposing vegetation — ignite on contact with air, producing brief, dancing flames that hover over the wet ground. But in the dark, in the mangroves, with the tide whispering, the science never quite wins the argument.\"]', '[{\"text\": \"Glowing, drifting balls of light over the Sundarbans\' swamps.\", \"title\": \"Ghost Lights\"}, {\"text\": \"Fishermen say the lights are their drowned ancestors\' souls.\", \"title\": \"Spirits of the Marsh\"}, {\"text\": \"Old mariners followed the lights — sometimes into danger.\", \"title\": \"Lures in the Dark\"}, {\"text\": \"Science says methane and phosphine ignite to make the glow.\", \"title\": \"Marsh Gas\"}, {\"text\": \"Generations of tales keep the Aleya alive in the mangroves.\", \"title\": \"A Delta of Mystery\"}]', 'The Aleya lights are the Sundarbans\' oldest mystery — a phenomenon that science can explain but the human heart refuses to, leaving the mangroves glowing with legend long after the flame itself has gone.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (44, 'places', 'charminar', 'Charminar', 'चारमीनार', 'Four minarets and arches — the beating heart of Hyderabad', 'Monuments & Forts', 1591, 'Sultan Muhammad Quli Qutb Shah', 'Hyderabad, Telangana', 17.3616024, 78.4746421, 'Landmark', 'from-[#78350F] to-[#B45309]', 'bg-amber-50 text-amber-800 border-amber-200', 'text-amber-700', 'The Arc de Triomphe of the East — the most graceful monument of its kind.', 'Visitors\' description of Charminar', 'Standing at the centre of Hyderabad for over 430 years, the Charminar — \'four minarets\' — is the city\'s soul. Its four grand arches face the four directions, its minarets rise 48 metres over the bazaars, and a mosque still crowns its top floor.', '[\"The Charminar was built in 1591 by Sultan Muhammad Quli Qutb Shah to mark the end of a plague in his new city of Hyderabad — and to celebrate the founding of the city itself. Since then, it has watched four centuries of Deccan history flow through its arches.\", \"The monument is a perfect square: four great arches, one on each side, opening onto the crossroads beneath, and four slender minarets rising 48.7 metres, each with a double balcony. On the top floor, a small mosque — one of the oldest surviving in Hyderabad — is still used for Friday prayers.\", \"Around its base swirls the famous Laad Bazaar, whose glittering bangles and pearls fill the lanes with colour, and just beyond stands the great Mecca Masjid. At night, the Charminar is flooded with light, turning the granite-grey monument to gold — Hyderabad\'s most loved sight.\"]', '[{\"text\": \"A perfect square of arches opening onto the crossroads beneath.\", \"title\": \"Four Arches, Four Directions\"}, {\"text\": \"Slender towers with double balconies that crown the skyline.\", \"title\": \"48 Metre Minarets\"}, {\"text\": \"One of the city\'s oldest mosques still holds prayers on the top floor.\", \"title\": \"A Mosque on Top\"}, {\"text\": \"The glittering bangle and pearl market that flows around its base.\", \"title\": \"Laad Bazaar\"}, {\"text\": \"Built in 1591 to mark the founding of Hyderabad and the end of a plague.\", \"title\": \"Born With the City\"}]', 'The Charminar is the symbol of Hyderabad — the face on every postcard, the heart of the old city, and the \'Arc de Triomphe of the East\' that has held its ground for 430 years.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (45, 'places', 'mysore-palace', 'Mysore Palace', 'मैसूर पैलेस', 'The crown jewel of the City of Palaces, lit by 100,000 bulbs', 'Monuments & Forts', 'Rebuilt 1912; the seat of kings for centuries', 'The Wodeyar dynasty of Mysuru', 'Mysuru, Karnataka', 12.3052197, 76.6553846, 'Crown', 'from-[#9A3412] to-[#D97706]', 'bg-orange-50 text-orange-700 border-orange-200', 'text-orange-600', 'Mysuru is the city of palaces — and this is its crown jewel.', 'A tribute to Mysore Palace', 'The Mysore Palace is the seat of the Wodeyar maharajas and Bhārat\'s most visited monument after the Taj Mahal. Part Hindu, part Muslim, part Gothic — its domes and arches blend styles from across the world, and on Sunday nights it glows under 100,000 light bulbs.', '[\"Mysuru has been a city of kings for centuries, and its palace — rebuilt in 1912 after a fire — is the most lavish royal residence in Bhārat. The architect blended Hindu, Mughal, Rajput, and Gothic styles into a palace that belongs to no single tradition but to all of them.\", \"Inside, the Durbar Hall\'s painted ceiling and stained glass, the elaborate wedding hall, and the Golden Howdah — a throne of gold carried by elephants — show the splendour of the Wodeyars. During the ten-day Dasara festival, the palace becomes the stage for one of Bhārat\'s grandest royal celebrations.\", \"On Sundays and festival nights, the palace is illuminated with nearly 100,000 bulbs, and the entire building — domes, arches, and towers — blazes against the dark sky. It is one of the most photographed sights in Bhārat, and the undisputed heart of the \'City of Palaces\'.\"]', '[{\"text\": \"Hindu, Mughal, Rajput, and Gothic architecture in one palace.\", \"title\": \"A Blend of Styles\"}, {\"text\": \"A 750 kg gold throne carried by royal elephants.\", \"title\": \"The Golden Howdah\"}, {\"text\": \"The ten-day festival that turns the palace into a royal stage.\", \"title\": \"Dasara Splendour\"}, {\"text\": \"The Sunday-night illumination that makes the palace blaze.\", \"title\": \"100,000 Bulbs\"}, {\"text\": \"Bhārat\'s second most popular monument.\", \"title\": \"Most Visited After the Taj\"}]', 'Mysore Palace is royal Bhārat at its most magnificent — a living palace where kings still hold court in memory, and where 100,000 bulbs turn history into light every Sunday night.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (46, 'places', 'bodh-gaya', 'Bodh Gaya', 'बोधगया', 'Where the Buddha attained enlightenment under the Bodhi tree', 'Spiritual Sites', 'The enlightenment: c. 6th c. BCE', 'Siddhartha Gautama; the Mahabodhi Temple', 'Bodh Gaya, Bihar', 24.6817365, 84.9682310, 'TreePine', 'from-[#B45309] to-[#F59E0B]', 'bg-amber-50 text-amber-700 border-amber-200', 'text-amber-600', 'Here the Buddha woke — and here the world found the Middle Path.', 'A tribute to Bodh Gaya', 'Bodh Gaya is the holiest site in Buddhism — the place where Siddhartha Gautama sat beneath the Bodhi tree and became the Buddha, the Awakened One, some 2,500 years ago. Pilgrims from across the Buddhist world still gather at its Mahabodhi Temple.', '[\"Around the 6th century BCE, the prince Siddhartha Gautama sat in meditation beneath a peepal tree on the banks of the Phalgu river, vowing not to rise until he understood suffering. At dawn, he attained enlightenment and became the Buddha — and Bodh Gaya became the most sacred place on Earth for Buddhism.\", \"The Mahabodhi Temple, a UNESCO World Heritage Site, rises 50 metres over the spot — its tower crowned with a stupa, its walls carved with scenes from the Buddha\'s life. Beside it stands the Bodhi tree, a direct descendant of the original, grown from a sapling that was carried to Sri Lanka and brought back after two thousand years.\", \"The complex is a global village of faith: Thai, Japanese, Tibetan, Sri Lankan, and Bhutanese monasteries surround the temple, their architecture a tour of the Buddhist world. Every year, hundreds of thousands of pilgrims meditate, chant, and light butter lamps under the tree where the dharma was born.\"]', '[{\"text\": \"The exact spot where the Buddha woke, 2,500 years ago.\", \"title\": \"The Enlightenment\"}, {\"text\": \"A descendant of the original tree, tended for millennia.\", \"title\": \"The Bodhi Tree\"}, {\"text\": \"The 50-metre UNESCO-listed temple raised over the enlightenment spot.\", \"title\": \"Mahabodhi Temple\"}, {\"text\": \"Thai, Japanese, Tibetan, and Sri Lankan monasteries ring the complex.\", \"title\": \"A Global Pilgrimage\"}, {\"text\": \"Pilgrims from across the Buddhist world meditate beneath the tree.\", \"title\": \"Lighting Butter Lamps\"}]', 'Bodh Gaya is the holiest site of Buddhism — the birthplace of the Middle Path that spread from Bihar to half the world. Every pilgrim, and every mindful breath taken anywhere, traces back to this tree.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (47, 'places', 'rishikesh', 'Rishikesh', 'ऋषिकेश', 'The Yoga Capital of the World on the banks of the Ganga', 'Spiritual Sites', 'A pilgrimage town for centuries; world-famous since the 1960s', 'Sages and ashrams; the Beatles\' 1968 visit', 'Uttarakhand, at the foot of the Himalaya', 30.1086537, 78.2916193, 'Sunset', 'from-[#0F766E] to-[#14B8A6]', 'bg-teal-50 text-teal-700 border-teal-200', 'text-teal-600', 'The city where the Ganga leaves the mountains — and seekers begin their journey.', 'A tribute to Rishikesh', 'Rishikesh is where the Ganga bursts out of the Himalaya onto the plains — and where the world comes to learn yoga. Home to hundreds of ashrams and yoga schools, it became the Yoga Capital of the World after the Beatles stayed here in 1968.', '[\"Rishikesh sits at the exact point where the Ganga leaves the mountains and begins its long journey across Bhārat. For centuries it has been a gateway for pilgrims on the Char Dham yatra to the Himalayan shrines — and a town of sages and ashrams beside the holy river.\", \"In 1968, the Beatles spent weeks at the Maharishi Mahesh Yogi\'s ashram in Rishikesh and wrote dozens of songs there. Their visit put this small Himalayan town on the world map, and today Rishikesh is the undisputed Yoga Capital of the World, drawing seekers from every continent.\", \"Its landmarks hang across the Ganga: the suspension bridges of Lakshman Jhula and Ram Jhula, the evening Ganga Aarti at Triveni Ghat where lamps float down the river, and the white-water rapids upstream that make it equally famous as Bhārat\'s adventure capital.\"]', '[{\"text\": \"The river\'s first stop on the plains after the Himalaya.\", \"title\": \"Where the Ganga Begins\"}, {\"text\": \"Hundreds of ashrams and yoga schools teaching the world.\", \"title\": \"Yoga Capital\"}, {\"text\": \"Their stay put Rishikesh on the world\'s spiritual map.\", \"title\": \"The Beatles, 1968\"}, {\"text\": \"Lakshman Jhula and Ram Jhula swinging over the Ganga.\", \"title\": \"Jhula Bridges\"}, {\"text\": \"Evening lamps on the river — and rafting by day.\", \"title\": \"Aarti & Rapids\"}]', 'Rishikesh is where ancient yoga meets the modern world — a town of saffron and white-water, ashrams and adventure. It is the world\'s classroom for the art of inner peace.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (48, 'places', 'mahabalipuram', 'Mahabalipuram', 'महाबलीपुरम', 'Stone rathas and a shore temple carved by the Pallava kings', 'Ancient Marvels', '7th – 8th c. CE', 'The Pallava dynasty', 'Mahabalipuram, Tamil Nadu', 12.6166214, 80.1991590, 'Ship', 'from-[#155E75] to-[#0891B2]', 'bg-cyan-50 text-cyan-700 border-cyan-200', 'text-cyan-600', 'Carved by kings, washed by the sea for twelve centuries.', 'A tribute to Mahabalipuram', 'On the shore of the Bay of Bengal, the Pallava kings carved a city of temples in the 7th century — the famous stone rathas, the Shore Temple still braving the waves, and the world\'s largest open-air rock relief. All of it is a UNESCO World Heritage Site.', '[\"Mahabalipuram was the great port city of the Pallava dynasty, which ruled Tamil Nadu in the 7th and 8th centuries. Its masterpiece is the Pancha Rathas — five temples carved from single granite boulders, each shaped like a chariot (ratha) and named after the Pandava brothers of the Mahabharata.\", \"Standing alone on the beach is the Shore Temple, one of the oldest stone temples in South Bhārat — two towers and a shrine that have faced the Bay of Bengal\'s storms and salt for 1,200 years. Nearby, the huge rock relief called the Descent of the Ganges covers two boulders with hundreds of carved figures: gods, elephants, and ascetics.\", \"The port made Pallava kings rich — their ships traded silk and spices across the Bay of Bengal to Southeast Asia, where Pallava art and scripts spread to Cambodia and Indonesia. The whole town is now a UNESCO World Heritage Site, its stone city still standing where the sea meets the land.\"]', '[{\"text\": \"Monolithic temples carved from single granite boulders.\", \"title\": \"The Five Rathas\"}, {\"text\": \"The sea-beaten stone temple that has survived 1,200 years.\", \"title\": \"Shore Temple\"}, {\"text\": \"The world\'s largest open-air rock relief, carved on two boulders.\", \"title\": \"Descent of the Ganges\"}, {\"text\": \"Pallava ships sailed to Southeast Asia with silk and stone.\", \"title\": \"A Great Trading Port\"}, {\"text\": \"The whole stone town is a World Heritage Site.\", \"title\": \"UNESCO Heritage\"}]', 'Mahabalipuram is where ancient art met the sea of Bhārat — a stone city that carried Pallava genius to Southeast Asia and still stands guard over the waves.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (49, 'places', 'statue-of-unity', 'Statue of Unity', 'स्टैच्यू ऑफ यूनिटी', 'The world\'s tallest statue — Sardar Patel, 182 metres of unity', 'Modern Landmarks', 'Unveiled 2018', 'Honouring Sardar Vallabhbhai Patel, the Iron Man of Bhārat', 'Narmada river, Gujarat', 21.8379770, 73.7191640, 'PersonStanding', 'from-[#334155] to-[#64748B]', 'bg-slate-100 text-slate-700 border-slate-200', 'text-slate-600', 'Unity is strength — and here it stands 182 metres tall.', 'A tribute to the Statue of Unity', 'Standing beside the Narmada river in Gujarat, the Statue of Unity is the tallest statue in the world — 182 metres of Sardar Vallabhbhai Patel, the Iron Man who welded 562 princely states into one Bhārat. It is a modern monument to national unity.', '[\"Unveiled in 2018, the Statue of Unity honours Sardar Vallabhbhai Patel — the \'Iron Man of Bhārat\' — whose greatest achievement was persuading 562 princely states to join the Union after Independence, creating a single nation from a patchwork of kingdoms.\", \"At 182 metres, it is nearly twice the height of the Statue of Liberty and the tallest statue on Earth. Built of steel and concrete with a bronze cladding, it stands on an island in the Narmada river, and a glass viewing gallery at its chest offers sweeping views of the Sardar Sarovar Dam and the surrounding valley.\", \"The statue faces the Narmada Dam — fitting, since Patel was also the visionary behind the river-linking and dam projects that would irrigate his home state of Gujarat. Around its base, a museum and exhibition hall tell the story of Patel and the unification of Bhārat, making the monument both a wonder and a history lesson.\"]', '[{\"text\": \"182 metres — nearly twice the height of the Statue of Liberty.\", \"title\": \"World\'s Tallest\"}, {\"text\": \"Sardar Patel, who united 562 princely states into one Bhārat.\", \"title\": \"The Iron Man\"}, {\"text\": \"A modern engineering marvel with a bronze-clad silhouette.\", \"title\": \"Bronze & Steel\"}, {\"text\": \"Set on an island beside the Sardar Sarovar Dam.\", \"title\": \"Above the Narmada\"}, {\"text\": \"A museum at its base tells the story of Patel and unity of Bhārat.\", \"title\": \"A Museum of Unity\"}]', 'The Statue of Unity is a 21st-century wonder with an eternal message: a nation is built when its people stand together. It is Bhārat\'s tallest tribute to its Iron Man — and to the unity he forged.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (50, 'places', 'national-flag', 'The National Flag', 'तिरंगा', 'Saffron, white, and green — the soul of a billion hearts', 'Patriotic Places', 'Adopted 22 July 1947', 'Pingali Venkayya', 'Bhārat', NULL, NULL, 'Flag', 'from-[#F97316] to-[#16A34A]', 'bg-orange-50 text-orange-700 border-orange-200', 'text-orange-600', 'This flag is not made of cloth — it is woven of the hopes and dreams of a nation.', 'A tribute to the Tiranga', 'The Tiranga — three colours and the Ashoka Chakra — is the soul of Bhārat. Saffron for courage, white for peace and truth, green for faith and fertility, and at the centre the wheel of law. It was designed by Pingali Venkayya and adopted on 22 July 1947.', '[\"The tricolour was adopted of Bhārat on 22 July 1947, weeks before Independence. Its design is credited to Pingali Venkayya, an agriculturist and freedom fighter from Andhra Pradesh who first submitted flag designs to the Congress in the 1920s. The flag he designed carries the history of a nation\'s struggle in its folds.\", \"Each element means something: saffron (kesariya) stands for courage and sacrifice, white for peace, truth, and purity, green for faith, fertility, and the land itself. In the centre, the navy-blue Ashoka Chakra — the eternal wheel of law and dharma — replaces the spinning wheel of earlier Congress flags, giving the flag both a modern and an ancient soul.\", \"The flag flies over every government office, school, and embassy — and, since the Flag Code of 2002, any citizen may fly it with pride, any day of the year. Every Independence Day, it rises over the Red Fort; every home hoists it for festivals. Few flags on Earth are as loved as the Tiranga.\"]', '[{\"text\": \"Saffron courage, white peace, green faith and fertility.\", \"title\": \"Three Colours, Three Ideals\"}, {\"text\": \"The navy-blue wheel of dharma at the flag\'s heart.\", \"title\": \"The Ashoka Chakra\"}, {\"text\": \"The freedom fighter whose design became the Tiranga.\", \"title\": \"Pingali Venkayya\"}, {\"text\": \"Chosen on 22 July 1947, before the dawn of freedom.\", \"title\": \"Adopted in 1947\"}, {\"text\": \"Since 2002, every person of Bhārat can fly it with pride all year round.\", \"title\": \"A Flag for Everyone\"}]', 'The Tiranga is the most loved flag on Earth — hoisted on the moon by Chandrayaan\'s payload, carried to the peaks of Everest, and saluted by a billion people. It is the single most powerful symbol of what it means to be a person of Bhārat.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (51, 'places', 'national-emblem', 'The National Emblem', 'राष्ट्रीय प्रतीक', 'Satyameva Jayate — the lion capital that crowns the nation', 'Patriotic Places', 'Adopted 26 January 1950', 'Emperor Ashoka (c. 250 BCE)', 'Sarnath, Uttar Pradesh', NULL, NULL, 'Shield', 'from-[#92400E] to-[#D97706]', 'bg-amber-50 text-amber-700 border-amber-200', 'text-amber-600', 'Satyameva Jayate — Truth alone triumphs.', 'Mundaka Upanishad, inscribed on the emblem', 'Bhārat\'s national emblem is the Lion Capital of Ashoka, carved at Sarnath over 2,200 years ago. Four lions stand back to back, and beneath them runs the motto \'Satyameva Jayate\' — Truth alone triumphs. It appears on every official document, passport, and rupee.', '[\"In the 3rd century BCE, Emperor Ashoka raised a magnificent pillar at Sarnath, where the Buddha had preached his first sermon. Its crowning capital — four lions seated back to back on a drum — was carved from a single block of polished sandstone and became the finest example of Mauryan art.\", \"On 26 January 1950, independent Bhārat adopted this Lion Capital as its national emblem. Only three lions are visible from the front; the fourth is hidden behind. The base shows a chakra (wheel) on each side, flanked by a bull and a horse, echoing the wheels of the emperor\'s law.\", \"Beneath the emblem runs the motto \'Satyameva Jayate\' — \'Truth alone triumphs\' — from the Mundaka Upanishad. The emblem stamps passports, currency notes, government buildings, and the Constitution itself. Wherever you see the lions, you are looking at the authority of the Republic of India.\"]', '[{\"text\": \"Ashoka\'s lion capital, carved 2,200 years ago.\", \"title\": \"From Sarnath, 250 BCE\"}, {\"text\": \"Four lions back to back — only three visible from the front.\", \"title\": \"Four Lions, One Nation\"}, {\"text\": \"The motto of truth, drawn from the Mundaka Upanishad.\", \"title\": \"Satyameva Jayate\"}, {\"text\": \"Passports, currency, and official papers carry the lions.\", \"title\": \"On Every Document\"}, {\"text\": \"Chakras and animals on the base echo Ashoka\'s dharma.\", \"title\": \"The Wheel of Law\"}]', 'The National Emblem connects modern Bhārat directly to the emperor who chose dharma over conquest. It is the face of the republic — carved 2,200 years ago, still standing for truth, justice, and the law.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (52, 'places', 'ashoka-chakra', 'The Ashoka Chakra', 'अशोक चक्र', 'The wheel of law — twenty-four spokes of dharma on the flag', 'Patriotic Places', 'From the Sarnath Lion Capital (c. 250 BCE)', 'Emperor Ashoka\'s dharma chakra', 'From Sarnath, Uttar Pradesh', NULL, NULL, 'Disc', 'from-[#312E81] to-[#4F46E5]', 'bg-indigo-50 text-indigo-700 border-indigo-200', 'text-indigo-600', 'The wheel of dharma never stops — it is the motion of justice itself.', 'A tribute to the Ashoka Chakra', 'At the centre of the flag stands the Ashoka Chakra of Bhārat — the navy-blue wheel with twenty-four spokes, taken from the Lion Capital of Ashoka. It replaced the spinning wheel in 1947 and stands for the eternal wheel of law, dharma, and progress.', '[\"The original chakra was carved at Sarnath 2,250 years ago as part of Ashoka\'s Lion Capital — the emperor\'s symbol of dharma, the righteous law he promised to rule by. The wheel, ever-rolling, meant that dharma was never static: it moves forward, like justice itself.\", \"When Pingali Venkayya\'s flag design was revised in 1947, the spinning wheel (charkha) of the Congress flags was replaced by the Ashoka Chakra — a change that kept the flag connected to Gandhian self-rule while giving it an even older symbol of law and righteousness. The chakra was approved on 22 July 1947.\", \"The chakra\'s twenty-four spokes are sometimes read as the twenty-four hours of the day — a reminder that Bhārat is always awake and always in motion. The chakra also names Bhārat\'s highest peacetime gallantry award: the Ashoka Chakra, given for valour away from the battlefield.\"]', '[{\"text\": \"The eternal wheel, said to mark every hour of the day.\", \"title\": \"Twenty-Four Spokes\"}, {\"text\": \"Carved on Ashoka\'s pillar 2,250 years ago.\", \"title\": \"From Sarnath\"}, {\"text\": \"Law and righteousness in eternal motion.\", \"title\": \"Wheel of Dharma\"}, {\"text\": \"The 1947 flag swapped the spinning wheel for the chakra.\", \"title\": \"Replaced the Charkha\"}, {\"text\": \"Bhārat\'s highest peacetime gallantry award bears its name.\", \"title\": \"A Medal of Valour\"}]', 'The Ashoka Chakra is the heartbeat of the flag — a 2,000-year-old wheel of law spinning at the centre of a modern republic. It reminds every person of Bhārat that justice is not a resting place but a journey.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (53, 'places', 'national-pledge', 'The National Pledge', 'राष्ट्रीय प्रतिज्ञा', 'The promise every schoolchild makes of Bhārat', 'Patriotic Places', 'Written 1962', 'Pydimarri Venkata Subba Rao', 'Written in Telugu, recited across Bhārat', NULL, NULL, 'ClipboardCheck', 'from-[#475569] to-[#94A3B8]', 'bg-slate-100 text-slate-700 border-slate-200', 'text-slate-600', 'Bhārat is my country. All people of Bhārat are my brothers and sisters.', 'The National Pledge, first line', 'Every morning in schools across Bhārat, millions of children recite the National Pledge — a promise of unity, honesty, and love for the motherland. It was written in Telugu in 1962 by Pydimarri Venkata Subba Rao and translated into every language of Bhārat.', '[\"The National Pledge was written in 1962 by Pydimarri Venkata Subba Rao, a Telugu writer from what is now Telangana. He composed it at the request of a school in Vishakhapatnam, and its simple, soaring lines — \'Bhārat is my country. All people of Bhārat are my brothers and sisters\' — caught on instantly.\", \"The pledge is a promise: to love my country, to do my duty, to be truthful and kind, to respect parents, teachers, and elders, and to cherish the nation\'s honour and glory. It was translated from Telugu into all languages so that every child of Bhārat could say it in their mother tongue.\", \"Today it is recited at school assemblies, Independence Day and Republic Day ceremonies across the country. It is perhaps the most spoken patriotic text in Bhārat — a daily ritual that has been shaping young citizens for over sixty years.\"]', '[{\"text\": \"Composed by P.V. Subba Rao for a school in Andhra.\", \"title\": \"Written in 1962\"}, {\"text\": \"\'All people of Bhārat are my brothers and sisters\' — the opening vow.\", \"title\": \"Unity First\"}, {\"text\": \"Recited in schools every morning across the country.\", \"title\": \"A Daily Ritual\"}, {\"text\": \"Translated into all mother tongues of Bhārat.\", \"title\": \"In Every Language\"}, {\"text\": \"Truth, kindness, respect, and love for the motherland.\", \"title\": \"Honour & Duty\"}]', 'The National Pledge has shaped generations of citizens of Bhārat — a minute of promise every morning that turns schoolchildren into patriots. It is the quiet ritual that holds the nation together.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (54, 'places', 'national-anthem', 'The National Anthem', 'जन गण मन', 'The song that wakes a nation — 52 seconds of unity', 'Patriotic Places', 'Written 1911; adopted 24 January 1950', 'Rabindranath Tagore', 'Written in Bengali, honoured across Bhārat', NULL, NULL, 'Music2', 'from-[#1E40AF] to-[#3B82F6]', 'bg-blue-50 text-blue-700 border-blue-200', 'text-blue-600', 'Jana Gana Mana Adhinayaka Jaya He — the anthem of a billion voices.', 'The National Anthem', 'Jana Gana Mana, written by Rabindranath Tagore and adopted as Bhārat\'s National Anthem on 24 January 1950, is the song that every person of Bhārat stands for. It speaks of a land bound together from the Himalayas to the southern seas.', '[\"Rabindranath Tagore composed \'Jana Gana Mana\' in Bengali, first sung in 1911 at the Calcutta session of the Indian National Congress. In 1919, Tagore himself translated it into English as \'The Morning Song of Bhārat\'. Its opening line hails the \'ruler of the minds of the people\' — a land, not a king.\", \"The anthem describes Bhārat\'s geography as one sweep of devotion: from the Punjab to Bengal, from Gujarat to the hills of the south, from the Ganga to the seven rivers of the Deccan. It is a song about the land itself — its mountains, rivers, and the unity that binds them.\", \"On 24 January 1950, the Constituent Assembly adopted it as the National Anthem, with the full version taking about 52 seconds to sing. It is played at every official function, every school assembly, and every medal ceremony — the moment when a billion people stand together in silence and pride.\"]', '[{\"text\": \"Written by Rabindranath Tagore in 1911.\", \"title\": \"Tagore\'s Song\"}, {\"text\": \"Hailing the ruler of the minds of the people — the nation itself.\", \"title\": \"The Land, Not the King\"}, {\"text\": \"The full anthem takes about 52 seconds to sing.\", \"title\": \"52 Seconds\"}, {\"text\": \"Chosen by the Constituent Assembly on 24 January 1950.\", \"title\": \"Adopted in 1950\"}, {\"text\": \"From the Punjab to the southern hills — unity in every verse.\", \"title\": \"One Land, One Voice\"}]', 'Jana Gana Mana is the most sung anthem on Earth, recited by over a billion people. Written by a poet who also wrote Bangladesh\'s anthem, it is Bhārat\'s daily reminder that a billion voices can sing as one.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (55, 'places', 'vande-mataram', 'The National Song — Vande Mataram', 'वंदे मातरम', 'Hail to the Mother — the song that stirred the freedom struggle', 'Patriotic Places', 'Written 1870s; published 1882', 'Bankim Chandra Chatterjee', 'From Bengal, beloved across Bhārat', NULL, NULL, 'Flower', 'from-[#BE123C] to-[#F43F5E]', 'bg-rose-50 text-rose-700 border-rose-200', 'text-rose-600', 'Vande Mataram — a motherland is a mother indeed.', 'The National Song, Bankim Chandra Chatterjee', 'Vande Mataram — \'I bow to thee, Mother\' — was written by Bankim Chandra Chatterjee and became the war cry of Bhārat\'s freedom movement. It holds equal honour with the National Anthem, and its first two lines are the National Song of Bhārat.', '[\"Bankim Chandra Chatterjee wrote the poem \'Vande Mataram\' in the 1870s, publishing it in 1882 in his novel Anandamath — set in the time of a great rebellion in Bengal. In the novel, a band of monks sings it before battle: the motherland is the Mother, and to free her is the highest duty.\", \"The song\'s opening words — \'Vande Mataram, Sujalam, Sufalam, Malayaja Shitalam\' — describe the motherland with all her abundance: fruitful, flowing with rivers, cool with winds. It made the nation itself a goddess to be worshipped, and the freedom struggle adopted it as its anthem of the heart.\", \"The British banned it, and singing it could mean prison — so people of Bhārat sang it louder. When the Constituent Assembly debated national songs in 1950, it gave the anthem and Vande Mataram equal honour. Today it is sung with the anthem at national events, and its first two stanzas hold the title of National Song.\"]', '[{\"text\": \"Bankim Chandra\'s 1882 novel gave the struggle its song.\", \"title\": \"From Anandamath\"}, {\"text\": \"The nation as the Mother — to free her is the highest duty.\", \"title\": \"Mother as Motherland\"}, {\"text\": \"Singing it could mean prison — so people of Bhārat sang it louder.\", \"title\": \"The British Ban\"}, {\"text\": \"The Constituent Assembly gave it equal status with the anthem.\", \"title\": \"Equal Honour\"}, {\"text\": \"Its first two stanzas are Bhārat\'s official National Song.\", \"title\": \"The National Song\"}]', 'Vande Mataram is the cry that launched a hundred years of struggle. From Bankim Chandra\'s pen to the lips of revolutionaries, it turned the map of Bhārat into a mother\'s face — and no song did more to win her freedom.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (56, 'places', 'saare-jahan-se-achha', 'Saare Jahan Se Achha', 'सारे जहां से अच्छा', 'Better than all the world — the beloved song of Hindustan', 'Patriotic Places', 'Written 1904', 'Muhammad Iqbal', 'Written in Urdu, loved across Bhārat', NULL, NULL, 'Globe', 'from-[#0F766E] to-[#14B8A6]', 'bg-teal-50 text-teal-700 border-teal-200', 'text-teal-600', 'Saare jahan se achha, Hindustan hamara — better than all the world is our Hindustan.', 'First lines of the song', 'Written in 1904 by the poet Muhammad Iqbal, \'Saare Jahan Se Achha\' is the most beloved patriotic song in the Urdu-Hindi tradition. For over a century it has been sung at every patriotic occasion — a hymn of love for the land of Hindustan.', '[\"In 1904, a young poet named Muhammad Iqbal — later honoured as Allama Iqbal — composed a ghazal in Urdu that began with the line \'Saare jahan se achha, Hindustan hamara\' — \'Better than all the world is our Hindustan.\' It appeared in his first book and soon travelled across the subcontinent by word of mouth.\", \"The song paints the nation as a garden of many flowers: \'Hindustan humari — hum hain iske, yeh hai humara\' — we are its, and it is ours. Its verses praise the mountains of the Himalaya, the Ganga\'s waters, and the unity of a land where all religions live as one family.\", \"Singers, soldiers, and schoolchildren have sung it for over 120 years. It is played at military bands, at Independence Day gatherings, and in countless films. Written in Urdu, loved in every language, it remains one of the few songs that can make the whole of Bhārat stop and sing together.\"]', '[{\"text\": \"Written by Muhammad Iqbal when he was a young poet.\", \"title\": \"Iqbal, 1904\"}, {\"text\": \"The nation as a garden where every community blooms.\", \"title\": \"A Garden of Flowers\"}, {\"text\": \"Sung and loved for over 120 years.\", \"title\": \"A Century Old\"}, {\"text\": \"Verses that praise the land\'s mountains and rivers.\", \"title\": \"Himalaya & Ganga\"}, {\"text\": \"Military bands, schools, and films — one voice for the land.\", \"title\": \"Everyone\'s Song\"}]', 'Saare Jahan Se Achha is the unofficial anthem of Bhārat — a song that crosses languages and faiths to reach the same heart. It proves that patriotism in Bhārat is not one voice but a chorus.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (57, 'places', 'independence-day', 'Independence Day', 'स्वतंत्रता दिवस', 'The day Bhārat woke to freedom — 15 August 1947', 'Patriotic Places', '15 August 1947 – present', 'Won by the freedom struggle; declared by Nehru', 'Celebrated across Bhārat', NULL, NULL, 'Sunrise', 'from-[#B45309] to-[#F59E0B]', 'bg-amber-50 text-amber-700 border-amber-200', 'text-amber-600', 'A moment comes, which comes but rarely in history, when we step out from the old to the new.', 'Jawaharlal Nehru, 15 August 1947', 'On 15 August 1947, Bhārat ended 200 years of British rule and woke to freedom. At the stroke of midnight, Nehru\'s \'Tryst with Destiny\' speech announced the birth of a free nation — and every year since, the tricolour rises over the Red Fort.', '[\"At the stroke of midnight on 15 August 1947, Bhārat became free. In a hall lit for the occasion, Jawaharlal Nehru rose to deliver the \'Tryst with Destiny\' speech: \'At the stroke of the midnight hour, when the world sleeps, Bhārat will awake to life and freedom.\' The moment had been paid for by a century of struggle — from the 1857 uprising to the salt marches.\", \"The next morning, Nehru hoisted the tricolour at the Red Fort in Delhi for the first time, and the tradition has never stopped. Every 15 August since, the Prime Minister raises the flag, the national anthem plays, and guns thunder in a 21-gun salute while the nation listens on radio and television.\", \"Independence Day is a day of joy: kites fill the sky across North Bhārat, homes are decorated, sweets are distributed, and schools hold flag-hoisting ceremonies and plays about the freedom fighters. The 75th anniversary in 2022 was celebrated as the Azadi Ka Amrit Mahotsav — the festival of freedom\'s nectar.\"]', '[{\"text\": \"The day Bhārat woke to freedom, ending 200 years of rule.\", \"title\": \"15 August 1947\"}, {\"text\": \"Nehru\'s midnight speech that announced a free nation.\", \"title\": \"Tryst with Destiny\"}, {\"text\": \"The annual hoisting by the Prime Minister, since 1947.\", \"title\": \"Flag at the Red Fort\"}, {\"text\": \"The sky fills with kites — a day of celebration and colour.\", \"title\": \"Kites in the Sky\"}, {\"text\": \"75 years of freedom, celebrated in 2022.\", \"title\": \"Amrit Mahotsav\"}]', 'Independence Day is the birthday of the republic of Bhārat — the day a billion people remember that freedom is never free, and that a nation\'s greatness begins with gratitude for those who won it.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (58, 'places', 'republic-day', 'Republic Day', 'गणतंत्र दिवस', 'The day the Constitution gave Bhārat her soul — 26 January', 'Patriotic Places', '26 January 1950 – present', 'The Constituent Assembly; the Constitution of Bhārat', 'Celebrated across Bhārat; parade in Delhi', NULL, NULL, 'Landmark', 'from-[#4338CA] to-[#6366F1]', 'bg-indigo-50 text-indigo-700 border-indigo-200', 'text-indigo-600', 'We, the people of Bhārat, having solemnly resolved to constitute Bhārat into a sovereign socialist secular democratic republic...', 'The Preamble of the Constitution', 'On 26 January 1950, the Constitution of Bhārat came into force and Bhārat became a republic — a nation that rules itself. The date was chosen to honour the Purna Swaraj declaration of 1930, and it is marked by the grand Republic Day parade.', '[\"On 26 January 1950, the Constitution drafted under Dr. B.R. Ambedkar came into force, replacing British-era laws and declaring Bhārat a sovereign, democratic republic. The date was no accident: it was chosen because 26 January 1930 was the day the Congress had first declared Purna Swaraj — complete independence.\", \"The Constitution is the longest written constitution of any nation, and its Preamble begins \'We, the people of Bhārat\' — a promise that power belongs to the people. Its 395 articles (as first written) guarantee rights, duties, and the democratic machinery of the world\'s largest republic.\", \"Every 26 January, Delhi hosts the Republic Day parade down Kartavya Path: the President unfurls the flag, regiments march, tanks roll past, schoolchildren dance, and tableaux from every state roll by. The celebrations end with the Beating Retreat ceremony, and the sky above Bhārat fills with the tricolour.\"]', '[{\"text\": \"The Constitution came into force and Bhārat became a republic.\", \"title\": \"26 January 1950\"}, {\"text\": \"The date honours the 1930 declaration of complete independence.\", \"title\": \"Purna Swaraj Link\"}, {\"text\": \"The Preamble\'s promise — power belongs to the people.\", \"title\": \"We, the People\"}, {\"text\": \"Marching regiments, tanks, tableaux, and children\'s dances.\", \"title\": \"The Grand Parade\"}, {\"text\": \"The ceremony that closes the Republic Day celebrations.\", \"title\": \"Beating Retreat\"}]', 'Republic Day is the day Bhārat\'s soul was written down — the promise that every citizen is equal before the law. It is the birthday of democracy of Bhārat, the largest in the world.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (59, 'places', 'national-animal-tiger', 'The National Animal — Royal Bengal Tiger', 'बाघ', 'The striped lord of the jungle — Bhārat\'s national animal', 'Patriotic Places', 'Declared 1973', 'The Government of Bhārat, Project Tiger', 'Found across Bhārat\'s forests', NULL, NULL, 'PawPrint', 'from-[#7C2D12] to-[#EA580C]', 'bg-orange-50 text-orange-700 border-orange-200', 'text-orange-600', 'The tiger is the soul of the forest of Bhārat — where it thrives, all thrives.', 'A tribute to Bhārat\'s national animal', 'The Royal Bengal tiger was declared Bhārat\'s national animal in 1973, the year Project Tiger began. With its stripes, its strength, and its silent grace, the tiger is the spirit of Bhārat\'s wild — and Bhārat is now home to about seventy percent of the world\'s wild tigers.', '[\"In 1973, the government declared the tiger of Bhārat the national animal and launched Project Tiger, creating nine tiger reserves to protect a species pushed to the edge of extinction. It was one of the first great conservation movements in the world — and Bhārat chose the tiger to carry the nation\'s name.\", \"The tiger stands for strength, power, and grace — qualities Bhārat has always admired. The Royal Bengal tiger is the largest cat species on Earth, an apex predator whose striped coat is as individual as a fingerprint. Its roar can be heard over two kilometres away.\", \"Today Bhārat protects tigers in over fifty reserves — from Corbett in the foothills of the Himalaya to the Sundarbans in the east. The tiger\'s recovery is one of conservation\'s greatest success stories: from fewer than 1,500 in 2006 to nearly 4,000 today — more than two-thirds of the world\'s wild tigers live in Bhārat.\"]', '[{\"text\": \"Declared the same year Project Tiger began.\", \"title\": \"National Animal, 1973\"}, {\"text\": \"The largest cat on Earth, with a unique striped coat.\", \"title\": \"Strength & Grace\"}, {\"text\": \"About 70% of the world\'s wild tigers live in Bhārat.\", \"title\": \"Bhārat\'s Tiger Majority\"}, {\"text\": \"From Corbett to the Sundarbans, tigers roam protected forests.\", \"title\": \"50+ Reserves\"}, {\"text\": \"Numbers have more than doubled since 2006.\", \"title\": \"A Conservation Miracle\"}]', 'The tiger is Bhārat\'s wild heart — the emblem on the nation\'s stamps, shields, and sports teams. Its comeback is proof that when a country decides to protect its soul, the soul comes back.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (60, 'places', 'national-bird-peacock', 'The National Bird — Peacock of Bhārat', 'मोर', 'The dancing rainbow bird of skies of Bhārat', 'Patriotic Places', 'Declared 1963', 'The Government of Bhārat', 'Found across Bhārat', NULL, NULL, 'Feather', 'from-[#134E4A] to-[#0D9488]', 'bg-teal-50 text-teal-700 border-teal-200', 'text-teal-600', 'The peacock dances, and the monsoon listens.', 'A tribute to Bhārat\'s national bird', 'The peacock of Bhārat — mayura — was declared the national bird in 1963 for its grace, colour, and deep place in culture of Bhārat. It is the mount of Kartikeya, the feather in Krishna\'s crown, and the dancer that welcomes the monsoon.', '[\"Bhārat chose the peacock as its national bird in 1963 for a simple reason: no other bird captures the beauty of Bhārat. The male\'s iridescent tail — a fan of a hundred eye-spotted feathers — is one of the most dazzling displays in nature, used to court the peahen in a dance that stops traffic and tourists alike.\", \"The peacock is woven into life of Bhārat. It is the vahana (mount) of Kartikeya, the god of war; its feather adorns the crown of Krishna; its image appears on temple walls, royal thrones, and Mughal miniature paintings. The Mauryan emblem and countless motifs carry its image of Bhārat.\", \"Peacocks are protected under the Wildlife of Bhārat Act and can be seen across the country — in villages, temple grounds, and forests. Before the rains, the male fans out his train and dances, and people of Bhārat say he is calling the monsoon. When the sky darkens and the peacock dances, the year itself feels renewed.\"]', '[{\"text\": \"Chosen for grace, colour, and cultural importance.\", \"title\": \"National Bird, 1963\"}, {\"text\": \"A tail of a hundred eye-spotted feathers.\", \"title\": \"The Dancing Fan\"}, {\"text\": \"The peacock is woven into myth and art of Bhārat.\", \"title\": \"Krishna\'s Feather\"}, {\"text\": \"Its dance is said to summon the monsoon.\", \"title\": \"The Rain Caller\"}, {\"text\": \"Safeguarded under the Wildlife of Bhārat Act.\", \"title\": \"Protected by Law\"}]', 'The peacock is Bhārat\'s living jewel — a bird that dances through myth, monsoon, and modern gardens alike. As the national bird, it carries the beauty of Bhārat on its feathered fan.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (61, 'places', 'national-flower-lotus', 'The National Flower — Lotus', 'कमल', 'The flower of purity that blooms above the mud', 'Patriotic Places', 'Adopted 1947', 'The Government of Bhārat', 'Found in ponds and lakes across Bhārat', NULL, NULL, 'Flower2', 'from-[#DB2777] to-[#F472B6]', 'bg-pink-50 text-pink-700 border-pink-200', 'text-pink-600', 'From the mud rises the lotus — purity, patience, and grace.', 'A tribute to the national flower', 'The lotus — kamal — is Bhārat\'s national flower, sacred and central to culture for thousands of Bhārat of years. It blooms flawless and fragrant from the muddiest water, and that is the lesson Bhārat loves: purity rising above the world, untouched by it.', '[\"The lotus was adopted as Bhārat\'s national flower in 1947, joining the earliest set of national symbols chosen by the new nation. But its story is far older: the lotus appears in the Rigveda, on Indus Valley seals, and in every temple and sculpture tradition of Bhārat.\", \"The lotus\'s biology is its philosophy. It grows in murky water, yet its flower rises above the surface, clean, unstained, and beautiful. thought took this of Bhārat as the perfect image of the soul: living in the world yet not stained by it. Gods and goddesses sit on lotus thrones; the Buddha and Lakshmi are lotus-born.\", \"Today the lotus still blooms across Bhārat\'s ponds and lakes — and on the nation\'s symbols. It names Bhārat\'s biggest political party and countless institutions, its petals appear in art from Ajanta to the modern logo, and its lesson — rise above the mud — is the national flower\'s quiet sermon.\"]', '[{\"text\": \"Among the first national symbols of free Bhārat.\", \"title\": \"Adopted 1947\"}, {\"text\": \"Bloom clean from murky water — the soul\'s perfect image.\", \"title\": \"Purity in Mud\"}, {\"text\": \"Lakshmi, Saraswati, and the Buddha sit on lotus thrones.\", \"title\": \"Thrones of the Gods\"}, {\"text\": \"From Indus seals and Ajanta to modern logos.\", \"title\": \"A Symbol of Art\"}, {\"text\": \"Kamal — the flower that names institutions and parties.\", \"title\": \"The National Flower\"}]', 'The lotus is Bhārat\'s favourite metaphor — a flower that turned into a philosophy. As the national flower, it tells every person of Bhārat: however deep the mud, you can still rise, open, and shine.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppcollection_items (id, type, slug, name, native_name, tagline, category, era, attribution, region, latitude, longitude, icon, accent, soft_accent, icon_color, quote, quote_source, summary, overview, core_ideas, legacy, created_at, updated_at) VALUES (62, 'places', 'national-tree-banyan', 'The National Tree — Banyan', 'बरगद', 'The great banyan — the tree that is a forest of one', 'Patriotic Places', 'Declared the national tree', 'A native tree of Bhārat, sacred for millennia', 'Found across Bhārat', NULL, NULL, 'TreeDeciduous', 'from-[#14532D] to-[#16A34A]', 'bg-green-50 text-green-700 border-green-200', 'text-green-600', 'Under the banyan, generations have sat and learned.', 'A tribute to the national tree', 'The banyan — the vatavriksha — is Bhārat\'s national tree, chosen for its extraordinary longevity and its place at the heart of village life of Bhārat. One tree can spread into a forest, and one banyan can shelter an entire community beneath its shade.', '[\"The banyan (Ficus benghalensis) is the national tree of Bhārat, a native fig whose branches send down aerial roots that grow into new trunks. Over centuries, one tree can become a forest — the famous Great Banyan in Kolkata\'s botanical garden is more than 250 years old and covers several acres.\", \"In villages of Bhārat, the banyan is the heart of the community: the panchayat meets under it, children learn under it, travellers rest in its shade, and festivals are celebrated beneath its canopy. The tree is sacred — Krishna is said to have rested under a banyan, and sages have meditated in its shade since the Upanishads.\", \"Its longevity made it the perfect national symbol: a tree that lives for hundreds of years, shelters everyone equally, and grows ever larger without ever losing its roots. The banyan teaches the nation its own ideal — deep roots, wide shade, and a family that becomes a forest.\"]', '[{\"text\": \"Aerial roots turn a single tree into an entire grove.\", \"title\": \"A Forest of One\"}, {\"text\": \"Panchayats, schools, and festivals under its shade.\", \"title\": \"The Village Heart\"}, {\"text\": \"The tree of sages, Krishna, and the Upanishads.\", \"title\": \"Sacred for Millennia\"}, {\"text\": \"Kolkata\'s 250-year-old giant spans several acres.\", \"title\": \"The Great Banyan\"}, {\"text\": \"The national ideal: deep roots, wide shade, long life.\", \"title\": \"Roots and Longevity\"}]', 'The banyan is the soul of the village of Bhārat — a tree that shelters all equally and never stops growing. As the national tree, it reminds Bhārat that strength is not one trunk but a thousand roots standing together.', '2026-08-10 14:36:39', '2026-08-13 21:55:16') ON DUPLICATE KEY UPDATE name = VALUES(name), native_name = VALUES(native_name), tagline = VALUES(tagline), category = VALUES(category), era = VALUES(era), attribution = VALUES(attribution), region = VALUES(region), latitude = VALUES(latitude), longitude = VALUES(longitude), icon = VALUES(icon), accent = VALUES(accent), soft_accent = VALUES(soft_accent), icon_color = VALUES(icon_color), quote = VALUES(quote), quote_source = VALUES(quote_source), summary = VALUES(summary), overview = VALUES(overview), core_ideas = VALUES(core_ideas), legacy = VALUES(legacy), updated_at = VALUES(updated_at);
INSERT INTO ppgames (id, title, tagline, description, path, tags, accent, badge, created_at, updated_at) VALUES (1, 'Pachisi', 'Twenty-Five — the royal game of the Mahabharata', 'The legendary cross-board race of ancient Bhārat — the game of the great gambling match in the Mahabharata. Cast the dala (ದಾಳ) — a Kannada cuboid die — race four beehive pieces around the sacred cross, capture your rivals on the way, and be the first to bring every piece home to the Charkoni. Play hot-seat with 2, 3, or 4 players.', '/play/pachisi', '[{\"icon\": \"Dices\", \"label\": \"Cuboid dala die\"}, {\"icon\": \"Users\", \"label\": \"2–4 players\"}, {\"icon\": \"Swords\", \"label\": \"Capture & grace throws\"}, {\"icon\": \"Shield\", \"label\": \"12 castle squares\"}, {\"icon\": \"Castle\", \"label\": \"Cross-board race\"}]', 'from-[#2a1220] to-[#4a2430]', '★ Mahabharata', '2026-08-10 14:36:40', '2026-08-10 14:55:15') ON DUPLICATE KEY UPDATE title = VALUES(title), tagline = VALUES(tagline), description = VALUES(description), path = VALUES(path), tags = VALUES(tags), accent = VALUES(accent), badge = VALUES(badge), updated_at = VALUES(updated_at);
INSERT INTO ppgames (id, title, tagline, description, path, tags, accent, badge, created_at, updated_at) VALUES (2, 'Chaukabaara', 'The ancient game of strategy of Bhārat & luck', 'Race your cowrie-shell dice across a square board in this two-thousand-year-old game of ancient Bhārat. Play with 2, 3, or 4 players on a 5-house or 7-house board — against friends online or around the same screen.', '/play/chaukabaara', '[{\"icon\": \"Users\", \"label\": \"2–4 players\"}, {\"icon\": \"Castle\", \"label\": \"5 & 7 house boards\"}, {\"icon\": \"Wifi\", \"label\": \"Online rooms\"}, {\"icon\": \"Monitor\", \"label\": \"Hot-seat local\"}, {\"icon\": \"Shell\", \"label\": \"Cowrie shell dice\"}]', 'from-[#0A2240] to-[#1F3D5E]', '★ Ancient Bhārat', '2026-08-10 14:36:40', '2026-08-10 14:55:15') ON DUPLICATE KEY UPDATE title = VALUES(title), tagline = VALUES(tagline), description = VALUES(description), path = VALUES(path), tags = VALUES(tags), accent = VALUES(accent), badge = VALUES(badge), updated_at = VALUES(updated_at);
INSERT INTO ppgames (id, title, tagline, description, path, tags, accent, badge, created_at, updated_at) VALUES (3, 'Aadu Puli Aatam', 'Goats & Tigers — the classic hunt of Tamil Nadu', 'Three tigers stalk fifteen goats on the temple triangle of Tamil Nadu. Place and move your goats to surround the tigers — or hunt them down, one leap at a time. Play hot-seat or challenge the computer.', '/play/aadu-puli-aatam', '[{\"icon\": \"Swords\", \"label\": \"3 tigers vs 15 goats\"}, {\"icon\": \"Bot\", \"label\": \"Vs computer\"}, {\"icon\": \"Monitor\", \"label\": \"Hot-seat local\"}, {\"icon\": \"Users\", \"label\": \"2 players\"}, {\"icon\": \"Shield\", \"label\": \"Pure strategy\"}]', 'from-[#0C2419] to-[#1F4A33]', '★ South Bhārat', '2026-08-10 14:36:40', '2026-08-10 14:55:15') ON DUPLICATE KEY UPDATE title = VALUES(title), tagline = VALUES(tagline), description = VALUES(description), path = VALUES(path), tags = VALUES(tags), accent = VALUES(accent), badge = VALUES(badge), updated_at = VALUES(updated_at);
INSERT INTO ppgames (id, title, tagline, description, path, tags, accent, badge, created_at, updated_at) VALUES (4, 'Chaturvimshati Koṣṭaka', 'Twenty-Four Squares — the game of Krīḍākauśalya', 'From the ancient Sanskrit text Krīḍākauśalya: eight ivory soldiers against eight crimson across a 3×8 board of twenty-four squares. Step sideways or leap over the enemy — capture them all, or trap them with no move left. Play hot-seat, vs the computer, or online.', '/play/chaturvimshati', '[{\"icon\": \"LayoutGrid\", \"label\": \"3×8 board · 24 squares\"}, {\"icon\": \"Users\", \"label\": \"2 players\"}, {\"icon\": \"Bot\", \"label\": \"Vs computer\"}, {\"icon\": \"Wifi\", \"label\": \"Online rooms\"}, {\"icon\": \"Shield\", \"label\": \"Pure strategy\"}]', 'from-[#1d1026] to-[#3a1f4a]', '★ Krīḍākauśalya', '2026-08-10 14:36:40', '2026-08-10 14:55:15') ON DUPLICATE KEY UPDATE title = VALUES(title), tagline = VALUES(tagline), description = VALUES(description), path = VALUES(path), tags = VALUES(tags), accent = VALUES(accent), badge = VALUES(badge), updated_at = VALUES(updated_at);
INSERT INTO ppgames (id, title, tagline, description, path, tags, accent, badge, created_at, updated_at) VALUES (5, 'Vish & Amrit', 'Poison & Nectar — the ancient freeze-tag chase', 'One player is Vish, the poison, hunting three fleeing runners across a 7×7 board. Touch a runner and they freeze into a Statue — but a runner who ends their move touching a statue cries “Amrit!” and frees them. Freeze all three, or survive 60 rounds. Play hot-seat, vs the computer, or online.', '/play/vish-amrit', '[{\"icon\": \"Skull\", \"label\": \"1 Vish vs 3 runners\"}, {\"icon\": \"Zap\", \"label\": \"Amrit release\"}, {\"icon\": \"Bot\", \"label\": \"Vs computer\"}, {\"icon\": \"Wifi\", \"label\": \"Online rooms\"}, {\"icon\": \"Users\", \"label\": \"2 players\"}]', 'from-[#0F1912] to-[#2A4A32]', '★ Poison & Nectar', '2026-08-10 14:36:40', '2026-08-10 14:55:15') ON DUPLICATE KEY UPDATE title = VALUES(title), tagline = VALUES(tagline), description = VALUES(description), path = VALUES(path), tags = VALUES(tags), accent = VALUES(accent), badge = VALUES(badge), updated_at = VALUES(updated_at);
