USE gavynomv_pp_backend;

CREATE TABLE IF NOT EXISTS ppcollection_items (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  type VARCHAR(255) NOT NULL,
  slug VARCHAR(255) NOT NULL,
  name VARCHAR(255) NOT NULL,
  native_name VARCHAR(255) NULL,
  tagline VARCHAR(255) NULL,
  category VARCHAR(255) NULL,
  era VARCHAR(255) NULL,
  attribution VARCHAR(255) NULL,
  region VARCHAR(255) NULL,
  latitude DECIMAL(10,7) NULL,
  longitude DECIMAL(10,7) NULL,
  icon VARCHAR(255) NULL,
  accent VARCHAR(255) NULL,
  soft_accent VARCHAR(255) NULL,
  icon_color VARCHAR(255) NULL,
  quote VARCHAR(255) NULL,
  quote_source VARCHAR(255) NULL,
  summary TEXT NULL,
  overview JSON NULL,
  core_ideas JSON NULL,
  legacy TEXT NULL,
  created_at TIMESTAMP NULL,
  updated_at TIMESTAMP NULL,
  PRIMARY KEY (id),
  UNIQUE KEY collection_items_type_slug_unique (type, slug),
  KEY collection_items_type_index (type),
  KEY collection_items_category_index (category)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS ppgames (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  title VARCHAR(255) NOT NULL,
  tagline VARCHAR(255) NULL,
  description TEXT NULL,
  path VARCHAR(255) NULL,
  tags JSON NULL,
  accent VARCHAR(255) NULL,
  badge VARCHAR(255) NULL,
  created_at TIMESTAMP NULL,
  updated_at TIMESTAMP NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

